Use a ternary expression inside `className`:

```jsx
Object.keys(row).filter((key) => key !== "id").map((key) => {
  return (
    <TableCell
      className={row[key] === "error" ? "error-cell" : ""}
      key={key}
    >
      {row[key]}
    </TableCell>
  );
})
```

If you also want to keep a base class alongside the conditional one:

```jsx
className={`cell ${row[key] === "error" ? "error-cell" : ""}`}
```

Or, if you prefer a helper to avoid the empty-string clutter:

```jsx
const cx = (...classes) => classes.filter(Boolean).join(" ");

// ...
className={cx("cell", row[key] === "error" && "error-cell")}
```

All three approaches render the same HTML — the class is only present when the value is `"error"`.

# Go Web Server with GET & POST Handlers

## Scratchpad: Design

```
┌─────────────────────────────────────────────────────────────────┐
│  SERVER STRUCTURE                                               │
├─────────────────────────────────────────────────────────────────┤
│                                                                 │
│  main()                                                         │
│    ├── NewServer() → *Server                                    │
│    │     ├── users map + sync.RWMutex                           │
│    │     └── seed initial data                                  │
│    ├── server.SetupRoutes() → http.Handler                      │
│    │     ├── middleware: Logging → CORS → Router                │
│    │     └── http.ServeMux (Go 1.22+ patterns)                 │
│    └── server.Start(":8080")                                   │
│                                                                 │
├─────────────────────────────────────────────────────────────────┤
│  API ENDPOINTS                                                  │
├─────────────────────────────────────────────────────────────────┤
│                                                                 │
│  GET    /                      → health check                   │
│  GET    /api/users             → list all users                 │
│  GET    /api/users/{id}        → get single user                │
│  POST   /api/users             → create user                    │
│  POST   /api/users/{id}        → update user                    │
│                                                                 │
├─────────────────────────────────────────────────────────────────┤
│  MODELS                                                         │
├─────────────────────────────────────────────────────────────────┤
│                                                                 │
│  User { ID, Name, Email, CreatedAt }                           │
│  APIResponse { Status, Message, Data }                          │
│                                                                 │
└─────────────────────────────────────────────────────────────────┘
```

## Implementation

```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"
)

// ─────────────────────────────────────────────
// Models
// ─────────────────────────────────────────────

type User struct {
	ID        int       `json:"id"`
	Name      string    `json:"name"`
	Email     string    `json:"email"`
	CreatedAt time.Time `json:"created_at"`
}

type APIResponse struct {
	Status  string      `json:"status"`
	Message string      `json:"message"`
	Data    interface{} `json:"data,omitempty"`
}

// ─────────────────────────────────────────────
// Server
// ─────────────────────────────────────────────

type Server struct {
	mu     sync.RWMutex
	users  map[int]User
	nextID int
}

func NewServer() *Server {
	s := &Server{
		users:  make(map[int]User),
		nextID: 1,
	}

	// Seed with sample data
	s.seed()
	return s
}

func (s *Server) seed() {
	now := time.Now()
	s.users[1] = User{ID: 1, Name: "Alice", Email: "alice@example.com", CreatedAt: now}
	s.users[2] = User{ID: 2, Name: "Bob", Email: "bob@example.com", CreatedAt: now}
	s.nextID = 3
}

// ─────────────────────────────────────────────
// Middleware
// ─────────────────────────────────────────────

func (s *Server) loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("[%s] %s %s — %s",
			r.Method, r.URL.Path, r.RemoteAddr, time.Since(start))
	})
}

func (s *Server) corsMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Content-Type")

		if r.Method == http.MethodOptions {
			w.WriteHeader(http.StatusNoContent)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// ─────────────────────────────────────────────
// Route Setup
// ─────────────────────────────────────────────

func (s *Server) SetupRoutes() http.Handler {
	mux := http.NewServeMux()

	// Health check
	mux.HandleFunc("GET /", s.handleHealth)

	// Users
	mux.HandleFunc("GET /api/users", s.handleListUsers)
	mux.HandleFunc("GET /api/users/{id}", s.handleGetUser)
	mux.HandleFunc("POST /api/users", s.handleCreateUser)
	mux.HandleFunc("POST /api/users/{id}", s.handleUpdateUser)

	// Wrap with middleware (outermost runs first)
	var handler http.Handler = mux
	handler = s.corsMiddleware(handler)
	handler = s.loggingMiddleware(handler)

	return handler
}

func (s *Server) Start(addr string) error {
	log.Printf("🚀 Server starting on %s", addr)
	return http.ListenAndServe(addr, s.SetupRoutes())
}

// ─────────────────────────────────────────────
// Handlers
// ─────────────────────────────────────────────

func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, APIResponse{
		Status:  "ok",
		Message: "Server is running",
		Data:    map[string]string{"time": time.Now().Format(time.RFC3339)},
	})
}

// GET /api/users
func (s *Server) handleListUsers(w http.ResponseWriter, r *http.Request) {
	s.mu.RLock()
	users := make([]User, 0, len(s.users))
	for _, u := range s.users {
		users = append(users, u)
	}
	s.mu.RUnlock()

	writeJSON(w, http.StatusOK, APIResponse{
		Status:  "success",
		Message: fmt.Sprintf("Returned %d users", len(users)),
		Data:    users,
	})
}

// GET /api/users/{id}
func (s *Server) handleGetUser(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.PathValue("id"))
	if err != nil {
		writeJSON(w, http.StatusBadRequest, APIResponse{
			Status:  "error",
			Message: "Invalid user ID",
		})
		return
	}

	s.mu.RLock()
	user, exists := s.users[id]
	s.mu.RUnlock()

	if !exists {
		writeJSON(w, http.StatusNotFound, APIResponse{
			Status:  "error",
			Message: fmt.Sprintf("User %d not found", id),
		})
		return
	}

	writeJSON(w, http.StatusOK, APIResponse{
		Status:  "success",
		Message: "User retrieved",
		Data:    user,
	})
}

// POST /api/users
func (s *Server) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	var input struct {
		Name  string `json:"name"`
		Email string `json:"email"`
	}

	if err := json.NewDecoder(r.Body).Decode(&input); err != nil {
		writeJSON(w, http.StatusBadRequest, APIResponse{
			Status:  "error",
			Message: "Invalid JSON body",
		})
		return
	}

	// Validation
	if strings.TrimSpace(input.Name) == "" {
		writeJSON(w, http.StatusBadRequest, APIResponse{
			Status:  "error",
			Message: "Name is required",
		})
		return
	}
	if !strings.Contains(input.Email, "@") {
		writeJSON(w, http.StatusBadRequest, APIResponse{
			Status:  "error",
			Message: "Valid email is required",
		})
		return
	}

	s.mu.Lock()
	user := User{
		ID:        s.nextID,
		Name:      input.Name,
		Email:     input.Email,
		CreatedAt: time.Now(),
	}
	s.users[user.ID] = user
	s.nextID++
	s.mu.Unlock()

	writeJSON(w, http.StatusCreated, APIResponse{
		Status:  "success",
		Message: "User created",
		Data:    user,
	})
}

// POST /api/users/{id}
func (s *Server) handleUpdateUser(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.Atoi(r.PathValue("id"))
	if err != nil {
		writeJSON(w, http.StatusBadRequest, APIResponse{
			Status:  "error",
			Message: "Invalid user ID",
		})
		return
	}

	var input struct {
		Name  *string `json:"name,omitempty"`
		Email *string `json:"email,omitempty"`
	}

	if err := json.NewDecoder(r.Body).Decode(&input); err != nil {
		writeJSON(w, http.StatusBadRequest, APIResponse{
			Status:  "error",
			Message: "Invalid JSON body",
		})
		return
	}

	s.mu.Lock()
	user, exists := s.users[id]
	if !exists {
		s.mu.Unlock()
		writeJSON(w, http.StatusNotFound, APIResponse{
			Status:  "error",
			Message: fmt.Sprintf("User %d not found", id),
		})
		return
	}

	// Partial update — only overwrite provided fields
	if input.Name != nil && strings.TrimSpace(*input.Name) != "" {
		user.Name = *input.Name
	}
	if input.Email != nil && strings.Contains(*input.Email, "@") {
		user.Email = *input.Email
	}

	s.users[id] = user
	s.mu.Unlock()

	writeJSON(w, http.StatusOK, APIResponse{
		Status:  "success",
		Message: "User updated",
		Data:    user,
	})
}

// ─────────────────────────────────────────────
// Utilities
// ─────────────────────────────────────────────

func writeJSON(w http.ResponseWriter, statusCode int, payload APIResponse) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(statusCode)
	json.NewEncoder(w).Encode(payload)
}

// ─────────────────────────────────────────────
// Entry Point
// ─────────────────────────────────────────────

func main() {
	server := NewServer()
	if err := server.Start(":8080"); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
```

