## 2. `StudentDB.cs` – Binary File I/O (mirrors `CustomerDB`)

```csharp
using System;
using System.Collections.Generic;
using System.IO;

namespace StudentMaintenance
{
    /// <summary>
    /// Handles saving and loading Student records to/from a binary file
    /// using BinaryWriter and BinaryReader.
    /// </summary>
    public static class StudentDB
    {
        // Directory and file path for the binary data store
        private const string Dir  = @"C:\C#\files\";
        private const string Path = Dir + "Students.dat";

        /// <summary>
        /// Writes the entire list of students to the binary file.
        /// Creates the directory if it does not already exist.
        /// </summary>
        public static void SaveStudents(List<Student> students)
        {
            // Ensure the target directory exists
            if (!Directory.Exists(Dir))
                Directory.CreateDirectory(Dir);

            // Open a BinaryWriter that overwrites the file each time
            using BinaryWriter binaryOut = new(
                new FileStream(Path, FileMode.Create, FileAccess.Write));

            foreach (Student student in students)
            {
                // Write each field in a fixed order so the reader can
                // reconstruct the record in the same order.
                binaryOut.Write(student.StudentID);   // int  (4 bytes)
                binaryOut.Write(student.Name);        // string (length-prefixed)
                binaryOut.Write(student.GPA);         // decimal (16 bytes)
            }
        }

        /// <summary>
        /// Reads all Student records from the binary file and returns them
        /// as a List<Student>.  Returns an empty list if the file is empty.
        /// </summary>
        public static List<Student> GetStudents()
        {
            List<Student> students = new();

            // Create the directory if it is missing so the file can be opened
            if (!Directory.Exists(Dir))
                Directory.CreateDirectory(Dir);

            // Open a BinaryReader over the file (creates it if absent)
            using BinaryReader binaryIn = new(
                new FileStream(Path, FileMode.OpenOrCreate, FileAccess.Read));

            // PeekChar returns -1 when the end of the stream is reached
            while (binaryIn.PeekChar() != -1)
            {
                Student student = new()
                {
                    // Read fields in the SAME order they were written
                    StudentID = binaryIn.ReadInt32(),
                    Name      = binaryIn.ReadString(),
                    GPA       = binaryIn.ReadDecimal()
                };
                students.Add(student);
            }

            return students;
        }
    }
}
```

