```csharp
namespace StudentMaintenance
{
    /// <summary>
    /// Provides reusable validation helpers that return an error message
    /// string (empty string means the value is valid).
    /// </summary>
    public static class Validator
    {
        public static string LineEnd { get; set; } = "\n";

        /// <summary>Checks that the field is not empty / whitespace.</summary>
        public static string IsPresent(string value, string name)
        {
            string msg = "";
            if (string.IsNullOrWhiteSpace(value))
            {
                msg = $"{name} is a required field.{LineEnd}";
            }
            return msg;
        }

        /// <summary>Checks that the value can be parsed as an Int32.</summary>
        public static string IsInt32(string value, string name)
        {
            string msg = "";
            if (!Int32.TryParse(value, out _))
            {
                msg = $"{name} must be a valid integer value.{LineEnd}";
            }
            return msg;
        }

        /// <summary>Checks that the value can be parsed as a Decimal.</summary>
        public static string IsDecimal(string value, string name)
        {
            string msg = "";
            if (!Decimal.TryParse(value, out _))
            {
                msg = $"{name} must be a valid decimal value.{LineEnd}";
            }
            return msg;
        }

        /// <summary>
        /// Checks that a decimal value falls within [min, max].
        /// Only evaluated when the value is a valid decimal.
        /// </summary>
        public static string IsWithinRange(string value, string name,
            decimal min, decimal max)
        {
            string msg = "";
            if (Decimal.TryParse(value, out decimal number))
            {
                if (number < min || number > max)
                {
                    msg = $"{name} must be between {min} and {max}.{LineEnd}";
                }
            }
            return msg;
        }
    }
}
```

