        public StudentForm()
        {
            BuildUI();
        }

        /// <summary>
        /// Creates and lays out every control on the form.
        /// </summary>
        private void BuildUI()
        {
            // ----- Form properties -----
            Text            = "Student Data – Binary File Manager";
            Size            = new System.Drawing.Size(520, 430);
            StartPosition   = FormStartPosition.CenterScreen;
            Font            = new System.Drawing.Font("Segoe UI", 9F);

            // ----- Labels -----
            lblStudentID = new Label
            {
                Text = "Student ID:",
                Location = new System.Drawing.Point(20, 25),
                AutoSize = true
            };
            lblName = new Label
            {
                Text = "Name:",
                Location = new System.Drawing.Point(20, 65),
                AutoSize = true
            };
            lblGPA = new Label
            {
                Text = "GPA (0.00 – 4.00):",
                Location = new System.Drawing.Point(20, 105),
                AutoSize = true
            };
            lblRecords = new Label
            {
                Text = "Stored Records:",
                Location = new System.Drawing.Point(20, 155),
                AutoSize = true
            };

            // ----- Text boxes -----
            txtStudentID = new TextBox
            {
                Location = new System.Drawing.Point(160, 22),
                Width    = 300
            };
            txtName = new TextBox
            {
                Location = new System.Drawing.Point(160, 62),
                Width    = 300
            };
            txtGPA = new TextBox
            {
                Location = new System.Drawing.Point(160, 102),
                Width    = 300
            };

            // ----- Buttons -----
            btnWrite = new Button
            {
                Text     = "Write Data",
                Location = new System.Drawing.Point(20, 195),
                Size     = new System.Drawing.Size(120, 32)
            };
            btnWrite.Click += BtnWrite_Click;

            btnRead = new Button
            {
                Text     = "Read Data",
                Location = new System.Drawing.Point(150, 195),
