            };
            btnRead.Click += BtnRead_Click;

            btnClear = new Button
            {
                Text     = "Clear Form",
                Location = new System.Drawing.Point(280, 195),
                Size     = new System.Drawing.Size(120, 32)
            };
            btnClear.Click += BtnClear_Click;

            // ----- ListBox -----
            lstStudents = new ListBox
            {
                Location = new System.Drawing.Point(20, 180),
                Size     = new System.Drawing.Size(470, 210),
                // We'll reposition it below the buttons
                Location = new System.Drawing.Point(20, 240),
                Size     = new System.Drawing.Size(470, 160)
            };

            // ----- Add everything to the form -----
            Controls.AddRange(new Control[]
