        // ── Button: Write Data ───────────────────────────────────────
        private void BtnWrite_Click(object sender, EventArgs e)
        {
            // 1. Validate every input field
            string errors = string.Empty;
            errors += Validator.IsPresent(txtStudentID.Text, "Student ID");
            errors += Validator.IsInt32(txtStudentID.Text, "Student ID");
            errors += Validator.IsPresent(txtName.Text, "Name");
            errors += Validator.IsPresent(txtGPA.Text, "GPA");
            errors += Validator.IsDecimal(txtGPA.Text, "GPA");
            errors += Validator.IsWithinRange(txtGPA.Text, "GPA", 0m, 4m);

            if (errors.Length > 0)
