                        MessageBoxButtons.OK,
                        MessageBoxIcon.Information);
                }
                else
                {
                    LoadStudentsIntoList();
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Error reading data:\n{ex.Message}",
                    "File Error",
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Error);
            }
        }

        // ── Button: Clear Form ───────────────────────────────────────
        private void BtnClear_Click(object sender, EventArgs e)
        {
            txtStudentID.Clear();
            txtName.Clear();
            txtGPA.Clear();
            txtStudentID.Focus();
        }

        // ── Helper: populate the ListBox ─────────────────────────────
        private void LoadStudentsIntoList()
        {
            lstStudents.Items.Clear();
            List<Student> students = StudentDB.GetStudents();

            foreach (Student s in students)
            {
                lstStudents.Items.Add(s.ToString());
            }
        }
    }
}
