</div>
```

```css
.carte {
  perspective: 1000px;
  height: 200px;
  margin-bottom: 1rem;
}

.carte-inner {
  position: relative;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;   /* ← clé pour le 3D */
  transition: transform 0.6s ease;
}

.carte:hover .carte-inner {
  transform: rotateY(180deg);
}

.carte-face {
  position: absolute;
  inset: 0;
  backface-visibility: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  border: 1px solid var(--accent-color);
}

.carte-front {
  background-color: var(--secondary-color);
}

.carte-front img {
  max-width: 50%;
  transition: filter 0.6s ease;
}

.carte:hover .carte-front img {
  filter: blur(6px);
}

