## `src/components/Input/useVirtualList.ts`

```typescript
import { useCallback, useMemo, useState } from 'react';

interface UseVirtualListOptions {
  itemCount: number;
  itemHeight: number;
  containerHeight: number;
  /** Extra items to render above/below the viewport for smooth scrolling */
  overscan?: number;
}

interface VirtualListResult {
  /** The slice of indices to render */
  visibleIndices: number[];
  /** Total scrollable height (for the spacer) */
  totalHeight: number;
  /** Top offset for the rendered slice */
  offsetY: number;
  /** Scroll handler to attach to the container */
  onScroll: (e: React.UIEvent<HTMLDivElement>) => void;
  /** Scroll to a specific index (for keyboard navigation) */
  scrollToIndex: (index: number) => void;
}

/**
 * Lightweight virtual list hook.
 * Only renders items that are within the visible viewport (+ overscan).
 */
export function useVirtualList({
  itemCount,
  itemHeight,
  containerHeight,
  overscan = 5,
}: UseVirtualListOptions): VirtualListResult {
  const [scrollTop, setScrollTop] = useState(0);

  const visibleCount = Math.ceil(containerHeight / itemHeight) + overscan * 2;

  const { visibleIndices, totalHeight, offsetY } = useMemo(() => {
    const start = Math.max(0, Math.floor(scrollTop / itemHeight) - overscan);
    const end = Math.min(itemCount, start + visibleCount);
    const indices: number[] = [];

    for (let i = start; i < end; i++) {
      indices.push(i);
    }

    return {
      visibleIndices: indices,
      totalHeight: itemCount * itemHeight,
      offsetY: start * itemHeight,
    };
  }, [scrollTop, itemCount, itemHeight, visibleCount, overscan]);

  const onScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  }, []);

  const scrollToIndex = useCallback(
    (index: number) => {
      const container = document.getElementById('input-dropdown-container');
      if (!container) return;

      const itemTop = index * itemHeight;
      const itemBottom = itemTop + itemHeight;
      const viewTop = container.scrollTop;
      const viewBottom = viewTop + containerHeight;

      if (itemTop < viewTop) {
        container.scrollTop = itemTop;
      } else if (itemBottom > viewBottom) {
        container.scrollTop = itemBottom - containerHeight;
      }
    },
    [itemHeight, containerHeight]
  );

  return { visibleIndices, totalHeight, offsetY, onScroll, scrollToIndex };
}
