## `src/components/Input/Input.tsx`

```tsx
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { InputOption, InputProps, ValidationState } from './types';
import { useDebounce, useLatest } from './useDebounce';
import { useVirtualList } from './useVirtualList';
import styles from './Input.module.css';

// ─── Internal helpers ────────────────────────────────────────────────────────

/**
 * Case-insensitive, trimmed substring match.
 * Also handles special regex characters in the query.
 */
function escapeRegExp(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function matchesQuery(option: InputOption, query: string): boolean {
  const trimmed = query.trim().toLowerCase();
  if (trimmed === '') return true;
  const label = option.label.toLowerCase();
  const value = option.value.toLowerCase();
  // Check both label and value for flexibility
  return label.includes(trimmed) || value.includes(trimmed);
}

/**
 * Filter options with debounced query.
 * Returns null if no matches (to hide the dropdown).
 */
function filterOptions(
  options: InputOption[],
  query: string
): InputOption[] | null {
  if (query.trim() === '') return options;
  const results = options.filter((opt) => matchesQuery(opt, query));
  return results.length > 0 ? results : null;
}

// ─── Component ───────────────────────────────────────────────────────────────

let idCounter = 0;

export const Input: React.FC<InputProps> = ({
  options,
  value,
  onChange,
  validate,
  disabled = false,
  placeholder = '',
  debounceMs = 150,
  virtualizeThreshold = 50,
  optionHeight = 40,
  dropdownMaxHeight = 240,
  showAllOnEmpty = true,
  ariaLabel,
  id,
  onDropdownToggle,
}) => {
  const generatedId = useRef(`input-${++idCounter}`).current;
  const inputId = id ?? generatedId;
  const listboxId = `${inputId}-listbox`;

  // ── State ─────────────────────────────────────────────────────────────────
  const [isFocused, setIsFocused] = useState(false);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [validationState, setValidationState] = useState<ValidationState>('idle');
  const [validationMessage, setValidationMessage] = useState<string | null>(null);
  const [hasInteracted, setHasInteracted] = useState(false);

  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // ── Derived / memoized values ─────────────────────────────────────────────
  const debouncedValue = useDebounce(value, debounceMs);
  const valueRef = useLatest(value);
  const optionsRef = useLatest(options);

  const filteredOptions: InputOption[] | null = useMemo(() => {
    if (!isDropdownOpen) return null;

    // If input is empty and showAllOnEmpty is false, don't show anything
    if (debouncedValue.trim() === '' && !showAllOnEmpty) return null;

    return filterOptions(optionsRef.current, debouncedValue);
  }, [debouncedValue, isDropdownOpen, showAllOnEmpty, optionsRef]);

  const shouldVirtualize =
    (filteredOptions?.length ?? 0) > virtualizeThreshold;

  const virtualList = useVirtualList({
    itemCount: filteredOptions?.length ?? 0,
    itemHeight,
    containerHeight: dropdownMaxHeight,
  });

  // ── Validation ────────────────────────────────────────────────────────────
  const runValidation = useCallback(
    (val: string) => {
      if (!validate) {
        setValidationState('idle');
        setValidationMessage(null);
        return;
      }
      const error = validate(val);
      if (error) {
        setValidationState('invalid');
        setValidationMessage(error);
      } else {
        setValidationState('valid');
        setValidationMessage(null);
      }
    },
    [validate]
  );

  // Run validation on change (after interaction)
  useEffect(() => {
    if (hasInteracted) {
      runValidation(value);
    }
  }, [value, hasInteracted, runValidation]);

  // ── Dropdown open/close logic ─────────────────────────────────────────────
  const openDropdown = useCallback(() => {
    if (disabled) return;
    setIsDropdownOpen(true);
    setActiveIndex(-1);
    onDropdownToggle?.(true);
  }, [disabled, onDropdownToggle]);

  const closeDropdown = useCallback(() => {
    setIsDropdownOpen(false);
    setActiveIndex(-1);
    onDropdownToggle?.(false);
  }, [onDropdownToggle]);

  // Close dropdown when filtered options become null (no match)
  useEffect(() => {
    if (isDropdownOpen && filteredOptions === null) {
      closeDropdown();
    }
  }, [filteredOptions, isDropdownOpen, closeDropdown]);

  // ── Selection ─────────────────────────────────────────────────────────────
  const selectOption = useCallback(
    (option: InputOption) => {
      onChange(option.value, option);
      closeDropdown();
      inputRef.current?.focus();
    },
    [onChange, closeDropdown]
  );

  // ── Keyboard navigation ───────────────────────────────────────────────────
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (disabled) return;

      // Don't intercept if a modifier key is held (allow copy/paste shortcuts)
      if (e.metaKey || e.ctrlKey || e.altKey) return;

      switch (e.key) {
        case 'ArrowDown': {
          e.preventDefault();
          if (!isDropdownOpen) {
            openDropdown();
            return;
          }
          if (filteredOptions && filteredOptions.length > 0) {
            setActiveIndex((prev) => {
              const next =
                prev < filteredOptions.length - 1 ? prev + 1 : 0;
              virtualList.scrollToIndex(next);
              return next;
            });
          }
          break;
        }
        case 'ArrowUp': {
          e.preventDefault();
          if (isDropdownOpen && filteredOptions && filteredOptions.length > 0) {
            setActiveIndex((prev) => {
              const next =
                prev > 0 ? prev - 1 : filteredOptions.length - 1;
              virtualList.scrollToIndex(next);
              return next;
            });
          }
          break;
        }
        case 'Enter': {
          e.preventDefault(); // Prevent form submission
          if (
            isDropdownOpen &&
            filteredOptions &&
            activeIndex >= 0 &&
            activeIndex < filteredOptions.length
          ) {
            selectOption(filteredOptions[activeIndex]);
          }
          break;
        }
        case 'Escape': {
          e.preventDefault();
          if (isDropdownOpen) {
            closeDropdown();
          }
          break;
        }
        case 'Tab': {
          // Close dropdown on tab away
          if (isDropdownOpen) {
            closeDropdown();
          }
          break;
        }
        default:
          break;
      }
    },
    [
      disabled,
      isDropdownOpen,
      filteredOptions,
      activeIndex,
      openDropdown,
      closeDropdown,
      selectOption,
      virtualList,
    ]
  );

  // ── Focus / blur handling ─────────────────────────────────────────────────
  const handleFocus = useCallback(() => {
    setIsFocused(true);
    setHasInteracted(true);
    openDropdown();
  }, [openDropdown]);

  const handleBlur = useCallback(
    (e: React.FocusEvent<HTMLInputElement>) => {
      // If focus moves to an option in the dropdown, don't close
      const relatedTarget = e.relatedTarget as HTMLElement | null;
      if (relatedTarget && dropdownRef.current?.contains(relatedTarget)) {
        return;
      }
      setIsFocused(false);
      closeDropdown();
    },
    [closeDropdown]
  );

  // Close on outside click (belt-and-suspenders beyond blur)
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as Node)
      ) {
          closeDropdown();
          setIsFocused(false);
        }
      };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [closeDropdown]);

  // ── Input change ──────────────────────────────────────────────────────────
  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const newVal = e.target.value;
      onChange(newVal);
      setHasInteracted(true);
      // Reset active index when user types
      setActiveIndex(-1);
      // Ensure dropdown is open while typing
      if (!isDropdownOpen) {
        openDropdown();
      }
    },
    [onChange, isDropdownOpen, openDropdown]
  );

  // ── Mouse interaction on options ──────────────────────────────────────────
  const handleOptionClick = useCallback(
    (e: React.MouseEvent, option: InputOption) => {
      e.preventDefault(); // Prevent blur from firing before click
      selectOption(option);
    },
    [selectOption]
  );

  const handleOptionMouseEnter = useCallback((index: number) => {
    setActiveIndex(index);
  }, []);

  // ── Render ────────────────────────────────────────────────────────────────
  const inputClasses = [
    styles.input,
    isFocused && styles.inputFocused,
    validationState === 'invalid' && styles.inputInvalid,
    disabled && styles.inputDisabled,
  ]
    .filter(Boolean)
    .join(' ');

  const showDropdown =
    isDropdownOpen && filteredOptions !== null && filteredOptions.length > 0;

  return (
    <div
      ref={containerRef}
      className={styles.container}
      role="combobox"
      aria-expanded={showDropdown}
      aria-haspopup="listbox"
      aria-owns={listboxId}
    >
      <input
        ref={inputRef}
        id={inputId}
        type="text"
        role="combobox"
        className={inputClasses}
        value={value}
        onChange={handleChange}
        onFocus={handleFocus}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
        disabled={disabled}
        placeholder={placeholder}
        aria-label={ariaLabel}
        aria-autocomplete="list"
        aria-controls={listboxId}
        aria-activedescendant={
          activeIndex >= 0 ? `${listboxId}-option-${activeIndex}` : undefined
        }
        aria-invalid={validationState === 'invalid' || undefined}
        autoComplete="off"
        spellCheck={false}
      />

      {/* Validation message */}
      {validationState === 'invalid' && validationMessage && (
        <span role="alert" className={styles.validationMessage}>
          {validationMessage}
        </span>
      )}

      {/* Dropdown */}
      {showDropdown && (
        <div
          ref={dropdownRef}
          id={listboxId}
          role="listbox"
          className={styles.dropdown}
          style={{ maxHeight: dropdownMaxHeight }}
        >
          {shouldVirtualize ? (
            <div
              id="input-dropdown-container"
              className={styles.virtualScrollContainer}
              onScroll={virtualList.onScroll}
              style={{ height: dropdownMaxHeight, overflowY: 'auto' }}
            >
              {/* Top spacer */}
              <div
                style={{
                  height: virtualList.offsetY,
                  flexShrink: 0,
                }}
              />

              {virtualList.visibleIndices.map((idx) => {
                const option = filteredOptions![idx];
                const isActive = idx === activeIndex;
                return (
                  <div
                    key={option.value}
                    id={`${listboxId}-option-${idx}`}
                    role="option"
                    aria-selected={isActive}
                    className={`${styles.option} ${
                      isActive ? styles.optionActive : ''
                    }`}
                    style={{ height: optionHeight }}
                    onMouseDown={(e) => handleOptionClick(e, option)}
                    onMouseEnter={() => handleOptionMouseEnter(idx)}
                  >
                    {option.label}
                  </div>
                );
              })}

              {/* Bottom spacer */}
              <div
                style={{
                  height:
                    virtualList.totalHeight -
                    virtualList.offsetY -
                    virtualList.visibleIndices.length * optionHeight,
                  flexShrink: 0,
                }}
              />
            </div>
          ) : (
            /* Non-virtualized: simple list for small option sets */
            filteredOptions!.map((option, idx) => {
              const isActive = idx === activeIndex;
              return (
                <div
                  key={option.value}
                  id={`${listboxId}-option-${idx}`}
                  role="option"
                  aria-selected={isActive}
                  className={`${styles.option} ${
                    isActive ? styles.optionActive : ''
                  }`}
                  style={{ height: optionHeight }}
                  onMouseDown={(e) => handleOptionClick(e, option)}
                  onMouseEnter={() => handleOptionMouseEnter(idx)}
                >
                  {option.label}
                </div>
              );
            })
          )}
        </div>
      )}
    </div>
  );
};

Input.displayName = 'Input';

export default Input;
