import { prisma } from "@/utils/prisma";
import { z } from "zod";
import { FastifyPluginAsyncTypeProvider } from "@/utils/fastify";
import {
  serializerCompiler,
  validatorCompiler,
} from "fastify-type-provider-zod";
import { validateAuthUser } from "@/utils/authCheck";
import { changePassword } from "@/utils/user";
import bcrypt from "bcrypt";

// ─── スキーマ ────────────────────────────────────────────────

const updateUserPasswordSchema = z.object({
  password: z.string(),
  new_password: z.string(),
  new_password_confirmation: z.string(),
});

// ─── ヘルパー ────────────────────────────────────────────────

async function verifyCurrentPassword(
  plainPassword: string,
  hashedPassword: string,
): Promise<boolean> {
  return bcrypt.compare(plainPassword, hashedPassword);
}

function assertNewPasswordRules(body: z.infer<typeof updateUserPasswordSchema>): void {
  const { password, new_password, new_password_confirmation } = body;

  if (password === new_password) {
    throw new Error("新しいパスワードは現在のパスワードと違うものを入力してください");
  }
  if (new_password !== new_password_confirmation) {
    throw new Error("新しいパスワードが一致しません");
  }
}

// ─── ルート ──────────────────────────────────────────────────

const index: FastifyPluginAsyncTypeProvider = async (fastify) => {
  fastify.setSerializerCompiler(serializerCompiler);
  fastify.setValidatorCompiler(validatorCompiler);

  fastify.patch(
    "/",
    { schema: { body: updateUserPasswordSchema } },
    async (request, reply) => {
      // 1. 認証ユーザーの取得
      const authedUser = validateAuthUser(request.user);
      const user = await prisma.users.findUnique({
        where: { id: authedUser.id },
      });
      if (!user) {
        throw fastify.httpErrors.notFound("ユーザー情報がありません");
      }

      // 2. 現在のパスワードの検証
      const isPasswordValid = await verifyCurrentPassword(
        request.body.password,
        user.password,
      );
      if (!isPasswordValid) {
        throw fastify.httpErrors.badRequest("現在のパスワードが異なります");
      }

      // 3. 新パスワードのルールチェック
      try {
        assertNewPasswordRules(request.body);
      } catch (err) {
        throw fastify.httpErrors.badRequest((err as Error).message);
      }

      // 4. パスワード更新
      await changePassword({
        user_id: authedUser.id,
        password: request.body.new_password,
      });

      reply.send("OK");
    },
  );
};

export default index;
```

## 主な変更点

| # | 変更内容 | 理由 |
|---|---------|------|
| 1 | `new Promise(...)` ラッパーを削除し `await bcrypt.compare(...)` に置換 | `bcrypt` v5 以降はコールバックを渡さなければ Promise を返す。ラッパーが余計なネストと `err/res` という意味の薄い変数名を生んでいた |
| 2 | `verifyCurrentPassword` / `assertNewPasswordRules` を関数に抽出 | ハンドラが「何をやるか」の羅列になり、各ステップの意図が一目で分かる |
| 3 | 変数名 `result` → `isPasswordValid`、`userData` → `user` | 型・用途が名前から伝わる |
| 4 | 新パスワードのルールチェックを `try/catch` で `fastify.httpErrors` に変換 | ヘルパー関数は純粋に「ルール違反か」を判定し、HTTP ステータスの付与はハンドラ側で行う責務分離 |
| 5 | 番号付きコメント（1〜4）を追加 | 処理の進行順序が視覚的に追える |
| 6 | 不要な `else` を削除（早期リターン） | ネストが 1 レベル減る |
| 7 | `import` の並びを「外部 → 内部」のグループに整え、`validateRequestPassword`（未使用）を削除 | 未使用 import の排除 + 読みやすさ |

