// Custom RequestMatcher that checks Referer header
public class RefererRequestMatcher implements RequestMatcher {
    private final String referer;

    public RefererRequestMatcher(String referer) {
        this.referer = referer;
    }

    @Override
    public boolean matches(HttpServletRequest request) {
        String refererHeader = request.getHeader("Referer");
        return referer != null && refererHeader != null && refererHeader.startsWith(referer);
    }
}
```

