    CSS = """
    Screen {
        align: center middle;
    }

    #title {
        text-style: bold;
        text-align: center;
        margin-bottom: 1;
    }

    #file-list {
        width: 60;
        height: auto;
        max-height: 20;
        border: round $primary;
        padding: 1 2;
    }

    #file-list:empty {
        content: "No files remaining";
        text-align: center;
        text-style: dim italic;
    }

