        width: 100%;
        height: 3;
        margin-bottom: 1;
        content-align: left middle;
    }

    FileButton:hover {
        background: $primary 30%;
    }

    /* Inner button (the delete button inside) */
    FileButton > Button {
        width: 4;
        height: 1;
        margin: 1 0;
