# ExpandableText — Production-Ready React Native Component

## `ExpandableText.tsx`

```tsx
import React, {
  useState,
  useRef,
  useCallback,
  useEffect,
  useMemo,
  forwardRef,
  useImperativeHandle,
} from 'react';
import {
  Text,
  View,
  TouchableOpacity,
  Animated,
  StyleProp,
  ViewStyle,
  TextStyle,
  LayoutChangeEvent,
  TextLayoutEvent,
  Platform,
  AccessibilityRole,
} from 'react-native';

// ─────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────
export interface ExpandableTextProps {
  /** The full text to display */
  text: string;
  /** Number of lines to show when collapsed (default: 1) */
  numberOfLines?: number;
  /** Label shown when collapsed (default: "See more") */
  seeMoreText?: string;
  /** Label shown when expanded (default: "See less") */
  seeLessText?: string;
  /** Style for the main text */
  textStyle?: StyleProp<TextStyle>;
  /** Style for the container */
  containerStyle?: StyleProp<ViewStyle>;
  /** Style for the "See more" / "See less" label */
  seeMoreTextStyle?: StyleProp<TextStyle>;
  /** Duration of expand/collapse animation in ms (default: 250) */
  animationDuration?: number;
  /** Callback fired when text is expanded */
  onExpand?: () => void;
  /** Callback fired when text is collapsed */
  onCollapse?: () => void;
  /** Whether to show "See less" when expanded (default: true) */
  showSeeLess?: boolean;
  /** Accessibility label override */
  accessibilityLabel?: string;
}

export interface ExpandableTextRef {
  /** Programmatically expand */
  expand: () => void;
  /** Programmatically collapse */
  collapse: () => void;
  /** Toggle expand/collapse */
  toggle: () => void;
  /** Whether the text is currently expanded */
  isExpanded: () => boolean;
}

// ─────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────
const ExpandableText = forwardRef<ExpandableTextRef, ExpandableTextProps>(
  (
    {
      text,
      numberOfLines = 1,
      seeMoreText = 'See more',
      seeLessText = 'See less',
      textStyle,
      containerStyle,
      seeMoreTextStyle,
      animationDuration = 250,
      onExpand,
      onCollapse,
      showSeeLess = true,
      accessibilityLabel,
    },
    ref,
  ) => {
    const [isExpanded, setIsExpanded] = useState(false);
    const [isTruncated, setIsTruncated] = useState(false);
    const [isMeasured, setIsMeasured] = useState(false);

    const containerRef = useRef<View>(null);
    const measureTextRef = useRef<Text>(null);
    const visibleTextRef = useRef<Text>(null);

    const animatedHeight = useRef(new Animated.Value(0)).current;
    const [contentHeight, setContentHeight] = useState(0);

    // ── Measurement ──────────────────────────
    const handleContainerLayout = useCallback(
      (e: LayoutChangeEvent) => {
        // Store container width for comparison
        (containerRef.current as any)?._width = e.nativeEvent.layout.width;
      },
      [],
    );

    const handleMeasureTextLayout = useCallback(
      (e: TextLayoutEvent) => {
        const { height: fullHeight } = e.nativeEvent;
        const { lines } = e.nativeEvent;

        // Calculate the height of `numberOfLines` lines
        const singleLineHeight = lines[0]?.height ?? fullHeight;
        const collapsedHeight = singleLineHeight * numberOfLines;

        // If full text height exceeds collapsed height, it's truncated
        const truncated = fullHeight > collapsedHeight + 1; // +1 for rounding
        setIsTruncated(truncated);
        setIsMeasured(true);
      },
      [numberOfLines],
    );

    const handleVisibleTextLayout = useCallback(
      (e: LayoutChangeEvent) => {
        setContentHeight(e.nativeEvent.layout.height);
        animatedHeight.setValue(e.nativeEvent.layout.height);
      },
      [],
    );

    // ── Expand / Collapse ────────────────────
    const expand = useCallback(() => {
      if (isExpanded) return;
      setIsExpanded(true);
      onExpand?.();
    }, [isExpanded, onExpand]);

    const collapse = useCallback(() => {
      if (!isExpanded) return;
      setIsExpanded(false);
      onCollapse?.();
    }, [isExpanded, onCollapse]);

    const toggle = useCallback(() => {
      if (isExpanded) {
        collapse();
      } else {
        expand();
      }
    }, [isExpanded, expand, collapse]);

    useImperativeHandle(ref, () => ({
      expand,
      collapse,
      toggle,
      isExpanded: () => isExpanded,
    }));

    // ── Animation on expand ──────────────────
    useEffect(() => {
      if (isExpanded && contentHeight > 0) {
        Animated.timing(animatedHeight, {
          toValue: contentHeight,
          duration: animationDuration,
          useNativeDriver: false,
        }).start();
      }
    }, [isExpanded, contentHeight, animationDuration, animatedHeight]);

    // ── Reset on text change ─────────────────
    useEffect(() => {
      setIsExpanded(false);
      setIsTruncated(false);
      setIsMeasured(false);
    }, [text]);

    // ── Render ───────────────────────────────
    const renderContent = () => {
      // If not yet measured, render the constrained text (safe default)
      if (!isMeasured) {
        return (
          <Text
            ref={visibleTextRef}
            numberOfLines={numberOfLines}
            style={textStyle}
            onLayout={handleVisibleTextLayout}
            accessibilityLabel={accessibilityLabel}
          >
            {text}
          </Text>
        );
      }

      // If text fits within the allowed lines, render normally
      if (!isTruncated) {
        return (
          <Text
            ref={visibleTextRef}
            style={textStyle}
            onLayout={handleVisibleTextLayout}
            accessibilityLabel={accessibilityLabel}
          >
            {text}
          </Text>
        );
      }

      // Truncated text → show expandable
      return (
        <View style={styles.row}>
          <Text
            ref={visibleTextRef}
            numberOfLines={isExpanded ? undefined : numberOfLines}
            style={[textStyle, styles.flexText]}
            onLayout={handleVisibleTextLayout}
            accessibilityLabel={accessibilityLabel}
          >
            {text}
          </Text>

          <TouchableOpacity
            onPress={toggle}
            activeOpacity={0.6}
            accessibilityRole={accessibilityRole}
            accessibilityLabel={
              isExpanded ? `Collapse text` : `Expand text: ${text}`
            }
            accessibilityState={{ expanded: isExpanded }}
            hitSlop={{ top: 8, bottom: 8, left: 4, right: 4 }}
          >
            <Text style={[styles.seeMore, seeMoreTextStyle]}>
              {isExpanded && showSeeLess ? seeLessText : seeMoreText}
            </Text>
          </TouchableOpacity>
        </View>
      );
    };

    const accessibilityRole: AccessibilityRole = 'button';

    return (
      <View
        ref={containerRef}
        style={[styles.container, containerStyle]}
        onLayout={handleContainerLayout}
      >
        {/* Hidden measurement text – full text, no line limit */}
        <Text
          ref={measureTextRef}
          style={[textStyle, styles.measureText]}
          onTextLayout={handleMeasureTextLayout}
          numberOfLines={undefined}
        >
          {text}
        </Text>

        {/* Visible content */}
        {renderContent()}
      </View>
    );
  },
);

ExpandableText.displayName = 'ExpandableText';

// ─────────────────────────────────────────────
// Styles
// ─────────────────────────────────────────────
const styles = StyleSheet.create({
  container: {
    width: '100%',
  },
  measureText: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    height: 0,
    overflow: 'hidden',
    opacity: 0,
    // Ensure it doesn't affect layout
    pointerEvents: 'none',
  },
  row: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    alignItems: 'baseline',
  },
  flexText: {
    flexShrink: 1,
    flexBasis: '100%',
  },
  seeMore: {
    fontWeight: '600',
    color: '#007AFF',
    marginLeft: 4,
  },
});

export default ExpandableText;
```

