# Solution: Excel Cell Validator with QXlsx

## Complete C++ Source Code

```cpp
#include <QXlsx>
#include <QFile>
#include <QString>
#include <QSet>
#include <QCoreApplication>
#include <QDebug>
#include <cmath>

/**
 * Checks whether the given cell contains one of the values: 0, 1, 2, 3, 10, 11, 42.
 * The value may be stored as a number (int/float/double) or as a string
 * in decimal, hexadecimal (0x...), octal (0o...), or binary (0b...) format.
 */
bool isCellValid(const QString &filePath, const QString &cellRef)
{
    // --- Load workbook ---
    QXlsx::Document doc;
    if (!doc.load(filePath)) {
        qWarning() << "Failed to open file:" << filePath;
        return false;
    }

    QXlsx::Cell cell = doc.cell(cellRef);
    if (cell.isNull()) {
        qWarning() << "Cell" << cellRef << "not found or empty.";
        return false;
    }

    // --- Set of allowed integer values ---
    static const QSet<int> kValidValues = {0, 1, 2, 3, 10, 11, 42};

    // --- Case 1: cell holds a numeric value (int, float, double) ---
    if (cell.isNumber()) {
        double val = cell.value().toDouble();

        // Accept if the value (ignoring tiny floating-point noise)
        // equals one of the allowed integers.
        for (int v : kValidValues) {
            if (std::abs(val - static_cast<double>(v)) < 1e-9)
                return true;
        }
        return false;
    }

    // --- Case 2: cell holds a string representation ---
    if (cell.isString()) {
        QString s = cell.value().toString().trimmed();
        if (s.isEmpty())
            return false;

        bool ok  = false;
        int  val = 0;

        // Determine base from prefix (case-insensitive)
        if (s.startsWith(QLatin1String("0x"), Qt::CaseInsensitive) ||
            s.startsWith(QLatin1String("0X"))) {
            // Hexadecimal: 0x2A, 0x0, 0xA, 0xB …
            val = s.mid(2).toInt(&ok, 16);
        }
        else if (s.startsWith(QLatin1String("0o"), Qt::CaseInsensitive) ||
                 s.startsWith(QLatin1String("0O"))) {
            // Octal: 0o52, 0o12, 0o13 …
            val = s.mid(2).toInt(&ok, 8);
        }
        else if (s.startsWith(QLatin1String("0b"), Qt::CaseInsensitive) ||
                 s.startsWith(QLatin1String("0B"))) {
            // Binary: 0b101010, 0b1010, 0b1011 …
            val = s.mid(2).toInt(&ok, 2);
        }
        else {
            // Decimal (may include a fractional part, e.g. "42.0")
            double dval = s.toDouble(&ok);
            if (ok) {
                for (int v : kValidValues) {
                    if (std::abs(dval - static_cast<double>(v)) < 1e-9)
                        return true;
                }
            }
            return ok && kValidValues.contains(val);
        }

        return ok && kValidValues.contains(val);
    }

    // Boolean, formula (no cached value), etc. → invalid
    return false;
}

// ------------------------------------------------------------------
int main(int argc, char *argv[])
{
    QCoreApplication app(argc, argv);

    if (argc < 3) {
        qWarning() << "Usage:" << argv[0] << "<file.xlsx> <cellRef>";
        qWarning() << "Example:" << argv[0] << "data.xlsx" << "B3";
        return 1;
    }

    QString filePath = QString::fromLocal8Bit(argv[1]);
    QString cellRef  = QString::fromLocal8Bit(argv[2]).toUpper();

    if (!QFile::exists(filePath)) {
        qCritical() << "File not found:" << filePath;
        return 1;
    }

    bool result = isCellValid(filePath, cellRef);

    if (result)
        qDebug().noquote() << "VALID  – cell" << cellRef
                           << "contains an allowed value (0,1,2,3,10,11,42).";
    else
        qDebug().noquote() << "INVALID – cell" << cellRef
                           << "does NOT contain an allowed value.";

    return result ? 0 : 1;
}
```

