## 2. `AudioRecorder.swift` — Service Layer

```swift
import AVFoundation
import Foundation

/// Protocol to allow mocking in unit tests.
protocol AudioRecording {
    func configure() throws
    func startRecording() throws
    func stopRecording() throws -> URL
    func isRecording() -> Bool
}

/// Concrete implementation wrapping AVAudioRecorder.
final class AudioRecorder: AudioRecording {

    private var audioRecorder: AVAudioRecorder?
    private var audioSession: AVAudioSession?
    private let fileManager = FileManager.default
    private let audioQuality: AVAudioQuality = .high

    // MARK: - Configuration

    func configure() throws {
        // Request microphone permission (must be called on main thread).
        let granted = try await_requestPermission()
        guard granted else {
            throw AudioRecorderError.microphonePermissionDenied
        }

        // Configure AVAudioSession.
        let session = AVAudioSession.sharedInstance()
        try session.setCategory(.playAndRecord, mode: .default, options: [.defaultToSpeaker])
        try session.setActive(true, options: .notifyOthersOnDeactivation)
        self.audioSession = session
    }

    // MARK: - Recording

    func startRecording() throws {
        guard audioRecorder == nil else { return }

        let url = Self.makeRecordingURL()
        let settings: [String: Any] = [
            AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
            AVSampleRateKey: 44_100,
            AVNumberOfChannelsKey: 1,
            AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue,
            AVEncoderBitRateKey: 128_000
        ]

        do {
            let recorder = try AVAudioRecorder(url: url, settings: settings)
            recorder.isMeteringEnabled = true
            recorder.record()
            audioRecorder = recorder
        } catch {
            throw AudioRecorderError.recordingFailed(error.localizedDescription)
        }
    }

    func stopRecording() throws -> URL {
        guard let recorder = audioRecorder, recorder.isRecording else {
            throw AudioRecorderError.notRecording
        }

        recorder.stop()
        let url = recorder.url
        audioRecorder = nil

        // Deactivate session so other apps can use the mic.
        try? audioSession?.setActive(false, options: .notifyOthersOnDeactivation)

        return url
    }

    func isRecording() -> Bool {
        audioRecorder?.isRecording ?? false
    }

    // MARK: - Private Helpers

    /// Generates a unique file URL in the Documents directory.
    private static func makeRecordingURL() -> URL {
        let documents = fileManager.urls(for: .documentDirectory, in: .userDomainMask)[0]
        let timestamp = Date().timeIntervalSince1970
        let filename = "Recording_\(Int(timestamp)).m4a"
        return documents.appendingPathComponent(filename)
    }

    /// Bridges the async permission API into a synchronous call for the protocol.
    /// In production you would make the protocol `async throws`.
    private func await_requestPermission() throws -> Bool {
        let semaphore = DispatchSemaphore(value: 0)
        var granted = false
        Task { @MainActor in
            granted = await AVAudioApplication.requestRecordPermission()
            semaphore.signal()
        }
        semaphore.wait()
        return granted
    }
}

// MARK: - Errors

enum AudioRecorderError: LocalizedError {
    case microphonePermissionDenied
    case recordingFailed(String)
    case notRecording

    var errorDescription: String? {
        switch self {
        case .microphonePermissionDenied:
            return "Microphone permission denied. Please enable it in Settings."
        case .recordingFailed(let detail):
            return "Failed to start recording: \(detail)"
        case .notRecording:
            return "No active recording to stop."
        }
    }
}
```

