## 3. `RecorderViewModel.swift` — ViewModel

```swift
import Foundation
import Combine

@MainActor
final class RecorderViewModel: ObservableObject {

    // MARK: - Published State

    @Published private(set) var state: RecordingState = .idle
    @Published private(set) var elapsed: TimeInterval = 0

    // MARK: - Dependencies

    private let audioRecorder: AudioRecording
    private var timerCancellable: AnyCancellable?
    private var startDate: Date?

    // MARK: - Init (Dependency Injection)

    init(audioRecorder: AudioRecording = AudioRecorder()) {
        self.audioRecorder = audioRecorder
    }

    // MARK: - Intents

    func startRecording() {
        guard case .idle = state,
              !audioRecorder.isRecording() else { return }

        do {
            try audioRecorder.configure()
            try audioRecorder.startRecording()
            startDate = Date()
            state = .recording
            startTimer()
        } catch {
            state = .failed(error.localizedDescription)
        }
    }

    func stopRecording() {
        guard case .recording = state else { return }

        do {
            let url = try audioRecorder.stopRecording()
            stopTimer()
            state = .finished(url)
        } catch {
            state = .failed(error.localizedDescription)
        }
    }

    func reset() {
        stopTimer()
        startDate = nil
        elapsed = 0
        state = .idle
    }

    // MARK: - Timer

    private func startTimer() {
        timerCancellable = Timer
            .publish(every: 0.1, on: .main, in: .common)
            .autoconnect()
            .sink { [weak self] _ in
                guard let self, let start = self.startDate else { return }
                self.elapsed = Date().timeIntervalSince(start)
            }
    }

    private func stopTimer() {
        timerCancellable?.cancel()
        timerCancellable = nil
    }

    // MARK: - Formatting

    var formattedElapsed: String {
        let total = Int(elapsed)
        let minutes = total / 60
        let seconds = total % 60
        return String(format: "%02d:%02d", minutes, seconds)
    }
}
