```swift
import SwiftUI

/// A reusable equalizer bar animation.
/// Shows N vertical bars that oscillate at different speeds/amplitudes
/// to simulate a live audio spectrum.
struct EqualizerView: View {

    // MARK: - Configuration

    let barCount: Int
    let barWidth: CGFloat
    let barSpacing: CGFloat
    let maxBarHeight: CGFloat
    let color: Color
    let isAnimating: Bool

    // MARK: - Init

    init(
        barCount: Int = 5,
        barWidth: CGFloat = 8,
        barSpacing: CGFloat = 6,
        maxBarHeight: CGFloat = 60,
        color: Color = .red,
        isAnimating: Bool = true
    ) {
        self.barCount = barCount
        self.barWidth = barWidth
        self.barSpacing = barSpacing
        self.maxBarHeight = maxBarHeight
        self.color = color
        self.isAnimating = isAnimating
    }

    // MARK: - Body

    var body: some View {
        HStack(spacing: barSpacing) {
            ForEach(0..<barCount, id: \.self) { index in
                EqualizerBar(
                    barWidth: barWidth,
                    maxBarHeight: maxBarHeight,
                    color: color,
                    isAnimating: isAnimating,
                    // Stagger each bar for an organic look
                    animationDelay: Double(index) * 0.12,
                    animationDuration: 0.4 + Double(index % 3) * 0.15
                )
            }
        }
    }
}

// MARK: - Single Bar

private struct EqualizerBar: View {

    let barWidth: CGFloat
    let maxBarHeight: CGFloat
    let color: Color
    let isAnimating: Bool
    let animationDelay: Double
    let animationDuration: Double

    @State private var scale: CGFloat = 0.3

    var body: some View {
        RoundedRectangle(cornerRadius: barWidth / 2)
            .fill(color)
            .frame(width: barWidth, height: maxBarHeight)
            .scaleEffect(y: scale, anchor: .bottom)
            .onAppear {
                guard isAnimating else { return }
                animate()
            }
            .onChange(of: isAnimating) { _, newValue in
                if newValue {
                    animate()
                } else {
                    withAnimation(.easeOut(duration: 0.3)) {
                        scale = 0.3
                    }
                }
            }
    }

    private func animate() {
        withAnimation(
            .easeInOut(duration: animationDuration)
            .repeatForever(autoreverses: true)
            .delay(animationDelay)
        ) {
            scale = 1.0
        }
    }
}

