        }

        .intro {
          margin-top: 4px;
        }

        .details {
          margin-top: 8px;
          display: none;
        }

        :host([expanded]) .details {
          display: block;
        }

        .toggle-button {
          margin-top: 10px;
          padding: 6px 12px;
          border: 1px solid #888;
          border-radius: 4px;
          background: #f5f5f5;
          cursor: pointer;
          font-size: 0.9em;
        }

        .toggle-button:hover {
          background: #e8e8e8;
        }
      </style>

      <div class="header" part="header">
        <span class="toggle-icon" aria-hidden="true">+</span>
        <slot name="header"></slot>
      </div>

      <div class="intro">
        <slot name="intro"></slot>
      </div>

      <div class="details">
        <slot name="details"></slot>
      </div>

      <button class="toggle-button" part="button">expand more</button>
    `;

    this._header = this.shadowRoot.querySelector('.header');
    this._button = this.shadowRoot.querySelector('.toggle-button');
    this._icon = this.shadowRoot.querySelector('.toggle-icon');

    // Toggle on header click
    this._header.addEventListener('click', () => this.toggle());

    // Toggle on button click
    this._button.addEventListener('click', (e) => {
      e.stopPropagation();
      this.toggle();
    });
  }

  get expanded() {
    return this.hasAttribute('expanded');
  }

  set expanded(value) {
    if (value) {
      this.setAttribute('expanded', '');
    } else {
      this.removeAttribute('expanded');
    }
  }

  toggle() {
    this.expanded = !this.expanded;
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name === 'expanded' && oldValue !== newValue) {
      this._updateUI();
    }
  }

  static get observedAttributes() {
    return ['expanded'];
  }

  _updateUI() {
    const isExpanded = this.expanded;
    this._icon.textContent = isExpanded ? '−' : '+';
    this._button.textContent = isExpanded ? 'collapse' : 'expand more';
    this.setAttribute('aria-expanded', String(isExpanded));
  }

  connectedCallback() {
    this._updateUI();
  }
}

customElements.define('x-details', XDetails);
</script>
```

## Usage

```html
<x-details>
  <span slot="header">Header here</span>
  <div slot="intro">intro part always visible</div>
  <div slot="details">details part - visible when expanded</div>
</x-details>
```

## Key features

- **Shadow DOM** — all internal styles are encapsulated and won't leak in or out.
- **Slots** — `header`, `intro`, and `details` slots match your usage example.
- **Toggle indicator** — a small square showing `+` when collapsed and `−` when expanded.
- **Header styling** — larger font, bold, with a bottom border, and clickable to toggle.
- **Intro always visible** — the intro section is rendered regardless of state.
- **"expand more" button** — shown below the intro when collapsed; changes to "collapse" when expanded.
- **Public API** — you can control it programmatically:
  ```js
  const el = document.querySelector('x-details');
  el.expanded = true;   // set state
  el.toggle();          // flip state
  el.expanded;          // read state
  ```
- **Accessibility** — `aria-expanded` is kept in sync with the state.

You can also toggle it declaratively by setting the `expanded` attribute directly: `<x-details expanded>`.

# Fast `strlen` via Word-At-A-Time Scanning

The core idea: instead of testing one byte per iteration, load a full `size_t`-sized word and use arithmetic to detect whether *any* byte in that word is zero. This gives you a 4× or 8× speedup on 32/64-bit machines.

## The Zero-Detection Trick

For a word `w`, the expression

```
(w - 0x0101010101010101) & ~w & 0x8080808080808080
```

is non-zero **if and only if** at least one byte in `w` is zero.

Why it works (per byte `b`):

| `b` | `b - 1` (no borrow) | high bit of result | `~b` high bit | AND result |
|-----|---------------------|--------------------|---------------|------------|
| 0   | 0xFF                | 1                  | 1             | **1** ✓   |
| 1   | 0x00                | 0                  | 1             | 0         |
| ≥2  | < 0x80              | 0                  | 1 (if <0x80)  | 0         |

Borrow propagation from a zero byte can set the high bit on the *next* byte, but that byte was already preceded by a zero, so we'd have stopped anyway. No false positives when no byte is zero (no borrow can occur).

## Implementation (64-bit, generalizable)

```c
#include <stddef.h>

/*
 * fast_strlen – word-at-a-time strlen.
 *
 * Requires: size_t is the machine word size (4 or 8 bytes),
 *           little-endian (byte 0 is the least-significant byte).
 */
size_t fast_strlen(const char *s)
{
    /* ---- 1. Handle the unaligned prefix (at most W-1 bytes) ---- */
    size_t offset = 0;
    while (((size_t)s & (sizeof(size_t) - 1)) != 0) {
        if (*s == '\0')
            return offset;
        s++;
        offset++;
    }

    /* ---- 2. Word-aligned main loop ---- */
    const size_t *p  = (const size_t *)s;
    const size_t ONES  = 0x0101010101010101ULL;  /* per-byte 0x01 */
    const size_t HIGH  = 0x8080808080808080ULL;  /* per-byte 0x80 */

    size_t i = 0;
    for (;;) {
        size_t w = p[i];

        /* Zero-byte test: non-zero result ⟹ some byte in w is 0 */
        size_t mask = (w - ONES) & ~w & HIGH;
        if (mask)
            break;

        i++;
    }

    /* ---- 3. Locate the exact zero byte within the word ---- */
    /*
     * 'mask' has bit 63,55,47,… set for each zero byte.
     * __builtin_ctzll gives the index of the least-significant
     * set bit; dividing by 8 yields the byte index (little-endian).
     */
    size_t byte_idx = __builtin_ctzll(mask) / 8;

    return offset + i * sizeof(size_t) + byte_idx;
}
```

### Portable byte-index fallback (no `__builtin_ctzll`)

If you can't rely on a compiler intrinsic, replace step 3 with a small lookup or a byte-by-byte scan (at most 8 iterations, only hit once):

```c
/* Portable alternative for step 3 */
size_t byte_idx = 0;
while (byte_idx < sizeof(size_t)) {
    if (w & (0xFFULL << (8 * byte_idx)))
        break;
    byte_idx++;
}
/* or, with a 256-entry lookup table: */
/* size_t byte_idx = ctz_table[ (unsigned char)(mask >> (8*0)) ]  ... */
```

## 32-bit variant

Just swap the constants:

```c
const size_t ONES = 0x01010101U;
const size_t HIGH = 0x80808080U;
/* use __builtin_ctz instead of __builtin_ctzll */
```

## Why this is fast

| Aspect | Naïve `strlen` | Word-at-a-time |
|--------|---------------|----------------|
| Bytes examined per loop iteration | 1 | `sizeof(size_t)` (4 or 8) |
| Branches per byte | 1 | ~1/8 (amortised) |
| Memory accesses | 1 byte load | 1 word load (often a single cache-line hit covers 8+ chars) |

On a 64-bit machine you get roughly a **6–8×** speedup for long strings, and the unaligned-prefix cost is at most 7 extra byte checks paid once.

## Caveats

- **Endianness**: The `ctz / 8` mapping assumes little-endian. On big-endian you'd use `(sizeof(size_t) - 1) - ctz/8`.
- **Unaligned loads**: The aligned main loop avoids unaligned word loads entirely. The prefix loop handles the first ≤ W−1 bytes.
- **`size_t` width**: The code above is written for 64-bit. For a fully generic version, derive `ONES` and `HIGH` in a loop:
  ```c
  size_t ones = 0, high = 0;
  for (size_t k = 0; k < sizeof(size_t); k++) {
      ones |= 1 << (8*k);
      high |= 0x80 << (8*k);
  }
  ```
- **`restrict` / aliasing**: In production you'd want `const char *restrict` to let the compiler prove the load can't alias with any store.

# Cloudflare WARP on ECS – Terraform Module

Below is a complete Terraform module that covers all four requirements. I've split it into logical files for readability.

## Directory structure

```
modules/warp-ecs/
├── main.tf
├── variables.tf
├── outputs.tf
├── iam.tf
├── ecs.tf
├── codepipeline.tf
└── parameter_store.tf
```

---

## `variables.tf`

```hcl
variable "cluster_name" {
  description = "Name of the ECS cluster"
  type        = string
  default     = "warp-cluster"
}

variable "create_cluster" {
  description = "Set to true to create a new ECS cluster, false to use an existing one"
  type        = bool
  default     = true
}

variable "existing_cluster_name" {
  description = "Name of the existing ECS cluster (used when create_cluster = false)"
  type        = string
  default     = ""
}

variable "service_name" {
  description = "Name of the ECS service"
  type        = string
  default     = "cloudflare-warp"
}

variable "task_cpu" {
  description = "Task CPU units"
  type        = number
  default     = 256
}

variable "task_memory" {
  description = "Task memory in MiB"
  type        = number
  default     = 512
}

variable "container_port" {
  description = "Port exposed by the WARP container"
  type        = number
  default     = 40000
}

variable "warp_token" {
  description = "Cloudflare WARP license token (stored in SSM Parameter Store as SecureString)"
  type        = string
  sensitive   = true
}

variable "parameter_store_name" {
  description = "Name of the SSM Parameter Store key for the WARP token"
  type        = string
  default     = "/warp/license-token"
}

variable "ecr_repository_name" {
  description = "Name of the ECR repository for the WARP image"
  type        = string
  default     = "cloudflare-warp"
}

variable "source_repo" {
  description = "GitHub repository for the CodePipeline source (owner/repo format)"
  type        = string
  default     = "my-org/warp-deployment"
}

variable "source_branch" {
  description = "Git branch to track"
  type        = string
  default     = "main"
}

variable "github_token" {
  description = "GitHub personal access token for the CodePipeline source"
  type        = string
  sensitive   = true
}

variable "vpc_id" {
  description = "VPC ID for the ECS cluster (required when create_cluster = true)"
  type        = string
  default     = ""
}

variable "subnet_ids" {
  description = "Subnet IDs for the ECS cluster (required when create_cluster = true)"
  type        = list(string)
  default     = []
}

variable "environment" {
  description = "Environment tag (dev, staging, prod)"
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}
```

---

## `parameter_store.tf`

```hcl
# ─── SSM Parameter Store for WARP token ───────────────────────────────────────

resource "aws_ssm_parameter" "warp_token" {
  name  = var.parameter_store_name
  type  = "SecureString"
  value = var.warp_token

  tags = merge(
    { Name = "warp-token" },
    var.tags
  )
}
```

---

## `ecs.tf`

```hcl
# ─── ECS Cluster (conditional) ────────────────────────────────────────────────

resource "aws_ecs_cluster" "this" {
  count = var.create_cluster ? 1 : 0

  name = var.cluster_name

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = merge(
    { Name = var.cluster_name },
    var.tags
  )
}

locals {
  cluster_name = var.create_cluster ? aws_ecs_cluster.this[0].name : var.existing_cluster_name
}

# ─── ECR Repository ───────────────────────────────────────────────────────────

resource "aws_ecr_repository" "warp" {
  name                 = var.ecr_repository_name
  image_tag_mutability = "MUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = var.tags
}

# ─── ECS Task Definition ──────────────────────────────────────────────────────

resource "aws_ecs_task_definition" "warp" {
  family                   = "cloudflare-warp"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = var.task_cpu
  memory                   = var.task_memory
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "warp"
      image     = "${aws_ecr_repository.warp.repository_url}:latest"
      essential = true

      portMappings = [
        {
          containerPort = var.container_port
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "WARP_LICENSE_TOKEN"
          value = aws_ssm_parameter.warp_token.arn # SSM ARN reference
        }
      ]

      # Use SSM parameter reference so the value is resolved at runtime
      secrets = [
        {
          name      = "WARP_LICENSE_TOKEN"
          valueFrom = aws_ssm_parameter.warp_token.arn
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.warp.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = "warp"
        }
      }
    }
  ])

  tags = var.tags
}

data "aws_region" "current" {
}

# ─── CloudWatch Log Group ─────────────────────────────────────────────────────

resource "aws_cloudwatch_log_group" "warp" {
  name              = "/ecs/${var.service_name}"
  retention_in_days = 30

  tags = var.tags
}

# ─── ECS Service ──────────────────────────────────────────────────────────────

resource "aws_ecs_service" "warp" {
  name            = var.service_name
  cluster         = local.cluster_name
  task_definition = aws_ecs_task_definition.warp.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets         = var.create_cluster ? var.subnet_ids : []
    security_groups = var.create_cluster ? [aws_security_group.warp.id] : []
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.warp.arn
    container_name   = "warp"
    container_port   = var.container_port
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  deployment_configuration {
    maximum_percent         = 200
    minimum_healthy_percent = 100
  }

  depends_on = [aws_iam_role_policy_attachment.ecs_service]

  tags = var.tags
}

# ─── Security Group (only when creating a new cluster) ────────────────────────

resource "aws_security_group" "warp" {
  count = var.create_cluster ? 1 : 0

  name_prefix = "${var.service_name}-"
  vpc_id      = var.vpc_id

  ingress {
    description = "WARP container port"
    from_port   = var.container_port
    to_port     = var.container_port
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(
    { Name = "${var.service_name}-sg" },
    var.tags
  )
}

# ─── ALB Target Group (for the service) ───────────────────────────────────────

resource "aws_lb_target_group" "warp" {
  name        = "${var.service_name}-tg"
  port        = var.container_port
  protocol    = "TCP"
  vpc_id      = var.create_cluster ? var.vpc_id : null
  target_type = "ip"

  health_check {
    enabled             = true
    port                = var.container_port
    protocol            = "TCP"
    healthy_threshold   = 2
    unhealthy_threshold = 3
    timeout             = 5
    interval            = 30
  }

  tags = var.tags
}
```

