  await page.waitForNavigation({ waitUntil: 'networkidle2' });

  // Wait for the prediction_option elements to appear
  await page.waitForSelector('[data-testid="prediction_option"]', { timeout: 15000 });

  // Grab the text content of all elements with data-testid="prediction_option"
  const results = await page.evaluate(() => {
    const elements = document.querySelectorAll('[data-testid="prediction_option"]');
    const contents = [];
    elements.forEach(el => {
      contents.push(el.textContent.trim());
    });
    return contents;
  });

  console.log('Prediction Options:', results);

  await browser.close();
})();

/**
 * Finds a common consecutive snippet of `length` characters between `str1` and `str2`.
 * Returns the first match or `null` if none found.
 */
function findCommonSnippet(str1, str2, length) {
  const minLen = Math.min(str1.length, str2.length);
  for (let i = 0; i <= minLen - length; i++) {
    const snippet = str1.slice(i, i + length);
    if (str2.includes(snippet)) return snippet;
  }
  return null;
}
