# `tryCatch` — Result-Wrapping Utility in TypeScript

```typescript
// ─── Result Type ───────────────────────────────────────────────────────────────

type Result<T, E = unknown> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: E };

// ─── Constructors ──────────────────────────────────────────────────────────────

function ok<T>(value: T): Result<T, never> {
  return { ok: true, value } as const;
}

function err<E>(error: E): Result<never, E> {
  return { ok: false, error } as const;
}

// ─── The Wrapper ───────────────────────────────────────────────────────────────

/**
 * Wraps a synchronous or asynchronous function in a try/catch,
 * returning a `Result<T, E>` instead of throwing.
 *
 * @example
 * const res = tryCatch(() => JSON.parse("not json"));
 * if (!res.ok) console.error(res.error); // SyntaxError
 *
 * const asyncRes = await tryCatch(async () => fetch("/api").then(r => r.json()));
 */
function tryCatch<T, E = unknown>(fn: () => T): Result<T, E>;
function tryCatch<T, E = unknown>(fn: () => Promise<T>): Promise<Result<T, E>>;
function tryCatch<T, E = unknown>(
  fn: () => T | Promise<T>,
): Result<T, E> | Promise<Result<T, E>> {
  try {
    const result = fn();

    // Async path: the function returned a Promise
    if (result instanceof Promise) {
      return result.then(
        (value) => ok(value),
        (error) => err(error as E),
      );
    }

    // Sync path
    return ok(result as T);
  } catch (error) {
    return err(error as E);
  }
}

// ─── Result Helpers (optional but ergonomic) ───────────────────────────────────

declare module "./result" {
  // (shown here for completeness; in practice you'd extend or use a namespace)
}

interface ResultMethods<T, E> {
  /** Returns the value or throws the error. */
  unwrap(): T;
  /** Returns the value or a fallback. */
  unwrapOr(fallback: T): T;
  /** Returns the value or the result of `fn(error)`. */
  unwrapOrElse(fn: (e: E) => T): T;
  /** True if the result is `ok`. */
  isOk(): this is { ok: true; value: T };
  /** True if the result is `err`. */
  isErr(): this is { ok: false; error: E };
  /** Transforms the success value. */
  map<U>(fn: (value: T) => U): Result<U, E>;
  /** Chains another fallible operation. */
  andThen<U>(fn: (value: T) => Result<U, E>): Result<U, E>;
  /** Transforms the error. */
  mapErr<F>(fn: (error: E) => F): Result<T, F>;
  /** Attaches a side-effect to the success value. */
  inspect(fn: (value: T) => void): Result<T, E>;
  /** Attaches a side-effect to the error. */
  inspectErr(fn: (error: E) => void): Result<T, E>;
}

/**
 * Wraps a plain `Result` literal with the helper methods.
 * Call it on the output of `tryCatch` / `ok` / `err`.
 */
function withResult<T, E = unknown>(r: Result<T, E>): ResultMethods<T, E> {
  return {
    unwrap() {
      if (r.ok) return r.value;
      throw r.error;
    },
    unwrapOr(fallback: T) {
      return r.ok ? r.value : fallback;
    },
    unwrapOrElse(fn: (e: E) => T) {
      return r.ok ? r.value : fn(r.error);
    },
    isOk() {
      return r.ok;
    },
    isErr() {
      return !r.ok;
    },
    map<U>(fn: (value: T) => U): Result<U, E> {
      return r.ok ? ok(fn(r.value)) : err(r.error);
    },
    andThen<U>(fn: (value: T) => Result<U, E>): Result<U, E> {
      return r.ok ? fn(r.value) : err(r.error);
    },
    mapErr<F>(fn: (error: E) => F): Result<T, F> {
      return r.ok ? ok(r.value) : err(fn(r.error));
    },
    inspect(fn: (value: T) => void): Result<T, E> {
      if (r.ok) fn(r.value);
      return r;
    },
    inspectErr(fn: (error: E) => void): Result<T, E> {
      if (!r.ok) fn(r.error);
      return r;
    },
  };
}

// ─── Usage Examples ────────────────────────────────────────────────────────────

// 1. Synchronous
const parse = tryCatch<unknown, SyntaxError>(() =>
  JSON.parse("not valid json"),
);
// parse: Result<unknown, SyntaxError>
// { ok: false, error: SyntaxError: ... }

// 2. Asynchronous
const fetchUser = tryCatch(async () => {
  const res = await fetch("/api/user");
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
});
// fetchUser: Promise<Result<unknown, Error>>

// 3. Chaining with helpers
const result = withResult(
  tryCatch(() => JSON.parse('{"name":"Ada"}')),
)
  .map((data) => (data as { name: string }).name.toUpperCase())
  .unwrapOr("UNKNOWN");
// "ADA"

// 4. Narrowing with type guards
const r = withResult(tryCatch(() => parseInt("abc")));
if (r.isOk()) {
  // r.value is `number` here
  console.log(r.value);
} else {
  // r.error is `unknown` here
  console.error(r.error);
}
```

## Why this design?

| Decision | Rationale |
|---|---|
| **Discriminated union** (`ok: true / false`) | Compiler narrows the type on a simple `if (r.ok)` check — no `instanceof` needed. |
| **`readonly` fields** | Prevents accidental mutation of the result after creation. |
| **`E = unknown` default** | Safe by default; you can narrow with `tryCatch<number, TypeError>(…)`. |
| **Overloads for sync / async** | Callers get the exact return type (`Result<T,E>` vs `Promise<Result<T,E>>`) without `.then()` gymnastics. |
| **`Promise.then` for async** | Catches *both* a synchronous throw *and* a rejected promise in one call. |
| **`withResult` helpers** | Keeps the core `Result` a plain data type (JSON-serialisable, easy to test) while giving you a fluent API when you want one. |
| **`as const` in constructors** | Locks the literal types so `ok(1)` is `{ ok: true, value: number }`, not `{ ok: boolean, value: number }`. |

