import Foundation

enum PointType: String, CaseIterable, Codable {
    case winner        = "Winner"
    case unforcedError = "Unforced Error"
    case forcedError   = "Forced Error"
    case ace           = "Ace"
    case returnWinner  = "Return Winner"
    case serveWinner   = "Serve Winner"
    case other         = "Other"
}

struct Point: Codable, Identifiable {
    let id: UUID
    let player: Int          // 0 or 1
    let type: PointType
    let timestamp: Date
    let setIndex: Int
    let gameIndex: Int

    init(player: Int, type: PointType, setIndex: Int, gameIndex: Int) {
        self.id = UUID()
        self.player = player
        self.type = type
        self.timestamp = Date()
        self.setIndex = setIndex
        self.gameIndex = gameIndex
    }
}
