### `Models/Match.swift`

```swift
import Foundation

enum MatchStatus: String, Codable {
    case inProgress
    case finished
}

struct Match: Codable, Identifiable {
    let id: UUID
    var player1Name: String
    var player2Name: String
    var sets: [Set]
    var status: MatchStatus
    var allPoints: [Point]
    var startDate: Date

    init(player1Name: String, player2Name: String) {
        self.id = UUID()
        self.player1Name = player1Name
        self.player2Name = player2Name
        self.sets = [Set()]
        self.status = .inProgress
        self.allPoints = []
        self.startDate = Date()
    }

    var currentSet: Set {
        get { sets[sets.count - 1] }
        set { sets[sets.count - 1] = newValue }
    }

    var currentGame: Game {
        get { currentSet.games[currentSet.games.count - 1] }
        set { currentSet.games[currentSet.games.count - 1] = newValue }
    }

    var setsWonByPlayer1: Int {
        sets.filter { $0.winner == 0 }.count
    }

    var setsWonByPlayer2: Int {
        sets.filter { $0.winner == 1 }.count
    }

    var winner: Int? {
        if setsWonByPlayer1 == 2 { return 0 }
        if setsWonByPlayer2 == 2 { return 1 }
        return nil
    }
}
