## 2. Tennis Logic Engine

### `Logic/TennisEngine.swift`

```swift
import Foundation

struct TennisEngine {
    // MARK: - Point Scoring
    static let pointNames = ["0", "15", "30", "40"]

    /// Record a point for `player` (0 or 1) in the current game.
    /// Returns (gameWon: Bool, setWon: Bool, matchWon: Bool)
    static func recordPoint(
        _ match: inout Match,
        player: Int,
        pointType: PointType
    ) -> (gameWon: Bool, setWon: Bool, matchWon: Bool) {

        var gameWon = false
        var setWon = false
        var matchWon = false

        let setIndex = match.sets.count - 1
        let gameIndex = match.sets[setIndex].games.count - 1

        // Create point record
        let point = Point(player: player, type: pointType, setIndex: setIndex, gameIndex: gameIndex)
        match.allPoints.append(point)

        // Update current game
        var game = match.currentGame
        if player == 0 {
            game.player1Points += 1
        } else {
            game.player2Points += 1
        }
        game.points.append(point)

        // Check if game is won
        if isGameWon(p1: game.player1Points, p2: game.player2Points) {
            game.winner = player
            gameWon = true

            // Update set games
            var set = match.currentSet
            if player == 0 {
                set.player1Games += 1
            } else {
                set.player2Games += 1
            }

            // Check tiebreak
            if set.player1Games == 6 && set.player2Games == 6 {
                set.isTiebreak = true
                // Tiebreak: first to 7, win by 2
                if isTiebreakWon(p1: game.player1Points, p2: game.player2Points) {
                    set.winner = player
                    setWon = true
                }
            } else if isSetWon(p1: set.player1Games, p2: set.player2Games) {
                set.winner = player
                setWon = true
            }

            match.sets[setIndex] = set

            // Check match won
            if setWon {
                if match.setsWonByPlayer1 == 2 || match.setsWonByPlayer2 == 2 {
                    match.status = .finished
                    matchWon = true
                } else {
                    // Start new set
                    match.sets.append(Set())
                }
            }
        }

        // Write back current game
        match.sets[setIndex].games[gameIndex] = game

        return (gameWon, setWon, matchWon)
    }

    // MARK: - Game Won Logic
    static func isGameWon(p1: Int, p2: Int) -> Bool {
        // Normal: reach 4 points with 2+ lead
        if p1 >= 4 && p1 - p2 >= 2 { return true }
        if p2 >= 4 && p2 - p1 >= 2 { return true }
        return false
    }

    // MARK: - Tiebreak Won Logic
    static func isTiebreakWon(p1: Int, p2: Int) -> Bool {
        if p1 >= 7 && p1 - p2 >= 2 { return true }
        if p2 >= 7 && p2 - p1 >= 2 { return true }
        return false
    }

    // MARK: - Set Won Logic
    static func isSetWon(p1: Int, p2: Int) -> Bool {
        if p1 >= 6 && p1 - p2 >= 2 { return true }
        if p2 >= 6 && p2 - p1 >= 2 { return true }
        return false
    }

    // MARK: - Display Score
    static func gameScoreString(p1: Int, p2: Int) -> String {
        if p1 >= 3 && p2 >= 3 {
            if p1 == p2 { return "Deuce" }
            if p1 > p2 { return "Ad - 40" }
            return "40 - Ad"
        }
        let s1 = p1 < 4 ? pointNames[p1] : "\(p1)"
        let s2 = p2 < 4 ? pointNames[p2] : "\(p2)"
        return "\(s1) - \(s2)"
    }

    // MARK: - Statistics
    struct PlayerStats {
        var winners: Int = 0
        var unforcedErrors: Int = 0
        var forcedErrors: Int = 0
        var aces: Int = 0
        var returnWinners: Int = 0
        var serveWinners: Int = 0
        var totalPoints: Int = 0
        var pointsWon: Int = 0

        var unforcedErrorRate: Double {
            totalPoints > 0 ? Double(unforcedErrors) / Double(totalPoints) : 0
        }

        var winnerRate: Double {
            totalPoints > 0 ? Double(winners) / Double(totalPoints) : 0
        }
    }

    static func computeStats(for match: Match) -> (PlayerStats, PlayerStats) {
        var s1 = PlayerStats()
        var s2 = PlayerStats()

        for point in match.allPoints {
            let stats = point.player == 0 ? &s1 : &s2
            stats.totalPoints += 1
            stats.pointsWon += 1

            switch point.type {
            case .winner:        stats.winners += 1
            case .unforcedError: stats.unforcedErrors += 1
            case .forcedError:   stats.forcedErrors += 1
            case .ace:           stats.aces += 1
            case .returnWinner:  stats.returnWinners += 1
            case .serveWinner:   stats.serveWinners += 1
            case .other:         break
            }
        }
        return (s1, s2)
    }
}
