import UIKit

class MatchViewController: UIViewController {

    // MARK: - Properties
    private var match: Match!
    private var advancedMode: Bool = false

    // MARK: - UI Elements
    private let player1Label = UILabel()
    private let player2Label = UILabel()
    private let setScoreLabel = UILabel()
    private let gameScoreLabel = UILabel()
    private let pointScoreLabel = UILabel()
    private let setHistoryLabel = UILabel()
    private let statusLabel = UILabel()

    private let pointButtons: [UIButton] = []
    private let advancedToggle = UISwitch()
    private let statsButton = UIButton(type: .system)
    private let newMatchButton = UIButton(type: .system)

    private let scrollView = UIScrollView()
    private let contentStack = UIStackView()

    // MARK: - Lifecycle
    override func viewDidLoad() {
        super.viewDidLoad()
        view.backgroundColor = .systemBackground
        title = "Tennis Score Tracker"
        setupUI()
        startNewMatch()
    }

    // MARK: - Setup
    private func setupUI() {
        scrollView.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(scrollView)

        contentStack.axis = .vertical
        contentStack.spacing = 16
        contentStack.translatesAutoresizingMaskIntoConstraints = false
        scrollView.addSubview(contentStack)

        NSLayoutConstraint.activate([
            scrollView.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor),
            scrollView.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            scrollView.trailingAnchor.constraint(equalTo: view.trailingAnchor),
            scrollView.bottomAnchor.constraint(equalTo: view.bottomAnchor),
            contentStack.topAnchor.constraint(equalTo: scrollView.topAnchor),
            contentStack.leadingAnchor.constraint(equalTo: scrollView.leadingAnchor, constant: 20),
            contentStack.trailingAnchor.constraint(equalTo: scrollView.trailingAnchor, constant: -20),
            contentStack.bottomAnchor.constraint(equalTo: scrollView.bottomAnchor),
            contentStack.widthAnchor.constraint(equalTo: scrollView.widthAnchor, constant: -40)
        ])

        // Player name fields
        let p1Field = UITextField()
        p1Field.placeholder = "Player 1 Name"
        p1Field.borderStyle = .roundedRect
        p1Field.tag = 101
        let p2Field = UITextField()
        p2Field.placeholder = "Player 2 Name"
        p2Field.borderStyle = .roundedRect
        p2Field.tag = 102

        let startBtn = UIButton(type: .system)
        startBtn.setTitle("Start Match", for: .normal)
        startBtn.titleLabel?.font = .systemFont(ofSize: 18, weight: .bold)
        startBtn.addTarget(self, action: #selector(startMatchTapped), for: .touchUpInside)

        contentStack.addArrangedSubview(p1Field)
        contentStack.addArrangedSubview(p2Field)
        contentStack.addArrangedSubview(startBtn)

        // Divider
        let divider = UIView()
        divider.backgroundColor = .separator
        divider.heightAnchor.constraint(equalToConstant: 1).isActive = true
        contentStack.addArrangedSubview(divider)

        // Scoreboard section
        let scoreboardCard = createCard()
        contentStack.addArrangedSubview(scoreboardCard)

        player1Label.font = .systemFont(ofSize: 22, weight: .bold)
        player2Label.font = .systemFont(ofSize: 22, weight: .bold)
        setScoreLabel.font = .systemFont(ofSize: 16, weight: .semibold)
        gameScoreLabel.font = .systemFont(ofSize: 16, weight: .semibold)
        pointScoreLabel.font = .systemFont(ofSize: 48, weight: .heavy)
        pointScoreLabel.textAlignment = .center
        setHistoryLabel.font = .monospacedDigitSystemFont(ofSize: 14, weight: .medium)
        setHistoryLabel.textAlignment = .center
        statusLabel.font = .systemFont(ofSize: 14, weight: .medium)
        statusLabel.textColor = .systemGreen
        statusLabel.textAlignment = .center

        let p1Row = UIStackView(arrangedSubviews: [player1Label, setScoreLabel])
        p1Row.distribution = .fillEqually
        let p2Row = UIStackView(arrangedSubviews: [player2Label, setScoreLabel])
        p2Row.distribution = .fillEqually

        scoreboardCard.addArrangedSubview(p1Row)
        scoreboardCard.addArrangedSubview(pointScoreLabel)
        scoreboardCard.addArrangedSubview(gameScoreLabel)
        scoreboardCard.addArrangedSubview(p2Row)
        scoreboardCard.addArrangedSubview(setHistoryLabel)
        scoreboardCard.addArrangedSubview(statusLabel)

        // Point buttons
        let pointBtnTitle = "Point"
        let p1PointBtn = makePointButton(title: "P1 \(pointBtnTitle)", color: .systemBlue, player: 0)
        let p2PointBtn = makePointButton(title: "P2 \(pointBtnTitle)", color: .systemRed, player: 1)

        let pointRow = UIStackView(arrangedSubviews: [p1PointBtn, p2PointBtn])
        pointRow.distribution = .fillEqually
        pointRow.spacing = 12
        contentStack.addArrangedSubview(pointRow)

        // Advanced toggle
        let advRow = UIStackView(arrangedSubviews: [
            { let l = UILabel(); l.text = "Advanced Point Details"; l.font = .systemFont(ofSize: 15); return l }(),
            advancedToggle
        ])
        advRow.spacing = 10
        advancedToggle.addTarget(self, action: #selector(advancedToggled), for: .valueChanged)
        contentStack.addArrangedSubview(advRow)

        // Stats & New Match buttons
        statsButton.setTitle("View Statistics", for: .normal)
        statsButton.titleLabel?.font = .systemFont(ofSize: 16, weight: .semibold)
        statsButton.addTarget(self, action: #selector(showStats), for: .touchUpInside)

        newMatchButton.setTitle("New Match", for: .normal)
        newMatchButton.titleLabel?.font = .systemFont(ofSize: 16, weight: .semibold)
        newMatchButton.addTarget(self, action: #selector(confirmNewMatch), for: .touchUpInside)

        let bottomRow = UIStackView(arrangedSubviews: [statsButton, newMatchButton])
        bottomRow.distribution = .fillEqually
        bottomRow.spacing = 12
        contentStack.addArrangedSubview(bottomRow)
    }

    private func createCard() -> UIStackView {
        let card = UIStackView()
        card.axis = .vertical
        card.spacing = 8
        card.backgroundColor = .secondarySystemBackground
        card.layer.cornerRadius = 12
        card.layer.shadowOpacity = 0.1
        card.layer.shadowRadius = 4
        card.isLayoutMarginsRelativeArrangement = true
        card.layoutMargins = UIEdgeInsets(top: 16, left: 16, bottom: 16, right: 16)
        return card
    }

    private func makePointButton(title: String, color: UIColor, player: Int) -> UIButton {
        let btn = UIButton(type: .system)
        btn.setTitle(title, for: .normal)
        btn.backgroundColor = color
        btn.setTitleColor(.white, for: .normal)
        btn.titleLabel?.font = .systemFont(ofSize: 18, weight: .bold)
        btn.layer.cornerRadius = 10
        btn.heightAnchor.constraint(equalToConstant: 56).isActive = true
        btn.tag = player
        btn.addTarget(self, action: #selector(pointTapped(_:)), for: .touchUpInside)
        return btn
    }

    // MARK: - Actions
    @objc private func startMatchTapped() {
        guard let p1 = view.viewWithTag(101) as? UITextField,
              let p2 = view.viewWithTag(102) as? UITextField,
              !p1.text!.isEmpty, !p2.text!.isEmpty else {
            showAlert("Please enter both player names.")
            return
        }
        match = Match(player1Name: p1.text!, player2Name: p2.text!)
        updateUI()
    }

    @objc private func pointTapped(_ sender: UIButton) {
        guard match != nil, match.status == .inProgress else { return }
        let player = sender.tag

        if advancedMode {
            // Show point detail picker
            let detailVC = PointDetailViewController(player: player)
            detailVC.onPointRecorded = { [weak self] pointType in
                self?.recordPoint(player: player, type: pointType)
            }
            detailVC.modalPresentationStyle = .pageSheet
            if let sheet = detailVC.sheetPresentationController {
                sheet.detents = [.medium]
            }
            present(detailVC, animated: true)
        } else {
            recordPoint(player: player, type: .other)
        }
    }

    private func recordPoint(player: Int, type: PointType) {
        let result = TennisEngine.recordPoint(&match, player: player, pointType: type)
        updateUI()

        if result.matchWon {
            let winner = match.winner!
            let name = winner == 0 ? match.player1Name : match.player2Name
            showAlert("\(name) wins the match! 🏆")
        } else if result.setWon {
            let winner = match.sets.last!.winner!
            let name = winner == 0 ? match.player1Name : match.player2Name
            showAlert("\(name) wins the set!")
        }
    }

    @objc private func advancedToggled() {
        advancedMode = advancedToggle.isOn
    }

    @objc private func showStats() {
        guard match != nil else { return }
        let statsVC = StatsViewController(match: match)
        let nav = UINavigationController(rootViewController: statsVC)
        nav.modalPresentationStyle = .fullScreen
        present(nav, animated: true)
    }

    @objc private func confirmNewMatch() {
        let alert = UIAlertController(
            title: "New Match",
            message: "Start a new match? Current progress will be lost.",
            preferredStyle: .alert
        )
        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel))
        alert.addAction(UIAlertAction(title: "New Match", style: .destructive) { [weak self] _ in
            self?.startNewMatch()
        })
        present(alert, animated: true)
    }

    private func startNewMatch() {
        match = nil
        updateUI()
    }

    // MARK: - UI Update
    private func updateUI() {
        guard let match else {
            player1Label.text = "Player 1"
            player2Label.text = "Player 2"
            pointScoreLabel.text = "–"
            gameScoreLabel.text = ""
            setScoreLabel.text = ""
            setHistoryLabel.text = ""
            statusLabel.text = "Tap 'Start Match' to begin"
            return
        }

        player1Label.text = match.player1Name
        player2Label.text = match.player2Name

        let set = match.currentSet
        let game = set.games.last!

        // Point score
        if set.isTiebreak {
            pointScoreLabel.text = "\(game.player1Points) - \(game.player2Points)"
        } else {
            pointScoreLabel.text = TennisEngine.gameScoreString(p1: game.player1Points, p2: game.player2Points)
        }

        // Game score
        gameScoreLabel.text = "Games: \(set.player1Games) - \(set.player2Games)"

        // Set score
        setScoreLabel.text = "Sets: \(match.setsWonByPlayer1) - \(match.setsWonByPlayer2)"

        // Set history
        let history = match.sets.enumerated().map { (i, s) -> String in
            if let w = s.winner {
                return w == 0 ? "S\(i+1): ✓" : "S\(i+1): ✗"
            }
            return "S\(i+1): \(s.player1Games)-\(s.player2Games)"
        }.joined(separator: "  |  ")
        setHistoryLabel.text = history

        // Status
        if match.status == .finished {
            let w = match.winner!
            statusLabel.text = "🏆 \(w == 0 ? match.player1Name : match.player2Name) wins!"
            statusLabel.textColor = .systemOrange
        } else {
            statusLabel.text = "Match in progress"
            statusLabel.textColor = .systemGreen
        }
    }

    private func showAlert(_ message: String) {
        let alert = UIAlertController(title: "Tennis Score Tracker", message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "OK", style: .default))
        present(alert, animated: true)
    }
}
