          const body = method.defaultBody && Object.keys(method.defaultBody).length > 0
            ? JSON.stringify(method.defaultBody, null, 2)
            : "";
          setRequestBody(body);
          setResponseText("");
          setStatus(null);
          setStatusMessage("");
          setMockStatus(null);
        };

        const sendRequest = async () => {
          if (!requestUrl) {
            setStatus("error");
            setStatusMessage("Select a method first.");
            return;
          }
          setIsSending(true);
          setStatus(null);
          setStatusMessage("");
          try {
            const options = { method: "POST" };
            if (requestBody.trim()) {
              options.headers = { "Content-Type": "application/json" };
              options.body = requestBody;
            }
            const response = await fetch(requestUrl, options);
            const text = await response.text();
            let formatted;
            try {
              formatted = JSON.stringify(JSON.parse(text), null, 2);
            } catch {
              formatted = text;
            }
            setResponseText(formatted);
            if (response.ok) {
              setStatus("success");
              setStatusMessage(`HTTP ${response.status}`);
            } else {
              setStatus("error");
              setStatusMessage(`HTTP ${response.status}`);
            }
          } catch (err) {
            setResponseText(JSON.stringify({ error: err.message }, null, 2));
            setStatus("error");
            setStatusMessage(err.message);
          } finally {
            setIsSending(false);
          }
        };

        const setAsMock = async () => {
          if (!requestUrl || !responseText.trim()) {
            setMockStatus("error");
            return;
          }
          // Extract method name from URL
          const urlParts = requestUrl.split("/");
          const methodName = urlParts[urlParts.length - 1];
          setIsSettingMock(true);
          setMockStatus(null);
          try {
            const mockBody = {
              api: methodName,
              response: JSON.parse(responseText),
