            const res = await fetch(`/api/${apiPrefix}/setResponse`, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify(mockBody),
            });
            if (res.ok) {
              setMockStatus("success");
            } else {
              const errText = await res.text();
              setMockStatus("error");
              setStatusMessage(`Set mock failed: ${errText}`);
            }
          } catch (err) {
            setMockStatus("error");
            setStatusMessage(`Set mock failed: ${err.message}`);
          } finally {
            setIsSettingMock(false);
