                      ${mockStatus === "success" ? "Mock Set ✓" : "Mock Failed"}
                    </span>
                  `}
                </div>
                <label class="form-label">Response (JSON) — editable</label>
                <textarea
                  class="form-input json-textarea"
                  rows="8"
                  placeholder="Response will appear here..."
                  value=${responseText}
                  onInput=${(e) => setResponseText(e.target.value)}
                  spellcheck="false"></textarea>
              </div>

              <div style="margin-top:10px;">
                <button
                  class="btn btn-ghost"
                  disabled=${isSettingMock || !responseText.trim() || !requestUrl}
                  onClick=${setAsMock}>
                  ${isSettingMock ? "Setting..." : "Set as Mock Response"}
                </button>
                <small class="text-muted" style="margin-left:8px;">
                  Modifies response above, then posts to /api/${apiPrefix}/setResponse
