```csharp
using UnityEngine;
using System.Collections.Generic;

public class Grid : MonoBehaviour
{
    public int width;
    public int height;
    public Node[,] nodes;

    private void Awake()
    {
        nodes = new Node[height, width];

        for (int z = 0; z < height; z++)
        {
            for (int x = 0; x < width; x++)
            {
                nodes[z, x] = new Node(z, x, false);
            }
        }
    }

    public Node GetNodeFromWorldPosition(Vector3 worldPos)
    {
        int col = Mathf.RoundToInt(worldPos.x);
        int row = Mathf.RoundToInt(worldPos.z);

        if (col < 0 || col >= width || row < 0 || row >= height)
            return null;

        return nodes[row, col];
    }

    public List<Node> GetNeighbors(Node node)
    {
        List<Node> neighbors = new List<Node>();

        int[] dr = { -1,  0,  1,  0, -1, -1,  1,  1 };
        int[] dc = {  0,  1,  0, -1, -1,  1,  1, -1 };

        for (int i = 0; i < 8; i++)
        {
            int r = node.row + dr[i];
            int c = node.col + dc[i];

            if (r < 0 || r >= height || c < 0 || c >= width)
                continue;

            neighbors.Add(nodes[r, c]);
        }

        return neighbors;
    }

    public void SetNodeBlocked(int row, int col, bool blocked)
    {
        if (row >= 0 && row < height && col >= 0 && col < width)
            nodes[row, col].isBlocked = blocked;
    }
}
