```js
class Events {
  #subscribers;

  constructor() {
    this.#subscribers = new Map();
  }

  /**
   * Register a callback for one or more events.
   * @param {string|string[]} eventName - Event name(s) to listen to.
   * @param {Function} callback - Function to invoke when the event fires.
   * @returns {Events} this (for chaining)
   */
  subscribe(eventName, callback) {
    if (typeof callback !== "function") {
      throw new TypeError("callback must be a function");
    }

    const names = Array.isArray(eventName) ? eventName : [eventName];

    for (const name of names) {
      if (!this.#subscribers.has(name)) {
        this.#subscribers.set(name, []);
      }
      this.#subscribers.get(name).push(callback);
    }

    return this;
  }

  /**
   * Remove a previously registered callback.
   * @param {string|string[]} eventName - Event name(s) to unbind from.
   * @param {Function} callback - The exact function reference to remove.
   * @returns {Events} this (for chaining)
   */
  unsubscribe(eventName, callback) {
    const names = Array.isArray(eventName) ? eventName : [eventName];

    for (const name of names) {
      const callbacks = this.#subscribers.get(name);
      if (!callbacks) continue;

      const idx = callbacks.indexOf(callback);
      if (idx !== -1) {
        callbacks.splice(idx, 1);
      }

      // Clean up empty arrays to avoid memory leaks
      if (callbacks.length === 0) {
        this.#subscribers.delete(name);
      }
    }

    return this;
  }

  /**
   * Emit one or more events, calling all registered callbacks.
   * @param {string|string[]} eventNames - Event name(s) to trigger.
   * @param {...*} options - Arguments forwarded to every callback.
   * @returns {Events} this (for chaining)
   */
  trigger(eventNames, ...options) {
    const names = Array.isArray(eventNames) ? eventNames : [eventNames];

    for (const name of names) {
      const callbacks = this.#subscribers.get(name);
      if (!callbacks) continue;

      // Copy the array so unsubscribe-during-trigger doesn't mutate mid-iteration
      for (const cb of [...callbacks]) {
        cb(...options);
      }
    }

    return this;
  }

  /**
   * Remove all subscribers for a given event (or all events if omitted).
   * @param {string} [eventName]
   * @returns {Events}
   */
  clear(eventName) {
    if (eventName) {
      this.#subscribers.delete(eventName);
    } else {
      this.#subscribers.clear();
    }
    return this;
  }
}
```

