// Subscribe (supports chaining)
events
  .subscribe("user:login", onUserLogin)
  .subscribe(["user:login", "user:logout"], onAudit);

// Trigger a single event
events.trigger("user:login", { name: "Alice" }, { ip: "10.0.0.1" });
// → "User Alice logged in" { ip: '10.0.0.1' }
// → "[AUDIT] Alice →" 10.0.0.1

// Trigger multiple events at once
events.trigger(["user:logout", "user:login"], { name: "Bob" }, { ip: "10.0.0.2" });

// Unsubscribe a specific callback
events.unsubscribe("user:login", onUserLogin);

// "user:login" now only fires onAudit
events.trigger("user:login", { name: "Carol" }, { ip: "10.0.0.3" });
// → "[AUDIT] Carol →" 10.0.0.3   (onUserLogin no longer called)

// Nuclear option
events.clear();
```

### Key design decisions

| Concern | Choice |
|---|---|
| **Storage** | `Map<string, Function[]>` — O(1) lookup, no prototype-pollution risk |
| **`eventNames` param** | Accepts a single `string` *or* an `Array<string>` for both `subscribe`, `unsubscribe`, and `trigger` |
| **Safe iteration** | `trigger` iterates over a shallow copy so a callback can `unsubscribe` itself mid-fire without skipping siblings |
| **Memory hygiene** | Empty callback arrays are deleted from the map; `clear()` wipes everything |
| **Chaining** | Every method returns `this` so you can do `events.subscribe(...).subscribe(...).trigger(...)` |
| **Encapsulation** | The subscriber map is a `#` private field — no external mutation |

# Pottery Wheel & Kiln Modules

## `scripts/PotteryWheel.js`

```javascript
let id = 1;

function makePottery(shape, weight, height) {
  const pottery = {
    shape,
    weight,
    height,
    id,
  };

  id++;

  return pottery;
}

export { makePottery };
```

## `scripts/Kiln.js`

```javascript
function firePottery(pottery, temperature) {
  pottery.fired = true;
  pottery.cracked = temperature > 2200;

  return pottery;
}

export { firePottery };
```

## `main.js`

```javascript
import { makePottery } from "./scripts/PotteryWheel.js";
import { firePottery } from "./scripts/Kiln.js";

// --- Make 5 pieces of pottery ---
const piece1 = makePottery("Mug", 1, 3);
const piece2 = makePottery("Platter", 5, 7);
const piece3 = makePottery("Vase", 3, 12);
const piece4 = makePottery("Bowl", 2, 4);
const piece5 = makePottery("Teapot", 4, 6);

console.log("=== Pieces of Pottery ===");
console.log(piece1);
console.log(piece2);
console.log(piece3);
console.log(piece4);
console.log(piece5);

// --- Fire each piece in the kiln ---
const fired1 = firePottery(piece1, 1800);
const fired2 = firePottery(piece2, 2100);
const fired3 = firePottery(piece3, 2300); // too hot!
const fired4 = firePottery(piece4, 2200); // right at the limit
const fired5 = firePottery(piece5, 1950);

console.log("\n=== Fired Pottery ===");
console.log(fired1);
console.log(fired2);
console.log(fired3);
console.log(fired4);
console.log(fired5);
```

## Expected Output

```
=== Pieces of Pottery ===
{ shape: 'Mug', weight: 1, height: 3, id: 1 }
{ shape: 'Platter', weight: 5, height: 7, id: 2 }
{ shape: 'Vase', weight: 3, height: 12, id: 3 }
{ shape: 'Bowl', weight: 2, height: 4, id: 4 }
{ shape: 'Teapot', weight: 4, height: 6, id: 5 }

=== Fired Pottery ===
{ shape: 'Mug', weight: 1, height: 3, id: 1, fired: true, cracked: false }
{ shape: 'Platter', weight: 5, height: 7, id: 2, fired: true, cracked: false }
{ shape: 'Vase', weight: 3, height: 12, id: 3, fired: true, cracked: true }
{ shape: 'Bowl', weight: 2, height: 4, id: 4, fired: true, cracked: false }
{ shape: 'Teapot', weight: 4, height: 6, id: 5, fired: true, cracked: false }
```

## How It Works

| Piece | Temperature | Cracked? | Reason |
|-------|------------|----------|--------|
| Mug | 1800 | `false` | ≤ 2200 |
| Platter | 2100 | `false` | ≤ 2200 |
| **Vase** | **2300** | **`true`** | **> 2200 (too hot!)** |
| Bowl | 2200 | `false` | At the limit (≤ 2200) |
| Teapot | 1950 | `false` | ≤ 2200 |

- **`PotteryWheel.js`** keeps a module-level `id` counter starting at `1`. Each call to `makePottery` assigns the current `id` to the new object, then increments it for the next call.
- **`Kiln.js`** mutates the passed-in object by adding `fired: true` and a `cracked` boolean based on the temperature threshold of 2200, then returns the same (now augmented) object.
- The Vase at **2300°** is the piece that gets cracked, satisfying the "at least one too hot" requirement.

