<script>
/* ================================================================
   VIRTUAL FILE SYSTEM
================================================================ */
const FS = {
  '/': {
    type: 'dir',
    children: {
      'Documents': {
        type: 'dir',
        children: {
          'readme.txt': { type: 'file', content: 'Welcome to WebOS!\n\nThis is a simple operating system emulator built with HTML, CSS, and JavaScript.' },
          'todo.txt': { type: 'file', content: '- Explore the file system\n- Write some notes\n- Try the terminal' }
        }
      },
      'Pictures': { type: 'dir', children: {} },
      'Music': { type: 'dir', children: {} },
      'notes.txt': { type: 'file', content: 'Hello from the desktop!' }
    }
  }
};

function fsResolve(path) {
  const parts = path.split('/').filter(Boolean);
  let node = FS['/'];
  for (const p of parts) {
    if (node.type !== 'dir' || !node.children[p]) return null;
    node = node.children[p];
  }
  return node;
}

function fsJoin(base, name) {
  if (base === '/') return '/' + name;
  return base + '/' + name;
}

function fsParent(path) {
  if (path === '/') return '/';
  const i = path.lastIndexOf('/');
  return i <= 0 ? '/' : path.slice(0, i);
}

function fsIcon(node) {
  if (node.type === 'dir') return '📁';
  if (node.name && node.name.endsWith('.txt')) return '📄';
  if (node.name && node.name.endsWith('.png')) return '🖼️';
  return '📄';
}

/* ================================================================
   WINDOW MANAGER
================================================================ */
const WM = {
  windows: new Map(),
  zCounter: 100,
  openCount: 0,

  create(opts) {
    const id = 'win-' + Date.now() + '-' + Math.floor(Math.random() * 1000);
    const win = document.createElement('div');
    win.className = 'window';
    win.id = id;
    win.style.width = (opts.width || 500) + 'px';
    win.style.height = (opts.height || 360) + 'px';
    win.style.left = (60 + (this.openCount % 6) * 30) + 'px';
    win.style.top = (40 + (this.openCount % 6) * 30) + 'px';
    this.openCount++;

    win.innerHTML = `
      <div class="titlebar">
        <div class="title"><span>${opts.icon}</span><span>${opts.title}</span></div>
        <div class="btns">
          <button class="btn min" title="Minimize">─</button>
          <button class="btn max" title="Maximize">□</button>
          <button class="btn close" title="Close">✕</button>
        </div>
      </div>
      <div class="window-body"></div>
      <div class="resize-handle"></div>
    `;

    document.getElementById('desktop').appendChild(win);

    const body = win.querySelector('.window-body');
    const appEl = opts.render(body, id);
    if (appEl && appEl !== body) body.appendChild(appEl);

    const record = { id, el: win, title: opts.title, icon: opts.icon, minimized: false, app: appEl };
    this.windows.set(id, record);

    // --- Focus / z-order ---
    const focus = () => {
      win.style.zIndex = ++this.zCounter;
      document.querySelectorAll('.window').forEach(w => w.classList.remove('active'));
      win.classList.add('active');
      this.updateTaskbar();
    };
    win.addEventListener('mousedown', focus);
    focus();

    // --- Close / Minimize / Maximize ---
    win.querySelector('.close').onclick = (e) => { e.stopPropagation(); this.close(id); };
    win.querySelector('.min').onclick = (e) => {
      e.stopPropagation();
      record.minimized = true;
      win.style.display = 'none';
      this.updateTaskbar();
    };
    win.querySelector('.max').onclick = (e) => {
      e.stopPropagation();
      if (win.classList.contains('maximized')) {
        win.classList.remove('maximized');
        Object.assign(win.style, record.prevRect);
      } else {
        record.prevRect = {
          left: win.style.left, top: win.style.top,
          width: win.style.width, height: win.style.height
        };
        win.classList.add('maximized');
        Object.assign(win.style, { left: '0', top: '0', width: '100%', height: '100%' });
      }
    };

    // --- Drag ---
    const titlebar = win.querySelector('.titlebar');
    titlebar.addEventListener('mousedown', (e) => {
      if (e.target.tagName === 'BUTTON') return;
      if (win.classList.contains('maximized')) return;
      const startX = e.clientX - win.offsetLeft;
      const startY = e.clientY - win.offsetTop;
      const move = (ev) => {
        win.style.left = (ev.clientX - startX) + 'px';
        win.style.top = Math.max(0, ev.clientY - startY) + 'px';
      };
      const up = () => {
        document.removeEventListener('mousemove', move);
        document.removeEventListener('mouseup', up);
      };
      document.addEventListener('mousemove', move);
      document.addEventListener('mouseup', up);
    });

    // --- Resize ---
    win.querySelector('.resize-handle').addEventListener('mousedown', (e) => {
      e.stopPropagation();
      const startX = e.clientX, startY = e.clientY;
      const startW = win.offsetWidth, startH = win.offsetHeight;
      const move = (ev) => {
        win.style.width = Math.max(300, startW + ev.clientX - startX) + 'px';
        win.style.height = Math.max(200, startH + ev.clientY - startY) + 'px';
      };
      const up = () => {
        document.removeEventListener('mousemove', move);
        document.removeEventListener('mouseup', up);
      };
      document.addEventListener('mousemove', move);
      document.addEventListener('mouseup', up);
    });

    this.updateTaskbar();
    return record;
  },

  close(id) {
    const rec = this.windows.get(id);
    if (!rec) return;
    if (rec.app && rec.app.destroy) rec.app.destroy();
    rec.el.remove();
    this.windows.delete(id);
    this.updateTaskbar();
  },

  updateTaskbar() {
    const container = document.getElementById('taskItems');
    container.innerHTML = '';
    this.windows.forEach((rec) => {
      const btn = document.createElement('button');
      btn.className = 'task-item';
      btn.textContent = rec.icon + ' ' + rec.title;
      if (rec.el.classList.contains('active') && !rec.minimized) btn.classList.add('active');
      btn.onclick = () => {
        if (rec.minimized) {
          rec.minimized = false;
          rec.el.style.display = 'flex';
          rec.el.style.zIndex = ++this.zCounter;
          document.querySelectorAll('.window').forEach(w => w.classList.remove('active'));
          rec.el.classList.add('active');
        } else if (rec.el.classList.contains('active')) {
          rec.minimized = true;
          rec.el.style.display = 'none';
        } else {
          rec.el.style.zIndex = ++this.zCounter;
          document.querySelectorAll('.window').forEach(w => w.classList.remove('active'));
          rec.el.classList.add('active');
        }
        this.updateTaskbar();
      };
      container.appendChild(btn);
    });
  }
};

/* ================================================================
   APPS
================================================================ */
const Apps = {

  /* ---------- File Explorer ---------- */
  explorer: (body, winId, startPath = '/') => {
    let cwd = startPath;
    let selected = null;

    const root = document.createElement('div');
    root.style.height = '100%';
    root.style.display = 'flex';
    root.style.flexDirection = 'column';
    root.innerHTML = `
      <div class="explorer-toolbar">
        <button data-act="up">⬆ Up</button>
        <button data-act="newfile">📄 New File</button>
        <button data-act="newdir">📁 New Folder</button>
        <button data-act="delete">🗑 Delete</button>
        <div class="path-bar"></div>
      </div>
      <div class="file-grid" style="flex:1; overflow-y:auto;"></div>
    `;
    body.appendChild(root);

    const grid = root.querySelector('.file-grid');
    const pathBar = root.querySelector('.path-bar');

    function render() {
      pathBar.textContent = cwd;
      grid.innerHTML = '';
      selected = null;
      const node = fsResolve(cwd);
      if (!node || node.type !== 'dir') return;

      const entries = Object.entries(node.children).sort((a, b) => {
        if (a[1].type !== b[1].type) return a[1].type === 'dir' ? -1 : 1;
        return a[0].localeCompare(b[0]);
      });

      entries.forEach(([name, child]) => {
        const item = document.createElement('div');
        item.className = 'file-item';
        item.innerHTML = `<div class="icon">${fsIcon({ ...child, name })}</div><div class="name">${name}</div>`;
        item.onclick = () => {
          grid.querySelectorAll('.file-item').forEach(i => i.classList.remove('selected'));
          item.classList.add('selected');
          selected = name;
        };
        item.ondblclick = () => {
          const p = fsJoin(cwd, name);
          if (child.type === 'dir') { cwd = p; render(); }
          else { Apps.notepad(winId, p); }
        };
        grid.appendChild(item);
      });
    }

    root.querySelector('[data-act="up"]').onclick = () => { cwd = fsParent(cwd); render(); };

    root.querySelector('[data-act="newfile"]').onclick = () => {
      const name = prompt('New file name:');
      if (name && !fsResolve(fsJoin(cwd, name))) {
        fsResolve(cwd).children[name] = { type: 'file', content: '' };
        render();
      }
    };
    root.querySelector('[data-act="newdir"]').onclick = () => {
      const name = prompt('New folder name:');
      if (name && !fsResolve(fsJoin(cwd, name))) {
        fsResolve(cwd).children[name] = { type: 'dir', children: {} };
        render();
      }
    };
    root.querySelector('[data-act="delete"]').onclick = () => {
      if (!selected) return toast('Select an item first');
      if (!confirm(`Delete "${selected}"?`)) return;
      delete fsResolve(cwd).children[selected];
      render();
    };

    render();
    return root;
  },

  /* ---------- Notepad ---------- */
  notepad: (winId, filePath = null) => {
    const root = document.createElement('div');
    root.className = 'notepad-body';
    root.innerHTML = `
      <div class="notepad-toolbar">
        <button data-act="new">New</button>
        <button data-act="save">💾 Save</button>
        <button data-act="saveas">Save As…</button>
        <span style="margin-left:auto; font-size:11px; color:#a6adc8;" class="fp"></span>
      </div>
      <textarea spellcheck="false" placeholder="Start typing..."></textarea>
    `;
    const ta = root.querySelector('textarea');
    const fp = root.querySelector('.fp');
    let currentPath = filePath;
    if (currentPath) {
      const node = fsResolve(currentPath);
      if (node) ta.value = node.content;
      fp.textContent = currentPath;
    }

    root.querySelector('[data-act="new"]').onclick = () => {
      ta.value = ''; currentPath = null; fp.textContent = 'unsaved';
    };
    root.querySelector('[data-act="saveas"]').onclick = () => {
      const p = prompt('Save as (full path, e.g. /Documents/note.txt):', currentPath || '/Documents/untitled.txt');
      if (!p) return;
      if (!p.startsWith('/')) return toast('Path must start with /');
      const dir = fsResolve(fsParent(p));
      if (!dir || dir.type !== 'dir') return toast('Directory not found');
      const name = p.split('/').pop();
      dir.children[name] = { type: 'file', content: ta.value };
      currentPath = p;
      fp.textContent = p;
      toast('Saved to ' + p);
    };
    root.querySelector('[data-act="save"]').onclick = () => {
      if (!currentPath) return root.querySelector('[data-act="saveas"]').click();
      const node = fsResolve(currentPath);
      if (node) { node.content = ta.value; toast('Saved'); }
    };

    return root;
  },

  /* ---------- Terminal ---------- */
  terminal: (body) => {
    let cwd = '/';
    const root = document.createElement('div');
    root.className = 'terminal-body';
    body.appendChild(root);

    function promptStr() { return 'user@webos' + cwd + '$ '; }

    function print(text, cls = '') {
      const line = document.createElement('div');
      line.className = 'line ' + cls;
      line.textContent = text;
      root.insertBefore(line, inputRow);
    }

    const inputRow = document.createElement('div');
    inputRow.className = 'terminal-input-row';
    inputRow.innerHTML = `<span class="prompt">${promptStr()}</span><input type="text" autocomplete="off">`;
    root.appendChild(inputRow);
    const input = inputRow.querySelector('input');

    print('WebOS Terminal — type "help" for commands');
    input.focus();

    function exec(raw) {
      const [cmd, ...args] = raw.trim().split(/\s+/);
      const arg = args.join(' ');
      switch (cmd) {
        case '': break;
        case 'help':
          print('Commands: help, ls, cd, cat, touch, mkdir, rm, echo, pwd, clear, open');
          break;
        case 'pwd': print(cwd); break;
        case 'clear': root.querySelectorAll('.line').forEach(l => l.remove()); break;
        case 'ls': {
          const node = fsResolve(cwd);
          print(Object.keys(node.children).map(n =>
            node.children[n].type === 'dir' ? n + '/' : n
          ).join('   ') || '(empty)');
          break;
        }
        case 'cd': {
          if (!arg || arg === '/') { cwd = '/'; break; }
          let target;
          if (arg === '..') target = fsParent(cwd);
          else if (arg === '.') target = cwd;
          else target = fsJoin(cwd, arg);
          const node = fsResolve(target);
          if (node && node.type === 'dir') cwd = target;
          else print('cd: no such directory: ' + arg);
          break;
        }
        case 'cat': {
          const node = fsResolve(fsJoin(cwd, arg));
          if (node && node.type === 'file') print(node.content || '(empty file)');
          else print('cat: ' + arg + ': no such file');
          break;
        }
        case 'touch': {
          if (!arg) { print('touch: missing operand'); break; }
          const p = fsJoin(cwd, arg);
          if (!fsResolve(p)) fsResolve(cwd).children[arg] = { type: 'file', content: '' };
          break;
        }
        case 'mkdir': {
          if (!arg) { print('mkdir: missing operand'); break; }
          if (!fsResolve(fsJoin(cwd, arg))) fsResolve(cwd).children[arg] = { type: 'dir', children: {} };
          else print('mkdir: ' + arg + ': already exists');
          break;
        }
        case 'rm': {
          if (!arg) { print('rm: missing operand'); break; }
          if (fsResolve(fsJoin(cwd, arg))) delete fsResolve(cwd).children[arg];
          else print('rm: ' + arg + ': no such file');
          break;
        }
        case 'echo': {
          if (arg.includes('>')) {
            const [text, file] = arg.split('>').map(s => s.trim());
            const p = fsJoin(cwd, file);
            const node = fsResolve(p);
            if (node && node.type === 'file') node.content = text;
            else fsResolve(cwd).children[file] = { type: 'file', content: text };
          } else print(arg);
          break;
        }
        case 'open': {
          const node = fsResolve(fsJoin(cwd, arg));
          if (node && node.type === 'file') Apps.notepad(null, fsJoin(cwd, arg));
          else if (node) Apps.explorer(null, fsJoin(cwd, arg));
          else print('open: no such file or directory');
          break;
        }
        default: print(cmd + ': command not found');
      }
      inputRow.querySelector('.prompt').textContent = promptStr();
    }

    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        print(promptStr() + input.value);
        exec(input.value);
        input.value = '';
      }
    });
    root.addEventListener('click', () => input.focus());

    return root;
  },

  /* ---------- Calculator ---------- */
  calculator: (body) => {
    const root = document.createElement('div');
    root.className = 'calc-body';
    root.innerHTML = `
      <div class="calc-display">0</div>
      <div class="calc-grid">
        <button>C</button><button>⌫</button><button class="op">%</button><button class="op">÷</button>
        <button>7</button><button>8</button><button>9</button><button class="op">×</button>
        <button>4</button><button>5</button><button>6</button><button class="op">−</button>
        <button>1</button><button>2</button><button>3</button><button class="op">+</button>
        <button class="eq">=</button><button>0</button><button>.</button>
      </div>
    `;
    const display = root.querySelector('.calc-display');
    let expr = '';

    function update() { display.textContent = expr || '0'; }

    root.querySelectorAll('button').forEach(btn => {
      btn.onclick = () => {
        const v = btn.textContent;
        if (v === 'C') expr = '';
        else if (v === '⌫') expr = expr.slice(0, -1);
        else if (v === '=') {
          try {
            const safe = expr.replace(/×/g, '*').replace(/÷/g, '/').replace(/−/g, '-');
            if (!/^[\d+\-*/.()%\s]+$/.test(safe)) throw 0;
            expr = String(Function('"use strict";return (' + safe + ')')());
          } catch { expr = 'Error'; }
        }
        else expr += v;
        update();
      };
    });

    return root;
  },

  /* ---------- Settings ---------- */
  settings: (body) => {
    const wallpapers = [
      'linear-gradient(135deg, #1e3c72, #2a5298, #6dd5ed)',
      'linear-gradient(135deg, #0f0c29, #302b63, #24243e)',
      'linear-gradient(135deg, #134e5e, #71b280)',
      'linear-gradient(135deg, #42275a, #734b6d)',
      'linear-gradient(135deg, #232526, #414345)',
      'linear-gradient(135deg, #870000, #190a05)'
    ];
    const root = document.createElement('div');
    root.className = 'settings-body';
    root.innerHTML = `<h3>Wallpaper</h3><div class="wallpaper-grid"></div>`;
    const grid = root.querySelector('.wallpaper-grid');
    wallpapers.forEach(w => {
      const sw = document.createElement('div');
      sw.className = 'wallpaper-swatch';
      sw.style.background = w;
      sw.onclick = () => {
        document.getElementById('desktop').style.background = w;
        toast('Wallpaper changed');
      };
      grid.appendChild(sw);
    });
    return root;
  },

  /* ---------- About ---------- */
  about: (body) => {
    const root = document.createElement('div');
    root.className = 'settings-body';
    root.innerHTML = `
      <div style="text-align:center; padding: 20px;">
        <div style="font-size: 60px;">🖥️</div>
        <h2 style="margin: 12px 0 6px;">WebOS 1.0</h2>
        <p style="color: #a6adc8; font-size: 13px;">A tiny operating system in your browser.</p>
        <p style="color: #a6adc8; font-size: 12px; margin-top: 16px;">Built with HTML, CSS & JavaScript</p>
      </div>`;
    return root;
  }
};

/* ================================================================
   APP REGISTRY
================================================================ */
const AppRegistry = {
  'Files':      { icon: '📁', title: 'File Explorer', open: (winId) => Apps.explorer(null, null, '/'), width: 560, height: 400 },
  'Notepad':    { icon: '📝', title: 'Notepad',         open: (winId) => Apps.notepad(null), width: 480, height: 380 },
  'Terminal':   { icon: '⌨️', title: 'Terminal',        open: () => Apps.terminal(null), width: 560, height: 360 },
  'Calculator': { icon: '🧮', title: 'Calculator',      open: () => Apps.calculator(null), width: 260, height: 380 },
  'Settings':   { icon: '⚙️', title: 'Settings',        open: () => Apps.settings(null), width: 380, height: 300 },
  'About':      { icon: 'ℹ️', title: 'About WebOS',     open: () => Apps.about(null), width: 340, height: 280 }
};

function launchApp(name) {
  const app = AppRegistry[name];
  if (!app) return;
  WM.create({
    title: app.title,
    icon: app.icon,
    width: app.width,
    height: app.height,
    render: (body, winId) => app.open(winId)
  });
}

/* ================================================================
   DESKTOP ICONS
================================================================ */
const desktopIcons = [
  { name: 'Files', x: 20, y: 20 },
  { name: 'Notepad', x: 20, y: 120 },
  { name: 'Terminal', x: 20, y: 220 },
  { name: 'Calculator', x: 20, y: 320 },
  { name: 'Settings', x: 20, y: 420 }
];

const desktop = document.getElementById('desktop');
desktopIcons.forEach(({ name, x, y }) => {
  const icon = document.createElement('div');
  icon.className = 'desktop-icon';
  icon.style.left = x + 'px';
  icon.style.top = y + 'px';
  icon.innerHTML = `<div class="icon">${AppRegistry[name].icon}</div><div class="label">${name}</div>`;
  icon.ondblclick = () => launchApp(name);
  desktop.appendChild(icon);
});

/* ================================================================
   START MENU
================================================================ */
const startMenu = document.getElementById('startMenu');
const startBtn = document.getElementById('startBtn');

Object.keys(AppRegistry).forEach(name => {
  const item = document.createElement('div');
  item.className = 'menu-item';
  item.innerHTML = `<span class="icon">${AppRegistry[name].icon}</span>${name}`;
  item.onclick = () => { launchApp(name); startMenu.classList.remove('open'); };
  startMenu.appendChild(item);
});

const sep = document.createElement('div');
sep.className = 'menu-sep';
startMenu.appendChild(sep);

const shutdown = document.createElement('div');
shutdown.className = 'menu-item';
shutdown.innerHTML = `<span class="icon">⏻</span>Restart`;
shutdown.onclick = () => location.reload();
startMenu.appendChild(shutdown);

startBtn.onclick = (e) => {
  e.stopPropagation();
  startMenu.classList.toggle('open');
};
document.addEventListener('click', (e) => {
  if (!startMenu.contains(e.target) && e.target !== startBtn) startMenu.classList.remove('open');
  hideContextMenu();
});

/* ================================================================
   RIGHT-CLICK CONTEXT MENU
================================================================ */
const ctxMenu = document.getElementById('contextMenu');
function showContextMenu(x, y, items) {
  ctxMenu.innerHTML = '';
  items.forEach(({ label, action }) => {
    const el = document.createElement('div');
    el.className = 'menu-item';
    el.textContent = label;
    el.onclick = () => { hideContextMenu(); action(); };
    ctxMenu.appendChild(el);
  });
  ctxMenu.style.display = 'block';
  ctxMenu.style.left = Math.min(x, innerWidth - 180) + 'px';
  ctxMenu.style.top = Math.min(y, innerHeight - 40 * items.length) + 'px';
}
function hideContextMenu() { ctxMenu.style.display = 'none'; }

desktop.addEventListener('contextmenu', (e) => {
  e.preventDefault();
  showContextMenu(e.clientX, e.clientY, [
    { label: '📁 Open File Explorer', action: () => launchApp('Files') },
    { label: '📝 New Note', action: () => launchApp('Notepad') },
    { label: '⚙️ Settings', action: () => launchApp('Settings') },
    { label: '🔄 Refresh', action: () => toast('Desktop refreshed') }
  ]);
});

/* ================================================================
   CLOCK & TOAST
================================================================ */
function tick() {
  const now = new Date();
  document.getElementById('clock').textContent =
    now.toLocaleDateString() + '  ' + now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}
tick();
setInterval(tick, 1000);

let toastTimer;
function toast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.style.display = 'block';
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.style.display = 'none', 2500);
}

/* ================================================================
   BOOT
================================================================ */
launchApp('Files');
setTimeout(() => toast('Welcome to WebOS! Right-click the desktop for options.'), 600);
</script>
</body>
</html>
```

## Features

**Window Manager**
- Drag windows by their title bar
- Resize via the bottom-right corner handle
- Minimize / Maximize / Close buttons
- Z-order focus management (clicking a window brings it to front)
- Taskbar with running-app buttons (click to focus or minimize)

**Virtual File System**
- A nested JS object tree rooted at `/` with `Documents`, `Pictures`, and `Music`
- Helper functions for path resolution, joining, and parent lookup
- Files persist in memory across apps (save in Notepad → see it in Explorer/Terminal)

**Apps**
| App | Capabilities |
|---|---|
| 📁 File Explorer | Navigate, create files/folders, delete, double-click to open |
| 📝 Notepad | Edit text, Save / Save As to the virtual FS |
| ⌨️ Terminal | `ls`, `cd`, `cat`, `touch`, `mkdir`, `rm`, `echo >`, `pwd`, `open`, `clear` |
| 🧮 Calculator | Basic arithmetic with a safe expression evaluator |
| ⚙️ Settings | Change the desktop wallpaper |
| ℹ️ About | System info |

**UI Extras**
- Start menu, live clock, desktop right-click context menu, toast notifications, and a "Restart" (page reload) option.

Just save it as an `.html` file and open it in any modern browser — no server or dependencies needed.

# Drupal 9 – Article Teaser List by Taxonomy Tag

Below is a complete, production-ready implementation as a custom module (`article_teaser`) that queries article nodes tagged with the term **"foobar"** using an optimized Entity Query, renders them in a Bootstrap 5 card grid, and adheres to Drupal 9 coding standards (PSR-12, strict types, proper DI, access checks, caching).

---

## Module Structure

```
article_teaser/
├── article_teaser.info.yml
├── article_teaser.module
├── article_teaser.routing.yml
├── src/
│   └── Controller/
│       └── ArticleTeaserController.php
└── templates/
    └── article-teaser-list.html.twig
```

---

## `article_teaser.info.yml`

```yaml
name: 'Article Teaser'
type: module
description: 'Displays a teaser list of article nodes filtered by a taxonomy term.'
package: Custom
core_version_requirement: ^9 || ^10
```

