## `article_teaser.module`

```php
<?php

/**
 * @file
 * Contains article_teaser.module.
 *
 * Provides a custom route that renders a Bootstrap 5–styled teaser grid
 * of article nodes sharing the taxonomy term "foobar".
 */

declare(strict_types=1);

use Drupal\Core\Routing\RouteMatchInterface;

/**
 * Implements hook_theme().
 */
function article_teaser_theme(): array {
  return [
    'article_teaser_list' => [
      'variables' => [
        'items' => [],
        'pager' => NULL,
        'term_label' => '',
      ],
    ],
  ];
}

/**
 * Implements hook_page_attachments_alter().
 *
 * Ensures Bootstrap 5 CSS/JS are loaded on the teaser route.
 */
function article_teaser_page_attachments_alter(array &$attachments, RouteMatchInterface $route_match): void {
  if ($route_match->getRouteName() === 'article_teaser.list') {
    $attachments['#attached']['library'][] = 'article_teaser/bootstrap5';
  }
}
```

