## `src/Controller/ArticleTeaserController.php`

```php
<?php

declare(strict_types=1);

namespace Drupal\article_teaser\Controller;

use Drupal\Core\Controller\ControllerBase;
use Drupal\Core\Entity\EntityTypeManagerInterface;
use Drupal\Core\Entity\Query\QueryExceptionInterface;
use Drupal\Core\Pager\PagerManagerInterface;
use Drupal\Core\Render\RendererInterface;
use Drupal\Core\StringTranslation\StringTranslationTrait;
use Symfony\Component\DependencyInjection\ContainerInterface;
use Symfony\Component\HttpFoundation\Request;

/**
 * Controller that renders a paginated teaser list of "foobar"-tagged articles.
 */
final class ArticleTeaserController extends ControllerBase {

  use StringTranslationTrait;

  /**
   * The entity type manager service.
   *
   * @var \Drupal\Core\Entity\EntityTypeManagerInterface
   */
  protected EntityTypeManagerInterface $entityTypeManager;

  /**
   * The pager manager service.
   *
   * @var \Drupal\Core\Pager\PagerManagerInterface
   */
  protected PagerManagerInterface $pagerManager;

  /**
   * The renderer service.
   *
   * @var \Drupal\Core\Render\RendererInterface
   */
  protected RendererInterface $renderer;

  /**
   * Constructs the controller.
   *
   * @param \Drupal\Core\Entity\EntityTypeManagerInterface $entity_type_manager
   *   The entity type manager.
   * @param \Drupal\Core\Pager\PagerManagerInterface $pager_manager
   *   The pager manager.
   * @param \Drupal\Core\Render\RendererInterface $renderer
   *   The renderer.
   */
  public function __construct(
    EntityTypeManagerInterface $entity_type_manager,
    PagerManagerInterface $pager_manager,
    RendererInterface $renderer
  ) {
    $this->entityTypeManager = $entity_type_manager;
    $this->pagerManager = $pager_manager;
    $this->renderer = $renderer;
  }

  /**
   * {@inheritdoc}
   */
  public static function create(ContainerInterface $container): static {
    return new static(
      $container->get('entity_type.manager'),
      $container->get('pager.manager'),
      $container->get('renderer')
    );
  }

  /**
   * Builds and returns the render array for the article teaser list.
   *
   * @param \Symfony\Component\HttpFoundation\Request $request
   *   The current request.
   *
   * @return \Drupal\Core\Render\BubbleableMetadata|array
   *   A render array or a response.
   */
  public function listArticles(Request $request): array {
    // --- 1. Resolve the term ID for "foobar" (cached via entity query). ----
    $term_id = $this->resolveTermId('foobar');

    if ($term_id === NULL) {
      return [
        '#type' => 'markup',
        '#markup' => $this->t('No taxonomy term matching "foobar" was found.'),
      ];
    }

    // --- 2. Build the entity query. ---------------------------------------
    $pager_id = 0;
    $pager_size = 12; // Items per page.

    $this->pagerManager->createPager($pager_size, $pager_id);
    $pager = $this->pagerManager->getPager($pager_id);
    $start = $pager->getCurrentPage($pager_id) * $pager_size;

    $query = $this->entityTypeManager->getStorage('node')->getQuery()
      ->accessCheck(TRUE)
      ->condition('type', 'article')
      ->condition('status', 1)
      ->condition('field_tags:target_id', $term_id)
      ->sort('created', 'DESC')
      ->sort('nid', 'DESC')
      ->range($start, $pager_size);

    try {
      $nids = $query->execute();
    }
    catch (QueryExceptionInterface $e) {
      $this->messenger()->addWarning($this->t('An error occurred while querying articles.'));
      return ['#type' => 'markup', '#markup' => ''];
    }

    // --- 3. Load nodes (only the fields we need via view mode). -----------
    $nodes = $this->entityTypeManager->getStorage('node')->loadMultiple($nids);

    $items = [];
    foreach ($nodes as $nid => $node) {
      $items[] = [
        'title' => $node->getTitle(),
        'url' => $node->toUrl()->toString(),
        'summary' => $node->hasField('field_summary')
          ? strip_tags((string) $node->get('field_summary')->value)
          : $node->hasField('body')
            ? mb_substr(strip_tags((string) $node->get('body')->value), 0, 160) . '…'
            : '',
        'image' => $node->hasField('field_image') && $node->get('field_image')->entity !== NULL
          ? $node->get('field_image')->entity->toUrl('thumbnail')->toString()
          : NULL,
        'date' => \Drupal::service('date.formatter')->format(
          $node->getCreatedTime(),
          'medium',
          NULL,
          TRUE
        ),
        'tags' => $this->extractTagNames($node),
      ];
    }

    // --- 4. Build the render array. ---------------------------------------
    return [
      '#theme' => 'article_teaser_list',
      '#items' => $items,
      '#pager' => [
        '#type' => 'pager',
        '#pager_id' => $pager_id,
        '#quantity' => 5,
      ],
      '#term_label' => 'foobar',
      '#attached' => [
        'library' => ['article_teaser/bootstrap5'],
      ],
    ];
  }

  /**
   * Resolves a taxonomy term ID by name within the "tags" vocabulary.
   *
   * @param string $name
   *   The term name to look up.
   *
   * @return int|null
   *   The term ID, or NULL if not found.
   */
  protected function resolveTermId(string $name): ?int {
    $term_ids = $this->entityTypeManager->getStorage('taxonomy_term')->getQuery()
      ->accessCheck(TRUE)
      ->condition('vid', 'tags')
      ->condition('name', $name)
      ->sort('tid', 'ASC')
      ->range(0, 1)
      ->execute();

    return !empty($term_ids) ? (int) reset($term_ids) : NULL;
  }

  /**
   * Extracts taxonomy term names from a node's field_tags.
   *
   * @param \Drupal\node\NodeInterface $node
   *   The node entity.
   *
   * @return string[]
   *   An array of term name strings.
   */
  protected function extractTagNames(\Drupal\node\NodeInterface $node): array {
    $names = [];
    if ($node->hasField('field_tags')) {
      foreach ($node->get('field_tags') as $item) {
        $term = $item->entity;
        if ($term instanceof \Drupal\taxonomy\TermInterface) {
          $names[] = $term->getName();
        }
      }
    }
    return $names;
  }

}
