```typescript
import type { APIRequestContext } from "@playwright/test";

/**
 * Dependency Inversion: concrete API classes depend on this abstraction,
 * not on the raw APIRequestContext. Swapping the transport (e.g. to a
 * mock) requires no changes to callers.
 */
export abstract class BaseAPI {
  constructor(protected readonly request: APIRequestContext) {}

  protected async post<TResponse>(
    path: string,
    payload: unknown,
  ): Promise<TResponse> {
    const res = await this.request.post(path, {
      data: payload,
      headers: { "Content-Type": "application/json" },
    });
    return res.json() as Promise<TResponse>;
  }

  protected async get<TResponse>(path: string): Promise<TResponse> {
    const res = await this.request.get(path);
    return res.json() as Promise<TResponse>;
  }

  protected async put<TResponse>(
    path: string,
    payload: unknown,
  ): Promise<TResponse> {
    const res = await this.request.put(path, { data: payload });
    return res.json() as Promise<TResponse>;
  }

  protected async delete(path: string): Promise<void> {
    await this.request.delete(path);
  }
}
```

