import type {
  CreateUserPayload,
  PermissionPayload,
  UserRole,
} from "../types/user.types";

/**
 * Builder Pattern: assembles complex, multi-step payloads step-by-step.
 * Open/Closed: new user variants are added by extending the builder,
 * not by mutating existing test code.
 */
export class UserBuilder {
  private name: string;
  private email: string;
  private role: UserRole;
  private permissions: string[];

  constructor() {
    this.name = "";
    this.email = "";
    this.role = "VIEWER";
    this.permissions = [];
  }

  withName(name: string): this {
    this.name = name;
    return this;
  }

  withEmail(email: string): this {
    this.email = email;
    return this;
  }

  withRole(role: UserRole): this {
    this.role = role;
    return this;
  }

  withPermissions(permissions: string[]): this {
    this.permissions = permissions;
    return this;
  }

  buildCreatePayload(): CreateUserPayload {
    return {
      name: this.name,
      email: this.email,
      role: this.role,
    };
  }

  buildPermissionPayload(userId: string): PermissionPayload {
    return {
      id: userId,
      permissions: this.permissions,
    };
  }
}
