```typescript
import type { APIRequestContext } from "@playwright/test";
import { UserAPI } from "../api/UserAPI";
import { PermissionAPI } from "../api/PermissionAPI";
import { UserBuilder } from "../builders/UserBuilder";
import type {
  CreatedUserResponse,
  PermissionUpdateResponse,
  UserCredentials,
  UserRole,
} from "../types/user.types";

/**
 * Factory Method + Chain of Responsibility:
 * encapsulates the *entire* multi-step user-provisioning flow
 * (create → attach permissions → extract credentials) behind a single
 * intent-revealing method.
 *
 * Liskov: any subclass (e.g. SSOUserFactory) can override
 * `provision` and remain substitutable.
 */
export class UserFactory {
  private readonly userAPI: UserAPI;
  private readonly permissionAPI: PermissionAPI;

  constructor(request: APIRequestContext) {
    this.userAPI = new UserAPI(request);
    this.permissionAPI = new PermissionAPI(request);
  }

  /**
   * Full provisioning: create user → update permissions → return credentials.
   */
  async provisionAdmin(
    name: string,
    email: string,
    permissions: string[],
  ): Promise<{ user: CreatedUserResponse; credentials: UserCredentials }> {
    return this.provision(name, email, "ADMIN", permissions);
  }

  async provisionEditor(
    name: string,
    email: string,
    permissions: string[],
  ): Promise<{ user: CreatedUserResponse; credentials: UserCredentials }> {
    return this.provision(name, email, "EDITOR", permissions);
  }

  // ── core chain ──────────────────────────────────────────────
  private async provision(
    name: string,
    email: string,
    role: UserRole,
    permissions: string[],
  ): Promise<{ user: CreatedUserResponse; credentials: UserCredentials }> {
    const builder = new UserBuilder()
      .withName(name)
      .withEmail(email)
      .withRole(role)
      .withPermissions(permissions);

    // Step 1 – create
    const user = await this.userAPI.create(builder.buildCreatePayload());

    // Step 2 – attach permissions (ID from step 1 flows here)
    const permRes = await this.permissionAPI.update(
      builder.buildPermissionPayload(user.id),
    );

    // Step 3 – extract credentials
    const credentials: UserCredentials = {
      username: permRes.username,
      password: permRes.password,
    };

    return { user, credentials };
  }

  // ── teardown helper ─────────────────────────────────────────
  async teardown(userId: string): Promise<void> {
    await this.permissionAPI.revoke(userId);
    await this.userAPI.delete(userId);
  }
}
```

