## 5. Full Arduino Sketch

```cpp
/*
 * ============================================================
 *  MODEL RAILROAD HOUSE LIGHTING AUTOMATION
 *  Arduino Nano + DS3231 RTC + 0.96" SSD1306 OLED
 *  Time ratio: 6:1 (configurable)
 *  Night compression: toggleable (7h night → 1h)
 * ============================================================
 */

#include <Wire.h>
#include <Adafruit_SSD1306.h>
#include <Adafruit_RTClib.h>

// ─── CONFIGURATION ───────────────────────────────────────────
#define TIME_RATIO        6       // 1 real sec = 6 model sec
#define NIGHT_START_HR    23      // Night begins (model hour)
#define NIGHT_END_HR      6       // Night ends (model hour)
#define NIGHT_COMPRESSED  1       // Compressed night duration (hours)
#define NIGHT_FULL        7       // Full night duration (hours)

// ─── PIN DEFINITIONS ─────────────────────────────────────────
#define PIN_LIVING_LIGHT  2
#define PIN_BEDROOM_LIGHT 3
#define PIN_KITCHEN_LIGHT 4
#define PIN_LIVING_TV     5   // PWM
#define PIN_BEDROOM_TV    6   // PWM
#define PIN_BUTTON        7

// ─── OBJECTS ─────────────────────────────────────────────────
Adafruit_SSD1306 display(128, 64, &Wire, -1);
Adafruit_RTC rtc(&Wire);

// ─── STATE VARIABLES ─────────────────────────────────────────
unsigned long modelMs = 0;          // accumulated model milliseconds
unsigned long lastRealMs = 0;
bool nightCompressed = false;       // toggled by button
unsigned long lastTVFlicker = 0;
unsigned long lastDisplayUpdate = 0;
unsigned long lastButtonCheck = 0;
bool lastButtonState = HIGH;
unsigned long channelChangeTimer = 0;
bool channelChanging = false;

// TV flicker state
int livingTVLevel = 200;
int bedroomTVLevel = 200;
bool livingTVOn = false;
bool bedroomTVOn = false;

// ─── DAILY SCHEDULE (model hours, minutes) ──────────────────
// Event struct
struct Event {
  int hour;
  int minute;
  const char* name;
  bool livingLight;
  bool bedroomLight;
  bool kitchenLight;
  bool livingTV;
  bool bedroomTV;
};

// One full 24-hour schedule
Event schedule[] = {
  // hr  min  event name              Liv  Bed  Kit  LivTV  BedTV
  {  0,   0,  "Night – All Dark",     false,false,false,false,false},
  {  6,   0,  "Wake Up",              false,true, false,false,false},
  {  6,  30,  "Morning News (BR)",    false,true, false,false,true },
  {  7,  30,  "News Off, Get Ready",  false,false,false,false,false},
  {  8,   0,  "Breakfast / Kitchen",  false,false,true, false,false},
  {  8,  45,  "Kitchen Off",          false,false,false,false,false},
  { 12,  0,  "Lunch / Kitchen",       false,false,true, false,false},
  { 12,  45, "Kitchen Off",           false,false,false,false,false},
  { 17,   0,  "Evening Lights On",    true, false,false,false,false},
  { 18,   0,  "Dinner / Kitchen",     true, false,true, false,false},
  { 19,   0,  "Living Room TV On",    true, false,false,true, false},
  { 21,   0,  "TV Off, Wind Down",    true, false,false,false,false},
  { 21,  30,  "Bedroom Light On",     false,true, false,false,false},
  { 22,   0,  "Bedtime – TV On",      false,false,false,false,true },
  {  0,   0,  "TV Off – Sleep",       false,false,false,false,false},
};
const int SCHEDULE_LEN = sizeof(schedule) / sizeof(schedule[0]);

// ─── HELPER: Get current model time ──────────────────────────
void getModelTime(int &hr, int &min, int &sec) {
  unsigned long totalSec = modelMs / 1000;
  hr  = (totalSec / 3600) % 24;
  min = (totalSec / 60) % 60;
  sec = totalSec % 60;
}

// ─── HELPER: Check if model time is in night zone ────────────
bool inNightZone(int hr) {
  return (hr >= NIGHT_START_HR || hr < NIGHT_END_HR);
}

// ─── TV FLICKER ──────────────────────────────────────────────
void updateTVFlicker() {
  unsigned long now = millis();
  if (now - lastTVFlicker < 25) return;  // ~40 Hz flicker
  lastTVFlicker = now;

  // Living Room TV
  if (livingTVOn) {
    if (channelChanging) {
      if (now - channelChangeTimer > 150) {
        channelChanging = false;
        livingTVLevel = random(160, 255);
      } else {
        analogWrite(PIN_LIVING_TV, 0);
        return;
      }
    } else {
      // Occasional channel change (~every 45-90 model seconds)
      if (random(1000) < 2) {
        channelChanging = true;
        channelChangeTimer = now;
      }
      // Normal flicker: vary ±30 from base
      livingTVLevel = constrain(random(160, 255), 100, 255);
      analogWrite(PIN_LIVING_TV, livingTVLevel);
    }
  } else {
    analogWrite(PIN_LIVING_TV, 0);
    channelChanging = false;
  }

  // Bedroom TV
  if (bedroomTVOn) {
    if (random(1000) < 2) {
      // brief channel change
      analogWrite(PIN_BEDROOM_TV, 0);
      delay(80);
      bedroomTVLevel = random(140, 240);
    } else {
      bedroomTVLevel = constrain(random(140, 240), 80, 255);
    }
    analogWrite(PIN_BEDROOM_TV, bedroomTVLevel);
  } else {
    analogWrite(PIN_BEDROOM_TV, 0);
  }
}

// ─── APPLY SCHEDULE EVENT ────────────────────────────────────
void applyEvent(const Event &ev) {
  digitalWrite(PIN_LIVING_LIGHT,  ev.livingLight  ? HIGH : LOW);
  digitalWrite(PIN_BEDROOM_LIGHT, ev.bedroomLight ? HIGH : LOW);
  digitalWrite(PIN_KITCHEN_LIGHT, ev.kitchenLight ? HIGH : LOW);
  livingTVOn  = ev.livingTV;
  bedroomTVOn = ev.bedroomTV;
  if (!livingTVOn)  channelChanging = false;
}

// ─── FIND CURRENT EVENT ──────────────────────────────────────
int findCurrentEvent(int hr, int min) {
  int idx = 0;
  for (int i = 0; i < SCHEDULE_LEN; i++) {
    int evMin = schedule[i].hour * 60 + schedule[i].minute;
    int curMin = hr * 60 + min;
    // Handle midnight wrap: schedule[0] is 00:00
    if (i == 0) {
      idx = 0;
      continue;
    }
    if (curMin >= evMin) {
      idx = i;
    }
  }
  return idx;
}

// ─── DISPLAY ─────────────────────────────────────────────────
void updateDisplay(int hr, int min, int sec, const char* eventName, bool nightComp) {
  if (millis() - lastDisplayUpdate < 500) return;  // 2 Hz refresh
  lastDisplayUpdate = millis();

  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);

  // Line 1: Time (large)
  display.setTextSize(2);
  char timeBuf[16];
  snprintf(timeBuf, sizeof(timeBuf), "%02d:%02d:%02d", hr, min, sec);
  display.setCursor(0, 0);
  display.print(timeBuf);

  // Line 2: Event name
  display.setTextSize(1);
  display.setCursor(0, 28);
  display.print(eventName);

  // Line 3: Ratio + Night mode
  display.setCursor(0, 44);
  char info[40];
  if (nightComp)
    snprintf(info, sizeof(info), "Ratio %d:1 | Night: COMP", TIME_RATIO);
  else
    snprintf(info, sizeof(info), "Ratio %d:1 | Night: FULL", TIME_RATIO);
  display.print(info);

  // Line 4: Active lights indicator
  display.setCursor(0, 56);
  char lights[40];
  snprintf(lights, sizeof(lights), "L:%c B:%c K:%c TV:%c/%c",
           ev_living  ? '1' : '0',
           ev_bedroom ? '1' : '0',
           ev_kitchen ? '1' : '0',
           livingTVOn ? '1' : '0',
           bedroomTVOn? '1' : '0');
  display.print(lights);

  display.display();
}

// Temporary storage for display
bool ev_living = false, ev_bedroom = false, ev_kitchen = false;

// ─── BUTTON HANDLING ─────────────────────────────────────────
void checkButton() {
  if (millis() - lastButtonCheck < 50) return;
  lastButtonCheck = millis();

  bool btn = digitalRead(PIN_BUTTON);
  if (btn == LOW && lastButtonState == HIGH) {  // falling edge
    nightCompressed = !nightCompressed;
    Serial.print("Night mode: ");
    Serial.println(nightCompressed ? "COMPRESSED (1h)" : "FULL (7h)");
  }
  lastButtonState = btn;
}

// ─── SETUP ───────────────────────────────────────────────────
void setup() {
  Serial.begin(9600);
  Wire.begin();

  // Pins
  pinMode(PIN_LIVING_LIGHT,  OUTPUT);
  pinMode(PIN_BEDROOM_LIGHT, OUTPUT);
  pinMode(PIN_KITCHEN_LIGHT, OUTPUT);
  pinMode(PIN_LIVING_TV,     OUTPUT);
  pinMode(PIN_BEDROOM_TV,    OUTPUT);
  pinMode(PIN_BUTTON,        INPUT);

  // Start all lights off
  digitalWrite(PIN_LIVING_LIGHT,  LOW);
  digitalWrite(PIN_BEDROOM_LIGHT, LOW);
  digitalWrite(PIN_KITCHEN_LIGHT, LOW);
  analogWrite(PIN_LIVING_TV, 0);
  analogWrite(PIN_BEDROOM_TV, 0);

  // RTC
  if (!rtc.begin()) {
    Serial.println("RTC not found!");
    while (1);
  }
  // Set RTC once (uncomment and edit for your timezone)
  // rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));

  // OLED
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED not found!");
    while (1);
  }
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.print("House Lighting");
  display.setCursor(0, 16);
  display.print("Starting...");
  display.display();
  delay(1500);

  // Seed random
  randomSeed(analogRead(A0));

  Serial.println("=== House Lighting Automation Started ===");
  Serial.print("Time ratio: "); Serial.print(TIME_RATIO); Serial.println(":1");
  Serial.print("Night: "); Serial.println(nightCompressed ? "COMPRESSED" : "FULL");
}

// ─── MAIN LOOP ───────────────────────────────────────────────
void loop() {
  unsigned long nowReal = millis();
  unsigned long realDelta = nowReal - lastRealMs;
  lastRealMs = nowReal;

  // ── Advance model time ──
  int mHr, mMin, mSec;
  getModelTime(mHr, mMin, mSec);

  // Determine speed multiplier for this moment
  float speedMult = 1.0;
  if (nightCompressed && inNightZone(mHr)) {
    // Compress NIGHT_FULL hours into NIGHT_COMPRESSED hours
    speedMult = (float)NIGHT_FULL / (float)NIGHT_COMPRESSED;  // 7x
  }

  modelMs += (unsigned long)(realDelta * TIME_RATIO * speedMult);

  // ── Get updated model time ──
  getModelTime(mHr, mMin, mSec);

  // ── Find and apply current schedule event ──
  int evIdx = findCurrentEvent(mHr, mMin);
  const Event &ev = schedule[evIdx];

  // Only re-apply if event changed (avoid flickering on same event)
  static int lastEvIdx = -1;
  if (evIdx != lastEvIdx) {
    applyEvent(ev);
    ev_living  = ev.livingLight;
    ev_bedroom = ev.bedroomLight;
    ev_kitchen = ev.kitchenLight;
    lastEvIdx  = evIdx;
    Serial.print("Event: ");
    Serial.println(ev.name);
  }

  // ── TV flicker (runs every loop iteration) ──
  updateTVFlicker();

  // ── Button ──
  checkButton();

  // ── Display (throttled to 2 Hz) ──
  updateDisplay(mHr, mMin, mSec, ev.name, nightCompressed);
}
```

---

## 6. Step-by-Step Implementation Guide

### Step 1 – Assemble the Hardware

1. **Breadboard the Nano** in the centre.
2. **Connect the DS3231 RTC**: VCC → 5 V, GND → GND, SDA → A4, SCL → A5.
3. **Connect the 0.96" OLED**: VCC → 5 V, GND → GND, SDA → A4, SCL → A5. (Address is usually **0x3C**; if it doesn't init, try **0x3D** in the `display.begin()` call.)
4. **Wire the five house LEDs**:
   - Each LED anode → 220 Ω resistor → Arduino pin (D2, D3, D4, D5, D6).
   - Each LED cathode → GND.
   - For the two TV LEDs (D5, D6) use a **cool-white or blue-white** LED so the flicker reads as a "screen."
5. **Wire the button**: One leg → D7, other leg → 5 V. Add a 10 kΩ resistor from D7 → GND (pull-down).
6. **Power** the Nano from USB or a 5 V bench supply.

> **Model-scale tip:** Mount the LEDs inside the house walls with a small diffuser (white paper or frosted tape) so they read as room glow at model-railroad viewing distance.

### Step 2 – Install Libraries in Arduino IDE

1. Open **Sketch → Include Library → Manage Libraries**.
2. Search and install:
   - *Adafruit SSD1306*
   - *Adafruit GFX Library*
   - *Adafruit RTClib*
3. Close the library manager.

### Step 3 – Load the Sketch

1. Open the code above in Arduino IDE.
2. **Tools → Board → Arduino Nano**.
3. **Tools → Port** → select your COM/USB port.
4. **Upload**.

### Step 4 – Set the RTC (one-time)

On first power-up the RTC will have a default date. Set it once:

```cpp
// In setup(), uncomment and edit:
rtc.adjust(DateTime(2025, 7, 14, 12, 0, 0));  // Y, M, D, h, m, s
```

After the first correct set, the DS3231's internal crystal keeps time. You can also set it via the **Serial Monitor** by adding a small `if (Serial.available())` block, but the compile-time method is simplest for a permanent install.

### Step 5 – Verify on the OLED

After upload you should see:

```
HH:MM:SS
Event Name
Ratio 6:1 | Night: FULL
L:0 B:0 K:0 TV:0/0
```

The clock advances at **6× real speed**. At 6:00 model time the bedroom light turns on, at 6:30 the bedroom TV starts flickering, etc.

### Step 6 – Test the Night Compression

- **Press the button once** → Serial prints `Night mode: COMPRESSED (1h)`.
- Now when model time hits 23:00, the clock races through 7 hours of night in only 1 hour of model time (≈ 10 real minutes at 6:1).
- **Press again** → back to full 7-hour night.

### Step 7 – Tune the Schedule

Edit the `schedule[]` array to match your household's routine. Each entry is:

```cpp
{ hour, minute, "Name", livingLight, bedroomLight, kitchenLight, livingTV, bedroomTV }
```

Add or remove rows freely. The code always picks the **last event whose time ≤ current model time**, so ordering matters (ascending, with 00:00 first).

### Step 8 – Adjust the Time Ratio

Change the single constant at the top:

```cpp
#define TIME_RATIO  6   // try 4, 8, 12, 24 …
```

- **6:1** → full 24 h day in **4 real hours**
- **12:1** → full day in **2 real hours**
- **24:1** → full day in **1 real hour** (great for a show table)

### Step 9 – Mount in the Model House

1. Solder the Nano + RTC + OLED onto a small **perfboard or PCB** (or use a Nano shield with I²C headers).
2. Mount the board **under the floor** or in a hidden compartment.
3. Run thin wire (30 AWG or 32 AWG) from the board to each LED location inside the rooms.
4. Secure the OLED (or a small mirror / angled acrylic) so the time is visible through a window or on the exterior wall.
5. Power from the layout's 12 V DC bus through a **5 V / 2 A buck converter** (LM2596 or similar) so you don't need a USB cable.

---

## 7. TV Flicker – How It Works

| Parameter | Value | Purpose |
|-----------|-------|---------|
| Flicker interval | 25 ms (40 Hz) | Mimics TV refresh |
| Brightness range | 140 – 255 (PWM) | Subtle luma variation |
| Channel-change probability | 2 / 1000 per tick | ~1 change every 45–90 model-sec |
| Channel-change dark period | 150 ms | "Static / blank" between channels |
| Bedroom TV range | 140 – 240 | Slightly dimmer (bedroom at night) |

The effect is a **soft, random PWM shimmer** that reads as a glowing TV screen at model scale. No RGB needed—single-colour white/blue with varying brightness is convincing at 1:87 or 1:160.

---

## 8. The "Bedtime" Sequence (Bedroom TV 2 h, Lights Off)

In the schedule:

```
22:00  "Bedtime – TV On"    bedroomLight = false, bedroomTV = true
 0:00  "TV Off – Sleep"     bedroomTV = false
```

That's exactly **2 model hours** of TV-on / lights-off. If you want a different duration, change the `0:00` entry to, say, `1:00` for 3 hours.

---

## 9. Night Compression – How It Works

```
Normal (FULL):
  23:00 ─────────── 06:00     7 model hours
  (at 6:1 ratio)  → 70 real minutes

Compressed (COMP):
  23:00 ── 00:00 ──► 06:00    1 model hour of "night"
  (at 6:1 ratio)  → 10 real minutes
```

The code multiplies the model-time advance by `NIGHT_FULL / NIGHT_COMPRESSED = 7×` whenever the model hour is in the night zone **and** the button has toggled compression on. The OLED label changes to `Night: COMP` so you (and spectators) can see the mode.

---

## 10. Optional Enhancements

| Feature | How |
|---------|-----|
| **Sunset colour shift** | Use a **WS2812B** strip instead of plain LEDs; fade warm-white → amber at 17:00–19:00 |
| **Sound** | Add a small piezo buzzer on D8; beep on event change |
| **Wi-Fi / BLE control** | Swap Nano for **Nano 33 BLE** or add a **HC-05** Bluetooth module to toggle night mode from a phone |
| **Multiple houses** | Run 2–3 Nanos on the same I²C bus (assign each a unique I²C address) or use a **PCF8574** I/O expander for more LED channels |
| **Random "accident" lights** | Add a 1-in-500 chance per tick to briefly flash the kitchen light (someone left it on) |
| **Seasonal schedules** | Store two `schedule[]` arrays (summer / winter) and select via a second button press |

---

## 11. Troubleshooting

| Symptom | Fix |
|---------|-----|
| OLED blank | Try address `0x3D` instead of `0x3C`. Check SDA/SCL are swapped. |
| RTC not found | Verify VCC/GND/SDA/SCL. Some modules need a **3.3 V** supply (check datasheet). |
| TV doesn't flicker | Confirm D5/D6 are used (hardware PWM). `analogWrite` on other pins is software PWM and may stutter. |
| Time jumps backwards | RTC battery (CR1220/CR2032) is dead. Replace it. |
| Night compression not working | Check the button is wired with the 10 kΩ pull-down. Read `digitalRead(PIN_BUTTON)` in Serial to confirm it toggles. |
| LEDs too bright for model | Add a **second 220 Ω in series** (total 440 Ω) or use a **1 kΩ** resistor. |

---

## 12. File / Project Structure (for future expansion)

```
HouseLighting/
├── HouseLighting.ino          ← main sketch (above)
├── config.h                   ← TIME_RATIO, pins, schedule (extract later)
├── tvFlicker.h / .cpp         ← TV flicker engine (extract later)
├── schedule.h                 ← Event struct + schedule[] array
└── wiring/
    └── wiring_diagram.pdf     ← Fritzing or KiCad schematic
```

Start with the single `.ino` file above. Once it's working and you want to add features, refactor into the modular layout.

---

Build it, power it up, and within 4 real hours you'll have watched a full model-railroad day of lights, TV flicker, and bedtime routine play out on the 0.96" OLED—compressed to 10 minutes of "night" whenever you press that button. Happy rolling! 🚂💡

