```cpp
// ============================================================================
//  Chart2D.h  –  2-D y = y(x) chart widget for FLTK
//  Single-axis, no mouse-tracking, pure drawing.
// ============================================================================
#ifndef CHART2D_H
#define CHART2D_H

#include <FL/Fl.H>
#include <FL/Fl_Widget.H>
#include <FL/Fl_Color.H>
#include <FL/Fl_Font.H>
#include <FL/Fl_Box.H>

#include <vector>
#include <string>
#include <algorithm>
#include <cmath>
#include <limits>
#include <functional>
#include <sstream>

// ---------------------------------------------------------------------------
//  Fundamental data types
// ---------------------------------------------------------------------------

/// A single (x, y) sample.
struct Point {
    float x;
    float y;

    Point() : x(0.0f), y(0.0f) {}
    Point(float x_, float y_) : x(x_), y(y_) {}

    bool operator==(const Point& o) const {
        return std::abs(x - o.x) < 1e-6f && std::abs(y - o.y) < 1e-6f;
    }
};

/// Chart rendering style.
enum class ChartType {
    LINE,       // connected line segments
    SCATTER,    // individual dots
    STEP,       // staircase
    AREA        // filled area under the curve
};

/// Grid-line configuration.
struct GridSettings {
    bool    visible        = true;
    int     majorStep      = 10;   // major grid interval in *data* units
    int     minorStep      = 2;    // minor grid interval
    Fl_Color majorColor    = FL_GRAY;
    Fl_Color minorColor    = FL_WHITE;
    float   majorLineWidth = 1.0f;
    float   minorLineWidth = 0.5f;
    bool    showMinor      = true;
};

/// One axis (X or Y) configuration.
struct AxisSettings {
    std::string name        = "";   // e.g. "Time [s]", "Amplitude [V]"
    Fl_Color    color       = FL_BLACK;
    float       lineWidth   = 1.5f;
    bool        showTicks   = true;
    int         tickCount   = 8;    // approximate number of tick marks
    float       tickLength  = 5.0f; // px
    int         labelFont   = FL_COURIER;
    int         labelSize   = 12;
    bool        autoScale   = true; // auto-fit data range
    float       rangeMin    = 0.0f; // used when autoScale == false
    float       rangeMax    = 1.0f;
};

/// A single named curve (graph) inside the chart.
class Graph {
public:
    Graph() = default;
    explicit Graph(const std::string& name) : name_(name) {}

    // -- data ---------------------------------------------------------------
    void addPoint(const Point& p)          { points_.push_back(p); }
    void addPoints(const std::vector<Point>& pts) {
        points_.insert(points_.end(), pts.begin(), pts.end());
    }
    void removePoint(size_t idx) {
        if (idx < points_.size()) points_.erase(points_.begin() + idx);
    }
    void removePoint(const Point& p) {
        points_.erase(std::remove(points_.begin(), points_.end(), p),
                      points_.end());
    }
    void clear()                           { points_.clear(); }
    size_t pointCount() const              { return points_.size(); }
    const Point& pointAt(size_t i) const   { return points_.at(i); }
    std::vector<Point>&       points()     { return points_; }
    const std::vector<Point>& points() const { return points_; }

    // -- appearance ---------------------------------------------------------
    const std::string& name() const        { return name_; }
    void setName(const std::string& n)     { name_ = n; }

    Fl_Color color() const                 { return color_; }
    void setColor(Fl_Color c)              { color_ = c; }

    float lineWidth() const                { return lineWidth_; }
    void setLineWidth(float w)             { lineWidth_ = w; }

    bool visible() const                   { return visible_; }
    void setVisible(bool v)                { visible_ = v; }

    ChartType type() const                 { return type_; }
    void setType(ChartType t)              { type_ = t; }

    // -- helpers -------------------------------------------------------------
    void computeRange(float& xMin, float& xMax,
                      float& yMin, float& yMax) const {
        xMin =  std::numeric_limits<float>::max();
        xMax = -std::numeric_limits<float>::max();
        yMin =  std::numeric_limits<float>::max();
        yMax = -std::numeric_limits<float>::max();
        for (const auto& p : points_) {
            xMin = std::min(xMin, p.x);
            xMax = std::max(xMax, p.x);
            yMin = std::min(yMin, p.y);
            yMax = std::max(yMax, p.y);
        }
        if (points_.empty()) { xMin = 0; xMax = 1; yMin = 0; yMax = 1; }
    }

private:
    std::string       name_;
    std::vector<Point> points_;
    Fl_Color          color_       = FL_RED;
    float             lineWidth_   = 2.0f;
    bool              visible_     = true;
    ChartType         type_        = ChartType::LINE;
};

// ---------------------------------------------------------------------------
//  Chart2D  –  the FLTK widget
// ---------------------------------------------------------------------------

class Chart2D : public Fl_Widget {
public:
    // ------------------------------------------------------------------
    //  Construction
    // ------------------------------------------------------------------
    explicit Chart2D(int x = 0, int y = 0,
                     int w = 600, int h = 400,
                     const char* label = "Chart");

    ~Chart2D() override = default;

    // ------------------------------------------------------------------
    //  Graph (curve) management
    // ------------------------------------------------------------------
    /// Add a new graph; returns its 0-based index.
    int addGraph(const std::string& name = "Graph");

    /// Remove graph by index.  Returns true on success.
    bool removeGraph(int idx);

    /// Remove the last graph.
    bool removeLastGraph();

    /// Number of graphs currently in the chart.
    int graphCount() const { return static_cast<int>(graphs_.size()); }

    /// Access a graph by index (throws std::out_of_range).
    Graph&       graphAt(int idx)       { return graphs_.at(idx); }
    const Graph& graphAt(int idx) const { return graphs_.at(idx); }

    /// Convenience: add a single point to graph *idx*.
    bool addPointToGraph(int idx, const Point& p);

    /// Convenience: remove a point from graph *idx*.
    bool removePointFromGraph(int idx, size_t pointIdx);

    /// Remove all graphs.
    void clearGraphs() { graphs_.clear(); redraw(); }

    // ------------------------------------------------------------------
    //  Axis configuration
    // ------------------------------------------------------------------
    AxisSettings&       xAxis()       { return xAxis_; }
    const AxisSettings& xAxis() const { return xAxis_; }

    AxisSettings&       yAxis()       { return yAxis_; }
    const AxisSettings& yAxis() const { return yAxis_; }

    /// Quick setters
    void setXAxisName(const std::string& n) { xAxis_.name = n; redraw(); }
    void setYAxisName(const std::string& n) { yAxis_.name = n; redraw(); }

    /// Resize the data range (disables auto-scale for that axis).
    void setXRange(float lo, float hi) {
        xAxis_.autoScale = false;
        xAxis_.rangeMin  = lo;
        xAxis_.rangeMax  = hi;
        redraw();
    }
    void setYRange(float lo, float hi) {
        yAxis_.autoScale = false;
        yAxis_.rangeMin  = lo;
        yAxis_.rangeMax  = hi;
        redraw();
    }

    // ------------------------------------------------------------------
    //  Grid configuration
    // ------------------------------------------------------------------
    GridSettings&       grid()       { return grid_; }
    const GridSettings& grid() const { return grid_; }

    void setGridVisible(bool v)      { grid_.visible = v; redraw(); }
    void setGridMajorStep(int s)     { grid_.majorStep = s; redraw(); }
    void setGridMinorStep(int s)     { grid_.minorStep = s; redraw(); }
    void setGridColors(Fl_Color major, Fl_Color minor) {
        grid_.majorColor = major;
        grid_.minorColor = minor;
        redraw();
    }

    // ------------------------------------------------------------------
    //  Chart-level appearance
    // ------------------------------------------------------------------
    void setBackground(Fl_Color c) { bg_ = c; redraw(); }
    void setChartType(ChartType t) { defaultType_ = t; redraw(); }

    /// Margin (in pixels) reserved for axis labels / titles.
    void setMargins(float left, float right, float top, float bottom) {
        mL_ = left; mR_ = right; mT_ = top; mB_ = bottom;
        redraw();
    }

    // ------------------------------------------------------------------
    //  Info / introspection
    // ------------------------------------------------------------------
    /// Returns a human-readable summary of the chart state.
    std::string info() const;

    /// Returns the current data bounding box across all graphs.
    void dataBounds(float& xMin, float& xMax,
                    float& yMin, float& yMax) const;

    // ------------------------------------------------------------------
    //  FL_Widget override – the actual drawing
    // ------------------------------------------------------------------
    int draw() override;

private:
    // -- drawing helpers ----------------------------------------------------
    void drawGrid(float px0, float py0, float pw, float ph,
                  float xMin, float xMax, float yMin, float yMax) const;

    void drawAxes(float px0, float py0, float pw, float ph,
                  float xMin, float xMax, float yMin, float yMax) const;

    void drawGraph(const Graph& g,
                   float px0, float py0, float pw, float ph,
                   float xMin, float xMax, float yMin, float yMax) const;

    void drawLegend(float px0, float py0, float pw, float ph) const;

    // -- coordinate conversion ----------------------------------------------
    float dataToPixX(float dataX, float px0, float pw,
                     float xMin, float xMax) const;
    float dataToPixY(float dataY, float py0, float ph,
                     float yMin, float yMax) const;

    // -- members -------------------------------------------------------------
    std::vector<Graph>  graphs_;

    AxisSettings        xAxis_;
    AxisSettings        yAxis_;
    GridSettings        grid_;

    Fl_Color            bg_            = FL_WHITE;
    ChartType           defaultType_   = ChartType::LINE;

    // plot-area margins (px)
    float mL_ = 60.0f;   // left   (Y-axis label + ticks)
    float mR_ = 20.0f;   // right
    float mT_ = 30.0f;   // top    (title / legend)
    float mB_ = 50.0f;   // bottom (X-axis label + ticks)
};

#endif // CHART2D_H
```

And here is the matching **implementation file** so you can see the drawing logic:

```cpp
// ============================================================================
//  Chart2D.cpp
// ============================================================================
#include "Chart2D.h"

#include <FL/Fl.H>
#include <FL/Fl_Color.H>
#include <FL/Fl_Font.H>
#include <FL/Fl_Box.H>

#include <sstream>
#include <iomanip>
#include <cmath>

// ---------------------------------------------------------------------------
//  Construction
// ---------------------------------------------------------------------------
Chart2D::Chart2D(int x, int y, int w, int h, const char* label)
    : Fl_Widget(x, y, w, h, label)
{
    box(FL_NO_BOX);          // we draw our own background
    color(FL_WHITE);
}

// ---------------------------------------------------------------------------
//  Graph management
// ---------------------------------------------------------------------------
int Chart2D::addGraph(const std::string& name) {
    Graph g(name);
    // cycle through a small palette
    static const Fl_Color palette[] = {
        FL_RED, FL_BLUE, FL_GREEN, FL_DARK3, FL_DARK4,
        FL_DARK5, FL_DARK6, FL_DARK7, FL_DARK8, FL_DARK9
    };
    g.color(palette[graphs_.size() % 10]);
    g.type(defaultType_);
    graphs_.push_back(std::move(g));
    redraw();
    return static_cast<int>(graphs_.size()) - 1;
}

bool Chart2D::removeGraph(int idx) {
    if (idx < 0 || idx >= static_cast<int>(graphs_.size())) return false;
    graphs_.erase(graphs_.begin() + idx);
    redraw();
    return true;
}

bool Chart2D::removeLastGraph() {
    if (graphs_.empty()) return false;
    graphs_.pop_back();
    redraw();
    return true;
}

bool Chart2D::addPointToGraph(int idx, const Point& p) {
    if (idx < 0 || idx >= static_cast<int>(graphs_.size())) return false;
    graphs_[idx].addPoint(p);
    redraw();
    return true;
}

bool Chart2D::removePointFromGraph(int idx, size_t pointIdx) {
    if (idx < 0 || idx >= static_cast<int>(graphs_.size())) return false;
    graphs_[idx].removePoint(pointIdx);
    redraw();
    return true;
}

// ---------------------------------------------------------------------------
//  Info / bounds
// ---------------------------------------------------------------------------
std::string Chart2D::info() const {
    std::ostringstream os;
    os << "=== Chart2D info ===\n";
    os << "  Size        : " << w() << " x " << h() << "\n";
    os << "  Background  : " << fl_color_index(bg_) << "\n";
    os << "  X-axis      : \"" << xAxis_.name << "\"  ["
       << xAxis_.rangeMin << " .. " << xAxis_.rangeMax << "]\n";
    os << "  Y-axis      : \"" << yAxis_.name << "\"  ["
       << yAxis_.rangeMin << " .. " << yAxis_.rangeMax << "]\n";
    os << "  Grid        : visible=" << (grid_.visible ? "yes" : "no")
       << "  major=" << grid_.majorStep
       << "  minor=" << grid_.minorStep << "\n";
    os << "  Graphs (" << graphs_.size() << "):\n";
    for (size_t i = 0; i < graphs_.size(); ++i) {
        const auto& g = graphs_[i];
        float x0,x1,y0,y1;
        g.computeRange(x0,x1,y0,y1);
        os << "    [" << i << "] \"" << g.name()
           << "\"  pts=" << g.pointCount()
           << "  color=" << fl_color_index(g.color())
           << "  type=" << static_cast<int>(g.type())
           << "  range=(" << x0 << "," << y0 << ")-("
           << x1 << "," << y1 << ")\n";
    }
    return os.str();
}

void Chart2D::dataBounds(float& xMin, float& xMax,
                         float& yMin, float& yMax) const {
    xMin =  std::numeric_limits<float>::max();
    xMax = -std::numeric_limits<float>::max();
    yMin =  std::numeric_limits<float>::max();
    yMax = -std::numeric_limits<float>::max();
    for (const auto& g : graphs_) {
        float gx0,gx1,gy0,gy1;
        g.computeRange(gx0,gx1,gy0,gy1);
        xMin = std::min(xMin, gx0);
        xMax = std::max(xMax, gx1);
        yMin = std::min(yMin, gy0);
        yMax = std::max(yMax, gy1);
    }
    if (xMin > xMax) { xMin = 0; xMax = 1; }
    if (yMin > yMax) { yMin = 0; yMax = 1; }
}

// ---------------------------------------------------------------------------
//  Coordinate helpers
// ---------------------------------------------------------------------------
float Chart2D::dataToPixX(float dataX, float px0, float pw,
                          float xMin, float xMax) const {
    if (xMax == xMin) return px0 + pw * 0.5f;
    return px0 + (dataX - xMin) / (xMax - xMin) * pw;
}

float Chart2D::dataToPixY(float dataY, float py0, float ph,
                          float yMin, float yMax) const {
    if (yMax == yMin) return py0 + ph * 0.5f;
    return py0 + ph - (dataY - yMin) / (yMax - yMin) * ph;  // flip Y
}

// ---------------------------------------------------------------------------
//  Drawing
// ---------------------------------------------------------------------------
int Chart2D::draw() {
    // background
    fl_color(bg_);
    fl_rect(0, 0, w(), h());

    // plot area
    float px0 = mL_;
    float py0 = mT_;
    float pw  = w() - mL_ - mR_;
    float ph  = h() - mT_ - mB_;
    if (pw < 10 || ph < 10) return 1;   // too small

    // resolve data range
    float xMin, xMax, yMin, yMax;
    if (xAxis_.autoScale) { dataBounds(xMin, xMax, yMin, yMax); }
    else                  { xMin = xAxis_.rangeMin; xMax = xAxis_.rangeMax; }

    if (yAxis_.autoScale) {
        float tx0,tx1,ty0,ty1;
        dataBounds(tx0, tx1, ty0, ty1);
        yMin = ty0; yMax = ty1;
    } else {
        yMin = yAxis_.rangeMin; yMax = yAxis_.rangeMax;
    }

    // add a small padding (5 %)
    float padX = (xMax - xMin) * 0.05f;
    float padY = (yMax - yMin) * 0.05f;
    xMin -= padX; xMax += padX;
    yMin -= padY; yMax += padY;

    // draw order: grid → axes → graphs → legend
    drawGrid  (px0, py0, pw, ph, xMin, xMax, yMin, yMax);
    drawAxes  (px0, py0, pw, ph, xMin, xMax, yMin, yMax);
    for (const auto& g : graphs_) {
        if (g.visible())
            drawGraph(g, px0, py0, pw, ph, xMin, xMax, yMin, yMax);
    }
    drawLegend(px0, py0, pw, ph);

    return 1;
}

// ---------------------------------------------------------------------------
void Chart2D::drawGrid(float px0, float py0, float pw, float ph,
                       float xMin, float xMax, float yMin, float yMax) const {
    if (!grid_.visible) return;

    // minor grid
    if (grid_.showMinor && grid_.minorStep > 0) {
        fl_color(grid_.minorColor);
        fl_line(grid_.minorLineWidth);
        // vertical minor
        for (float v = std::ceil(xMin / grid_.minorStep) * grid_.minorStep;
             v <= xMax; v += grid_.minorStep) {
            float px = dataToPixX(v, px0, pw, xMin, xMax);
            fl_line(px, py0, px, py0 + ph);
        }
        // horizontal minor
        for (float v = std::ceil(yMin / grid_.minorStep) * grid_.minorStep;
             v <= yMax; v += grid_.minorStep) {
            float py = dataToPixY(v, py0, ph, yMin, yMax);
            fl_line(px0, py, px0 + pw, py);
        }
    }

    // major grid
    if (grid_.majorStep > 0) {
        fl_color(grid_.majorColor);
        fl_line(grid_.majorLineWidth);
        for (float v = std::ceil(xMin / grid_.majorStep) * grid_.majorStep;
             v <= xMax; v += grid_.majorStep) {
            float px = dataToPixX(v, px0, pw, xMin, xMax);
            fl_line(px, py0, px, py0 + ph);
        }
        for (float v = std::ceil(yMin / grid_.majorStep) * grid_.majorStep;
             v <= yMax; v += grid_.majorStep) {
            float py = dataToPixY(v, py0, ph, yMin, yMax);
            fl_line(px0, py, px0 + pw, py);
        }
    }
}

// ---------------------------------------------------------------------------
void Chart2D::drawAxes(float px0, float py0, float pw, float ph,
                       float xMin, float xMax, float yMin, float yMax) const {
    // -- X axis (bottom) ----------------------------------------------------
