// ---------------------------------------------------------------------------
void Chart2D::drawGraph(const Graph& g,
                        float px0, float py0, float pw, float ph,
                        float xMin, float xMax, float yMin, float yMax) const {
    const auto& pts = g.points();
    if (pts.size() < 2) {
        // draw a single dot if only one point
        if (pts.size() == 1) {
            fl_color(g.color());
            float px = dataToPixX(pts[0].x, px0, pw, xMin, xMax);
            float py = dataToPixY(pts[0].y, py0, ph, yMin, yMax);
            fl_circle(px, py, g.lineWidth() * 1.5f);
        }
        return;
    }

    // clip to plot area
    fl_push_clip(px0, py0, pw, ph);
    fl_color(g.color());
    fl_line(g.lineWidth());

    switch (g.type()) {
    case ChartType::LINE:
    case ChartType::STEP: {
        for (size_t i = 1; i < pts.size(); ++i) {
            float x0 = dataToPixX(pts[i-1].x, px0, pw, xMin, xMax);
            float y0 = dataToPixY(pts[i-1].y, py0, ph, yMin, yMax);
            float x1 = dataToPixX(pts[i].x,   px0, pw, xMin, xMax);
            float y1 = dataToPixY(pts[i].y,   py0, ph, yMin, yMax);
            if (g.type() == ChartType::STEP) {
                fl_line(x0, y0, x1, y0);   // horizontal
                fl_line(x1, y0, x1, y1);   // vertical
            } else {
                fl_line(x0, y0, x1, y1);
            }
        }
        break;
    }
    case ChartType::SCATTER: {
        float r = g.lineWidth() * 1.2f;
        for (const auto& p : pts) {
            float px = dataToPixX(p.x, px0, pw, xMin, xMax);
            float py = dataToPixY(p.y, py0, ph, yMin, yMax);
            fl_circle(px, py, r);
        }
        break;
    }
    case ChartType::AREA: {
        // fill under curve
        float baseY = py0 + ph;
        fl_begin_poly();
        fl_vertex(dataToPixX(pts.front().x, px0, pw, xMin, xMax), baseY);
        for (const auto& p : pts)
            fl_vertex(dataToPixX(p.x, px0, pw, xMin, xMax),
                      dataToPixY(p.y, py0, ph, yMin, yMax));
        fl_vertex(dataToPixX(pts.back().x, px0, pw, xMin, xMax), baseY);
        fl_end_poly();
        fl_poly_fill(g.color());
        // outline
        for (size_t i = 1; i < pts.size(); ++i) {
            fl_line(dataToPixX(pts[i-1].x, px0, pw, xMin, xMax),
                    dataToPixY(pts[i-1].y, py0, ph, yMin, yMax),
                    dataToPixX(pts[i].x,   px0, pw, xMin, xMax),
                    dataToPixY(pts[i].y,   py0, ph, yMin, yMax));
        }
        break;
    }
    }
    fl_pop_clip();
}

// ---------------------------------------------------------------------------
void Chart2D::drawLegend(float px0, float py0, float pw, float ph) const {
    if (graphs_.empty()) return;

    fl_font(FL_COURIER, 11);
    float lx = px0 + 10;
    float ly = py0 + 14;
    for (const auto& g : graphs_) {
        if (!g.visible()) continue;
        // colour swatch
        fl_color(g.color());
        fl_rectf(lx, ly - 6, 18, 3);
        // label
        fl_color(FL_BLACK);
        fl_draw(g.name().c_str(), lx + 22, ly);
        ly += 16;
    }
}
