# 矩形面积 II - 扫描线 + 线段树

## 思路

使用**扫描线算法**：沿 x 轴方向扫描，维护当前 x 位置处 y 轴上被覆盖的总长度。

1. 将每个矩形的左边界作为"开始事件"，右边界作为"结束事件"
2. 对 y 坐标进行离散化
3. 用线段树维护 y 轴上被覆盖的总长度（记录覆盖次数）
4. 相邻两个 x 坐标之间，面积贡献 = Δx × 当前 y 轴覆盖长度

## C++ 代码

```cpp
#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1e9 + 7;

struct Event {
    long long x;
    int y1, y2;
    int type; // +1 开始, -1 结束
};

struct SegTree {
    vector<long long> cover;
    vector<int> cnt;
    vector<long long> ys;
    int n;

    SegTree(vector<long long>& y) : ys(y) {
        n = (int)ys.size() - 1;
        cover.assign(4 * n + 4, 0);
        cnt.assign(4 * n + 4, 0);
    }

    void update(int node, int l, int r, int ql, int qr, int val) {
        if (qr <= l || r <= ql) return;
        if (ql <= l && r <= qr) {
            cnt[node] += val;
        } else {
            int mid = (l + r) >> 1;
            update(node << 1, l, mid, ql, qr, val);
            update(node << 1 | 1, mid, r, ql, qr, val);
        }
        if (cnt[node] > 0) {
            cover[node] = ys[r] - ys[l];
        } else if (r - l == 1) {
            cover[node] = 0;
        } else {
            cover[node] = cover[node << 1] + cover[node << 1 | 1];
        }
    }
};

int main() {
    int n;
    scanf("%d", &n);

    vector<long long> xs, ys;
    vector<Event> events;

    for (int i = 0; i < n; i++) {
        long long x1, y1, x2, y2;
        scanf("%lld %lld %lld %lld", &x1, &y1, &x2, &y2);
        xs.push_back(x1);
        xs.push_back(x2);
        ys.push_back(y1);
        ys.push_back(y2);
    }

    // y 坐标离散化
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    int m = (int)ys.size();

    // 生成事件
    for (int i = 0; i < n; i++) {
        long long x1, y1, x2, y2;
        scanf("%lld %lld %lld %lld", &x1, &y1, &x2, &y2);
        int yi1 = lower_bound(ys.begin(), ys.end(), y1) - ys.begin();
        int yi2 = lower_bound(ys.begin(), ys.end(), y2) - ys.begin();
        events.push_back({x1, yi1, yi2, 1});
        events.push_back({x2, yi1, yi2, -1});
    }

    sort(events.begin(), events.end(), [](const Event& a, const Event& b) {
        return a.x < b.x;
    });

    SegTree st(ys);

    long long totalArea = 0;
    long long prevX = events[0].x;

    for (int i = 0; i < (int)events.size(); ) {
        long long curX = events[i].x;
        // 累加 [prevX, curX) 之间的面积
        totalArea += (curX - prevX) * st.cover[1];

        // 处理 curX 处所有事件
        while (i < (int)events.size() && events[i].x == curX) {
            st.update(1, 0, m - 1, events[i].y1, events[i].y2, events[i].type);
            i++;
        }
        prevX = curX;
    }

    printf("%lld\n", totalArea % MOD);
    return 0;
}
```

## 关键点说明

| 要点 | 说明 |
|------|------|
| **扫描线方向** | 沿 x 轴从左到右扫描 |
| **线段树维护** | 每个节点记录 `cnt`（被几个矩形覆盖）和 `cover`（该段 y 轴上被覆盖的总长度） |
| **覆盖判断** | `cnt > 0` 时整段被覆盖，`cover = ys[r] - ys[l]`；否则合并子节点 |
| **面积累加** | 相邻两个 x 坐标之间：`Δx × 当前 y 轴覆盖总长度` |
| **取模** | 题目保证总面积 ≤ 2⁶³−1，用 `long long` 累加，最后对 10⁹+7 取模 |

## 复杂度

- 时间：O(n log n)，n 为矩形数量（≤ 50），排序 + 线段树操作
- 空间：O(n)，离散化后的 y 坐标和线段树

