    vector<long long> cover; // total covered length in this segment
    vector<int> cnt; // number of rectangles covering this segment
    int n; // number of y-segments (n-1 segments from n points)

    SegmentTree(int n) : n(n), cover(4 * n, 0), cnt(4 * n, 0) {}

    void update(int node, int l, int r, int ql, int qr, int val) {
