import java.util.ArrayList;
import java.util.List;

public class ClimbStairs {

    static List<List<Integer>> allWays = new ArrayList<>();

    public static void main(String[] args) {
        int n = 5; // 修改这里改变台阶数

        System.out.println("========== n = " + n + " 级台阶 ==========");
        System.out.println("规则：每次可以走 1 步或 2 步\n");

        // 回溯枚举所有走法
        List<Integer> currentPath = new ArrayList<>();
        generateWays(n, 0, currentPath);

        // 输出所有方法
        System.out.println("总共有 " + allWays.size() + " 种方法：\n");
        System.out.printf("%-8s %-20s %s%n", "编号", "走法", "累计台阶");
        System.out.println("-".repeat(50));

        for (int i = 0; i < allWays.size(); i++) {
            List<Integer> path = allWays.get(i);

            // 构建走法字符串，如 "1 + 2 + 2"
            StringBuilder steps = new StringBuilder();
            StringBuilder cumulative = new StringBuilder();
            int pos = 0;
            for (int j = 0; j < path.size(); j++) {
                pos += path.get(j);
                steps.append(path.get(j));
                cumulative.append(pos);
                if (j < path.size() - 1) {
                    steps.append(" + ");
                    cumulative.append(" -> ");
                }
            }

            System.out.printf("%-8s %-20s %s%n",
                    (i + 1) + ":", steps.toString(), cumulative.toString());
        }

        // 验证：用动态规划计算总数
        System.out.println("\n[验证] 动态规划计算结果: " + countByDP(n));
    }

    /**
     * 回溯法：枚举所有走法
     */
    static void generateWays(int n, int current, List<Integer> path) {
        if (current > n) return;
        if (current == n) {
            allWays.add(new ArrayList<>(path));
            return;
        }

        // 选择走 1 步
        path.add(1);
        generateWays(n, current + 1, path);
        path.remove(path.size() - 1);

        // 选择走 2 步
        path.add(2);
        generateWays(n, current + 2, path);
        path.remove(path.size() - 1);
    }

    /**
     * 动态规划：计算总方法数（斐波那契）
     */
    static int countByDP(int n) {
        if (n <= 1) return 1;
        int[] dp = new int[n + 1];
        dp[0] = 1;
        dp[1] = 1;
        for (int i = 2; i <= n; i++) {
            dp[i] = dp[i - 1] + dp[i - 2];
        }
        return dp[n];
    }
}
