        T = T * dh_matrix(DH_params(i,:), theta(i));
    end
    end_pos = T(1:3, 4);
end

function T = dh_matrix(params, theta)
    a     = params(1);
    alpha = deg2rad(params(2));
    d     = params(3);
    T = [
        cos(theta), -sin(theta)*cos(alpha),  sin(theta)*sin(alpha), a*cos(theta);
        sin(theta),  cos(theta)*cos(alpha), -cos(theta)*sin(alpha), a*sin(theta);
        0,           sin(alpha),             cos(alpha),            d;
        0,           0,                      0,                     1
    ];
end

function visualize_results(fval, fig, start)
    % 【Bug 5 修复】复用传入的 figure，用 subplot 区分每次启动
    subplot(2, 3, start);
    scatter(fval(:,1), fval(:,2), 20, 'filled');
    xlabel('End Effector Error (mm)');
    ylabel('Energy Consumption (J)');
    title(sprintf('Start #%d', start));
    grid on;
end

function disp_results(x, fval)
    [minError,    minErrorIdx]    = min(fval(:,1));
    [maxEnergy,   maxEnergyIdx]   = max(fval(:,2));

    % --- 最低误差点 ---
    disp('--- 最低误差点 ---');
    disp(array2table(rad2deg(x(minErrorIdx,:)), ...
        'VariableNames', {'Joint1','Joint2','Joint3','Joint4','Joint5','Joint6'}));
    disp(array2table([minError, fval(minErrorIdx,2)], ...   % 【Bug 3 修复】
        'VariableNames', {'EndEffectorError_mm','EnergyConsumption_J'}));

    % --- 最高能耗点 ---
    disp('--- 最高能耗点 ---');
    disp(array2table(rad2deg(x(maxEnergyIdx,:)), ...
        'VariableNames', {'Joint1','Joint2','Joint3','Joint4','Joint5','Joint6'}));
    disp(array2table([fval(maxEnergyIdx,1), maxEnergy], ...
        'VariableNames', {'EndEffectorError_mm','EnergyConsumption_J'}));

    % --- 均衡点（误差 ≤ 1.1×minError 中能耗最小的）---
    % 【Bug 4 修复】补全被截断的逻辑
    balancedIdx = find(fval(:,1) <= 1.1 * minError);
    if ~isempty(balancedIdx)
        [~, localMin] = min(fval(balancedIdx, 2));
        balancedIdx   = balancedIdx(localMin);
        disp('--- 均衡点 (误差≤1.1×min, 能耗最低) ---');
        disp(array2table(rad2deg(x(balancedIdx,:)), ...
            'VariableNames', {'Joint1','Joint2','Joint3','Joint4','Joint5','Joint6'}));
        disp(array2table(fval(balancedIdx,:), ...
            'VariableNames', {'EndEffectorError_mm','EnergyConsumption_J'}));
    else
        disp('--- 均衡点: 未找到满足误差≤1.1×min的解 ---');
    end
end
```

