# Super Platformer — Complete Single-File Game

Save this as `game.html` and open it in any browser.

**Controls:**
- **A / D** or **← / →** — move
- **W / ↑ / Space** — jump (press again in air for double jump)
- **J** — attack (sword swing)
- **K** — hook (hold to grapple & pull toward the surface; hold **W** while hooking to aim upward)
- **R** — restart after death / victory

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Super Hook Bros</title>
<style>
  html,body{margin:0;height:100%;background:#1a1a2e;display:flex;flex-direction:column;
            align-items:center;justify-content:center;font-family:monospace;}
  canvas{border:3px solid #444;border-radius:6px;background:#87ceeb;}
  #help{color:#ccc;margin-top:10px;font-size:14px;text-align:center;}
  b{color:#ffd93d;}
</style>
</head>
<body>
<canvas id="game" width="960" height="540"></canvas>
<div id="help">
  <b>A/D</b> move &nbsp; <b>W/Space</b> jump (x2) &nbsp; <b>J</b> attack &nbsp;
  <b>K</b> hook (hold W to aim up) &nbsp; <b>R</b> restart
</div>
<script>
"use strict";
const cvs = document.getElementById('game');
const ctx = cvs.getContext('2d');
const W = cvs.width, H = cvs.height;
const GRAV = 1400;
const LEVEL_W = 6400, LEVEL_H = 700;

/* ---------------- AUDIO ---------------- */
let AC = null;
function initAudio(){ if(!AC){ try{ AC = new (window.AudioContext||window.webkitAudioContext)(); }catch(e){} } }
function beep(freq, dur=0.1, type='square', vol=0.04){
  if(!AC) return;
  const o = AC.createOscillator(), g = AC.createGain();
  o.type = type; o.frequency.value = freq;
  g.gain.setValueAtTime(vol, AC.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001, AC.currentTime + dur);
  o.connect(g); g.connect(AC.destination);
  o.start(); o.stop(AC.currentTime + dur);
}

/* ---------------- INPUT ---------------- */
const keys = {}, just = {};
addEventListener('keydown', e=>{
  if(!keys[e.code]) just[e.code] = true;
  keys[e.code] = true;
  initAudio();
  if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)) e.preventDefault();
});
addEventListener('keyup', e=> keys[e.code] = false);

/* ---------------- LEVEL ---------------- */
let platforms, enemies, coins, particles, player, flag, clouds;
let camX = 0, camY = 0, state = 'playing', time = 0;

const P = (x,y,w,h=22) => ({x,y,w,h});

function init(){
  platforms = [
    // ground segments (gaps between them)
    P(0,600,820,100),
    P(920,600,760,100),
    P(1780,600,420,100),
    P(2300,600,900,100),
    P(3300,600,600,100),
    P(4600,600,1800,100),
    // floating platforms
    P(300,470,120),  P(520,360,120),
    P(1000,460,140), P(1250,350,140), P(1500,450,120),
    P(1640,320,40,280),           // tall pillar
    P(1850,460,120), P(2050,340,120),
    P(2400,460,140), P(2650,340,140), P(2900,440,120),
    P(3400,460,120), P(3600,340,120),
    // hook section ledges (above the big pit)
    P(4100,320,140), P(4380,220,120),
    // late-game route
    P(5000,440,140), P(5300,320,140), P(5600,440,140), P(5900,340,140),
  ];

  enemies = [600,1100,1450,1900,2500,2800,3450,4800,5150,5700,6050].map(x=>({
    x, y:574, w:32, h:26, dir:-1, spd:60, vy:0, alive:true,
    t:Math.random()*6, onGround:false
  }));

  coins = [[340,430],[560,320],[700,555],[1040,420],[1290,310],[1540,410],
    [1900,420],[2090,300],[2450,420],[2690,300],[2940,400],[3440,420],
    [3640,300],[4160,270],[4420,170],[5040,400],[5340,280],[5640,400],
    [5940,300],[6100,555],[6200,555]
  ].map(([x,y])=>({x,y,taken:false,t:Math.random()*6}));

  flag = {x:6300, y:600};

  player = {
    x:60, y:566, w:26, h:34, vx:0, vy:0, facing:1,
    onGround:false, jumps:2, coyote:0, hp:3, inv:0,
    attackT:0, attackCd:0,
    hook:{state:'idle', x:0, y:0, range:0},
    coins:0
  };

  particles = [];
  clouds = [];
  for(let i=0;i<18;i++)
    clouds.push({x:Math.random()*LEVEL_W, y:30+Math.random()*180, s:0.6+Math.random()*0.9});

  camX = 0; camY = LEVEL_H - H;
  state = 'playing'; time = 0;
}

/* ---------------- HELPERS ---------------- */
const overlap = (a,b)=> a.x < b.x+b.w && a.x+a.w > b.x && a.y < b.y+b.h && a.y+a.h > b.y;
const clamp = (v,a,b)=> Math.max(a, Math.min(b,v));

function moveEntity(e, dt){
  // horizontal
  e.x += e.vx*dt;
  for(const pl of platforms){
    if(overlap(e,pl)){
      if(e.vx > 0) e.x = pl.x - e.w;
      else if(e.vx < 0) e.x = pl.x + pl.w;
      e.vx = 0;
    }
  }
  // vertical
  e.y += e.vy*dt;
  e.onGround = false;
  for(const pl of platforms){
    if(overlap(e,pl)){
      if(e.vy > 0){ e.y = pl.y - e.h; e.onGround = true; }
      else if(e.vy < 0){ e.y = pl.y + pl.h; }
      e.vy = 0;
    }
  }
}

function pointOnPlatform(px,py){
  for(const pl of platforms)
    if(px>pl.x-2 && px<pl.x+pl.w+2 && py>pl.y-2 && py<pl.y+pl.h+2) return true;
  return false;
}

function burst(x,y,color,n=12){
  for(let i=0;i<n;i++){
    const a = Math.random()*Math.PI*2, s = 60+Math.random()*180;
    particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-60,
                    life:0.4+Math.random()*0.4, color, size:2+Math.random()*3});
  }
}

function damagePlayer(kb){
  if(player.inv > 0) return;
  player.hp--;
  player.inv = 1.5;
  player.vx = kb*260;
  player.vy = -320;
  beep(120,0.25,'sawtooth',0.06);
  burst(player.x+13, player.y+17, '#ff5555', 10);
  if(player.hp <= 0){ state = 'dead'; beep(80,0.6,'sawtooth',0.07); }
}

function killEnemy(e){
  e.alive = false;
  burst(e.x+e.w/2, e.y+e.h/2, '#8b5a2b', 14);
  beep(200,0.15,'triangle',0.05);
}

/* ---------------- UPDATE ---------------- */
function update(dt){
  time += dt;
  if(state !== 'playing'){
    if(just['KeyR']) init();
    return;
  }

  const p = player, h = p.hook;
  const inputX = ((keys['KeyD']||keys['ArrowRight'])?1:0) - ((keys['KeyA']||keys['ArrowLeft'])?1:0);
  const upKey  = keys['KeyW']||keys['ArrowUp']||keys['Space'];

  // ---- hook ----
  const hookKey = keys['KeyK']||keys['KeyE'];
  const hookJust = just['KeyK']||just['KeyE'];
  const cx = p.x+p.w/2, cy = p.y+p.h/2;

  if(hookJust && h.state==='idle'){
    h.state='firing'; h.x=cx; h.y=cy; h.range=0;
    beep(600,0.06,'square',0.03);
  }
  if(!hookKey && h.state==='attached') h.state='idle';

  if(h.state==='firing'){
    let dx = p.facing, dy = upKey ? -1 : 0;
    const len = Math.hypot(dx,dy); dx/=len; dy/=len;
    for(let s=0;s<10;s++){
      h.x += dx*10; h.y += dy*10; h.range += 10;
      if(pointOnPlatform(h.x,h.y)){ h.state='attached'; beep(880,0.08,'sine',0.04); break; }
      if(h.range>420 || h.x<0 || h.x>LEVEL_W || h.y<0){ h.state='idle'; break; }
    }
  } else if(h.state==='attached'){
    const dx = h.x-cx, dy = h.y-cy, d = Math.hypot(dx,dy);
    if(d < 34){ h.state='idle'; }
    else{
      p.vx = dx/d*340 + inputX*150;
      p.vy = dy/d*340;
    }
  }

  // ---- movement ----
  if(h.state !== 'attached'){
    p.vx = inputX*270;
    if(inputX) p.facing = inputX;
    p.vy += GRAV*dt;
    if(p.vy > 900) p.vy = 900;
  }

  // jump (with double jump + coyote time)
  if(just['KeyW']||just['ArrowUp']||just['Space']){
    if(p.onGround || p.coyote>0){
      p.vy = -560; p.jumps = 1; p.coyote = 0;
      beep(300,0.12,'square',0.04);
      burst(cx, p.y+p.h, '#ffffff', 6);
    } else if(p.jumps > 0){
      p.vy = -520; p.jumps = 0;
      beep(420,0.12,'square',0.04);
      burst(cx, p.y+p.h, '#aee6ff', 8);
    }
  }

  moveEntity(p, dt);
  p.coyote = p.onGround ? 0.1 : p.coyote - dt;
  if(p.onGround) p.jumps = 2;

  // fell into a pit
  if(p.y > LEVEL_H + 100){ p.hp = 0; state='dead'; beep(80,0.6,'sawtooth',0.07); }

  // ---- attack ----
  p.attackT -= dt; p.attackCd -= dt;
  if((just['KeyJ']||just['KeyX']) && p.attackCd <= 0){
    p.attackT = 0.22; p.attackCd = 0.35;
    beep(500,0.08,'square',0.03);
  }
  if(p.attackT > 0){
    const hb = { x: p.facing>0 ? p.x+p.w : p.x-50, y: p.y+2, w:50, h:30 };
    for(const e of enemies)
      if(e.alive && overlap(hb,e)) killEnemy(e);
  }

  // ---- enemies ----
  for(const e of enemies){
    if(!e.alive) continue;
    e.t += dt;
    e.vy += GRAV*dt;
    e.x += e.dir*e.spd*dt;
    for(const pl of platforms)
      if(overlap(e,pl)){ e.x = e.dir>0 ? pl.x-e.w : pl.x+pl.w; e.dir*=-1; }
    e.y += e.vy*dt; e.onGround = false;
    for(const pl of platforms)
      if(overlap(e,pl)){
        if(e.vy>0){ e.y = pl.y-e.h; e.onGround=true; } else e.y = pl.y+pl.h;
        e.vy = 0;
      }
    // turn at edges
    if(e.onGround){
      const ax = e.dir>0 ? e.x+e.w+3 : e.x-3, fy = e.y+e.h+5;
      let g = false;
      for(const pl of platforms)
        if(ax>pl.x && ax<pl.x+pl.w && fy>pl.y && fy<pl.y+pl.h){ g=true; break; }
      if(!g) e.dir *= -1;
    }
    // player collision
    if(overlap(p,e)){
      if(p.vy > 100 && (p.y+p.h) - e.y < 16){
        killEnemy(e); p.vy = -450; p.jumps = 1;
      } else damagePlayer(e.dir>0?1:-1);
    }
  }

  // ---- coins ----
  for(const c of coins){
    if(c.taken) continue;
    c.t += dt;
    const bob = Math.sin(c.t*3)*4;
    const dx = c.x-cx, dy = (c.y+bob)-cy;
    if(dx*dx+dy*dy < 30*30){
      c.taken = true; p.coins++;
      beep(900,0.08,'sine',0.05);
      setTimeout(()=>beep(1300,0.1,'sine',0.05), 60);
      burst(c.x, c.y, '#ffd93d', 8);
    }
  }

  // ---- particles ----
  for(let i=particles.length-1;i>=0;i--){
    const pt = particles[i];
    pt.x += pt.vx*dt; pt.y += pt.vy*dt;
    pt.vy += GRAV*0.4*dt; pt.life -= dt;
    if(pt.life <= 0) particles.splice(i,1);
  }

  p.inv -= dt;

  // ---- win ----
  if(p.x + p.w > flag.x){
    state = 'win';
    beep(523,0.15,'square',0.05);
    setTimeout(()=>beep(659,0.15,'square',0.05),150);
    setTimeout(()=>beep(784,0.3,'square',0.05),300);
  }

  // ---- camera ----
  const tx = clamp(cx - W*0.4, 0, LEVEL_W-W);
  const ty = clamp(cy - H*0.55, 0, LEVEL_H-H);
  camX += (tx-camX)*Math.min(1, dt*8);
  camY += (ty-camY)*Math.min(1, dt*8);
}

/* ---------------- DRAW ---------------- */
function draw(){
  // sky
  const g = ctx.createLinearGradient(0,0,0,H);
  g.addColorStop(0,'#6ec6ff'); g.addColorStop(1,'#cfeeff');
  ctx.fillStyle = g; ctx.fillRect(0,0,W,H);

  // clouds (parallax)
  ctx.fillStyle = 'rgba(255,255,255,0.85)';
  for(const c of clouds){
    const sx = ((c.x - camX*0.4) % (LEVEL_W*0.6) + LEVEL_W*0.6) % (LEVEL_W*0.6) - 200;
    const sy = c.y - camY*0.3;
    ctx.beginPath();
    ctx.ellipse(sx, sy, 40*c.s, 16*c.s, 0, 0, Math.PI*2);
    ctx.ellipse(sx+28*c.s, sy-8*c.s, 26*c.s, 14*c.s, 0, 0, Math.PI*2);
    ctx.ellipse(sx-28*c.s, sy-4*c.s, 22*c.s, 12*c.s, 0, 0, Math.PI*2);
    ctx.fill();
  }

  // hint above the big pit
  ctx.save();
  ctx.translate(-camX, -camY);
  ctx.fillStyle = '#1a1a2e';
  ctx.font = 'bold 18px monospace';
  ctx.textAlign = 'center';
  ctx.fillText('⚠ big pit — use the HOOK (K)!', 4250, 480);
  ctx.restore();

  // platforms
  for(const pl of platforms){
    const x = pl.x-camX, y = pl.y-camY;
    if(x+pl.w < 0 || x > W) continue;
    ctx.fillStyle = '#8b5a2b';
    ctx.fillRect(x, y, pl.w, pl.h);
    ctx.fillStyle = '#5f3d1c';
    for(let i=0;i<pl.w;i+=26)
      for(let j=14;j<pl.h;j+=22)
        ctx.fillRect(x+i+((j/22)%2)*13, y+j, 14, 10);
    ctx.fillStyle = '#4caf50';
    ctx.fillRect(x, y, pl.w, 8);
    ctx.fillStyle = '#66d96a';
    ctx.fillRect(x, y, pl.w, 3);
  }

  // flag
  const fx = flag.x-camX, fy = flag.y-camY;
  ctx.fillStyle = '#888';
  ctx.fillRect(fx-3, fy-160, 6, 160);
  ctx.fillStyle = '#ffd93d';
  ctx.beginPath(); ctx.arc(fx, fy-163, 7, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#e33';
  ctx.beginPath();
  ctx.moveTo(fx+3, fy-158);
  ctx.lineTo(fx+55, fy-140);
  ctx.lineTo(fx+3, fy-122);
  ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#666';
  ctx.fillRect(fx-14, fy-8, 28, 8);

  // coins
  for(const c of coins){
    if(c.taken) continue;
    const x = c.x-camX, y = c.y-camY + Math.sin(c.t*3)*4;
    if(x<-20||x>W+20) continue;
    ctx.fillStyle = '#ffd93d';
    ctx.beginPath(); ctx.arc(x,y,9,0,Math.PI*2); ctx.fill();
    ctx.fillStyle = '#e6b800';
    ctx.beginPath(); ctx.arc(x,y,5,0,Math.PI*2); ctx.fill();
    ctx.fillStyle = '#fff7cc';
    ctx.fillRect(x-3, y-6, 2, 4);
  }

  // enemies
  for(const e of enemies){
    if(!e.alive) continue;
    const x = e.x-camX, y = e.y-camY;
    if(x<-40||x>W+40) continue;
    const step = Math.sin(e.t*12)*3;
    ctx.fillStyle = '#4a2c12';
    ctx.fillRect(x+3+step, y+e.h-5, 10, 5);
    ctx.fillRect(x+e.w-13-step, y+e.h-5, 10, 5);
    ctx.fillStyle = '#8b5a2b';
    ctx.beginPath();
    ctx.ellipse(x+e.w/2, y+e.h/2, e.w/2, e.h/2, 0, 0, Math.PI*2);
    ctx.fill();
    // eyes
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.arc(x+9, y+9, 5, 0, Math.PI*2); ctx.arc(x+e.w-9, y+9, 5, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#000';
    ctx.beginPath();
    ctx.arc(x+9+e.dir*2, y+10, 2.4, 0, Math.PI*2);
    ctx.arc(x+e.w-9+e.dir*2, y+10, 2.4, 0, Math.PI*2);
    ctx.fill();
    // angry brows
    ctx.strokeStyle = '#3a2008'; ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x+4, y+3); ctx.lineTo(x+14, y+6);
    ctx.moveTo(x+e.w-4, y+3); ctx.lineTo(x+e.w-14, y+6);
    ctx.stroke();
  }

  // particles
  for(const pt of particles){
    ctx.globalAlpha = Math.max(0, pt.life*2);
    ctx.fillStyle = pt.color;
    ctx.fillRect(pt.x-camX-pt.size/2, pt.y-camY-pt.size/2, pt.size, pt.size);
  }
  ctx.globalAlpha = 1;

  // hook line
  const p = player;
  if(p.hook.state === 'firing' || p.hook.state === 'attached'){
    const hx = p.hook.x-camX, hy = p.hook.y-camY;
    const px = p.x+p.w/2-camX, py = p.y+p.h/2-camY;
    ctx.strokeStyle = '#555'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(px,py); ctx.lineTo(hx,hy); ctx.stroke();
    ctx.fillStyle = '#999';
    ctx.beginPath(); ctx.arc(hx,hy,5,0,Math.PI*2); ctx.fill();
    ctx.fillStyle = '#333';
    ctx.beginPath(); ctx.arc(hx,hy,2.5,0,Math.PI*2); ctx.fill();
  }

  // player (blink while invulnerable)
  if(!(p.inv>0 && Math.floor(p.inv*12)%2===0)){
    ctx.save();
    ctx.translate(p.x+p.w/2-camX, p.y+p.h/2-camY);
    ctx.scale(p.facing,1);
    // hat
    ctx.fillStyle = '#e33';
    ctx.fillRect(-11,-21,22,6);
    ctx.fillRect(0,-17,13,3);
    // head
    ctx.fillStyle = '#fcd7b0';
    ctx.fillRect(-9,-15,18,10);
    ctx.fillStyle = '#222';
    ctx.fillRect(3,-13,3,4);
