### `Services/GuidedProcessService.cs`

```csharp
using GuidedProcess.Models;
using Microsoft.Extensions.Caching.Memory;

namespace GuidedProcess.Services;

public class GuidedProcessService : IGuidedProcessService
{
    private readonly IMemoryCache _cache;
    private readonly Dictionary<string, GuidedProcessConfig> _processConfigs;
    private readonly ILogger<GuidedProcessService> _logger;

    public GuidedProcessService(IMemoryCache cache, ILogger<GuidedProcessService> logger)
    {
        _cache = cache;
        _logger = logger;
        _processConfigs = new Dictionary<string, GuidedProcessConfig>();
    }

    public void RegisterProcess(GuidedProcessConfig config)
    {
        _processConfigs[config.ProcessId] = config;
        _logger.LogInformation("Registered guided process: {ProcessId} with {StepCount} steps",
            config.ProcessId, config.Steps.Count);
    }

    public GuidedProcessConfig GetProcessConfig(string processId)
    {
        if (!_processConfigs.TryGetValue(processId, out var config))
            throw new InvalidOperationException($"Process '{processId}' not found.");
        return config;
    }

    public ProcessState InitializeProcess(string processId)
    {
        var config = GetProcessConfig(processId);
        var state = new ProcessState
        {
            ProcessId = processId,
            SessionToken = Guid.NewGuid().ToString("N"),
            CurrentStepIndex = 0,
            FieldValues = new Dictionary<string, object?>(),
            StepProgress = config.Steps.Select(s => new StepProgress
            {
                StepId = s.StepId,
                Status = s.StepOrder == 1 ? StepStatus.Active : StepStatus.Pending
            }).ToList(),
            StartedAt = DateTime.UtcNow
        };

        CacheState(state);
        _logger.LogInformation("Initialized process {ProcessId}, session: {Token}", processId, state.SessionToken);
        return state;
    }

    public StepDefinition GetCurrentStep(ProcessState state)
    {
        var config = GetProcessConfig(state.ProcessId);
        return config.Steps[state.CurrentStepIndex];
    }

    public StepResult AdvanceStep(ProcessState state, Dictionary<string, object?> fieldValues)
    {
        // 1. Validate current step
        var validation = ValidateStep(state, fieldValues);
        if (!validation.Success)
            return validation;

        // 2. Merge field values into state
        foreach (var kvp in fieldValues)
            state.FieldValues[kvp.Key] = kvp.Value;

        // 3. Mark current step as completed
        state.StepProgress[state.CurrentStepIndex].Status = StepStatus.Completed;
        state.StepProgress[state.CurrentStepIndex].CompletedAt = DateTime.UtcNow;

        // 4. Advance to next step
        var config = GetProcessConfig(state.ProcessId);
        if (state.CurrentStepIndex < config.Steps.Count - 1)
        {
            state.CurrentStepIndex++;
            state.StepProgress[state.CurrentStepIndex].Status = StepStatus.Active;
        }
        else
        {
            state.IsCompleted = true;
            state.CompletedAt = DateTime.UtcNow;
        }

        CacheState(state);
        return new StepResult
        {
            Success = true,
            NextStepIndex = state.CurrentStepIndex,
            UpdatedState = state,
            Message = state.IsCompleted ? "Process completed!" : $"Step {state.CurrentStepIndex + 1} of {config.Steps.Count}"
        };
    }

    public StepResult GoBack(ProcessState state)
    {
        var config = GetProcessConfig(state.ProcessId);
        if (state.CurrentStepIndex <= 0)
            return new StepResult { Success = false, Message = "Cannot go back further." };

        state.StepProgress[state.CurrentStepIndex].Status = StepStatus.Pending;
        state.CurrentStepIndex--;
        state.StepProgress[state.CurrentStepIndex].Status = StepStatus.Active;

        CacheState(state);
        return new StepResult
        {
            Success = true,
            NextStepIndex = state.CurrentStepIndex,
            UpdatedState = state
        };
    }

    public StepResult ValidateStep(ProcessState state, Dictionary<string, object?> fieldValues)
    {
        var config = GetProcessConfig(state.ProcessId);
        var step = config.Steps[state.CurrentStepIndex];
        var errors = new List<ValidationError>();

        foreach (var field in step.Fields)
        {
            var value = fieldValues.TryGetValue(field.FieldId, out var v) ? v?.ToString()?.Trim() : null;

            // Required check
            if (field.IsRequired && string.IsNullOrWhiteSpace(value))
            {
                errors.Add(new ValidationError
                {
                    FieldId = field.FieldId,
                    FieldLabel = field.Label,
                    Message = $"{field.Label} is required."
                });
                continue;
            }

            if (string.IsNullOrWhiteSpace(value)) continue;

            // Length validation
            if (value.Length < field.MinLength)
                errors.Add(new ValidationError
                {
                    FieldId = field.FieldId,
                    FieldLabel = field.Label,
                    Message = $"{field.Label} must be at least {field.MinLength} characters."
                });

            if (value.Length > field.MaxLength)
                errors.Add(new ValidationError
                {
                    FieldId = field.FieldId,
                    FieldLabel = field.Label,
                    Message = $"{field.Label} must not exceed {field.MaxLength} characters."
                });

            // Regex validation
            if (!string.IsNullOrEmpty(field.ValidationRegex))
            {
                if (!System.Text.RegularExpressions.Regex.IsMatch(value, field.ValidationRegex))
                {
                    errors.Add(new ValidationError
                    {
                        FieldId = field.FieldId,
                        FieldLabel = field.Label,
                        Message = field.ValidationMessage ?? $"{field.Label} is invalid."
                    });
                }
            }

            // Type-specific validation
            if (field.FieldType == "email" && !value.Contains('@'))
            {
                errors.Add(new ValidationError
                {
                    FieldId = field.FieldId,
                    FieldLabel = field.Label,
                    Message = "Please enter a valid email address."
                });
            }
        }

        return new StepResult
        {
            Success = errors.Count == 0,
            Errors = errors,
            NextStepIndex = state.CurrentStepIndex
        };
    }

    public ProcessState CompleteProcess(ProcessState state)
    {
        state.IsCompleted = true;
        state.CompletedAt = DateTime.UtcNow;
        CacheState(state);
        return state;
    }

    public ProcessState GetProcessState(string sessionToken)
    {
        if (_cache.TryGetValue($"process:{sessionToken}", out ProcessState? state))
            return state;
        throw new InvalidOperationException("Session expired or not found.");
    }

    private void CacheState(ProcessState state)
    {
        var options = new MemoryCacheEntryOptions
            .SetAbsoluteExpiration(TimeSpan.FromMinutes(30));
        _cache.Set($"process:{state.SessionToken}", state, options);
    }
}
