## 5. Controller

### `Controllers/GuidedProcessController.cs`

```csharp
using GuidedProcess.Models;
using GuidedProcess.Services;
using Microsoft.AspNetCore.Mvc;

namespace GuidedProcess.Controllers;

[ApiController]
[Route("api/[controller]")]
public class GuidedProcessController : ControllerBase
{
    private readonly IGuidedProcessService _processService;

    public GuidedProcessController(IGuidedProcessService processService)
    {
        _processService = processService;
    }

    // GET: Get the full process config (steps, fields, metadata)
    [HttpGet("config/{processId}")]
    public IActionResult GetConfig(string processId)
    {
        var config = _processService.GetProcessConfig(processId);
        return Ok(config);
    }

    // POST: Initialize a new process session
    [HttpPost("initialize/{processId}")]
    public IActionResult Initialize(string processId)
    {
        var state = _processService.InitializeProcess(processId);
        return Ok(new
        {
            SessionToken = state.SessionToken,
            CurrentStep = _processService.GetCurrentStep(state),
            CurrentStepIndex = state.CurrentStepIndex,
            TotalSteps = _processService.GetProcessConfig(processId).Steps.Count,
            StepProgress = state.StepProgress
        });
    }

    // POST: Advance to next step (validates current step)
    [HttpPost("advance")]
    public IActionResult Advance([FromBody] AdvanceRequest request)
    {
        var state = _processService.GetProcessState(request.SessionToken);
        var result = _processService.AdvanceStep(state, request.FieldValues);

        if (!result.Success)
            return BadRequest(new { errors = result.Errors });

        var config = _processService.GetProcessConfig(state.ProcessId);
        return Ok(new
        {
            SessionToken = state.SessionToken,
            CurrentStep = state.IsCompleted ? null : _processService.GetCurrentStep(state),
            CurrentStepIndex = state.CurrentStepIndex,
            TotalSteps = config.Steps.Count,
            IsCompleted = state.IsCompleted,
            SuccessMessage = state.IsCompleted ? config.SuccessMessage : null,
            StepProgress = state.StepProgress
        });
    }

    // POST: Go back to previous step
    [HttpPost("back")]
    public IActionResult GoBack([FromBody] SessionRequest request)
    {
        var state = _processService.GetProcessState(request.SessionToken);
        var result = _processService.GoBack(state);

        if (!result.Success)
            return BadRequest(new { message = result.Message });

        return Ok(new
        {
            SessionToken = state.SessionToken,
            CurrentStep = _processService.GetCurrentStep(state),
            CurrentStepIndex = state.CurrentStepIndex,
            FieldValues = state.FieldValues, // restore previous values
            StepProgress = state.StepProgress
        });
    }

    // POST: Validate a specific field (real-time)
    [HttpPost("validate-field")]
    public IActionResult ValidateField([FromBody] ValidateFieldRequest request)
    {
        var state = _processService.GetProcessState(request.SessionToken);
        var config = _processService.GetProcessConfig(state.ProcessId);
        var step = config.Steps[state.CurrentStepIndex];
        var field = step.Fields.FirstOrDefault(f => f.FieldId == request.FieldId);

        if (field == null)
            return NotFound(new { message = "Field not found in current step." });

        var value = request.Value?.Trim();
        var errors = new List<string>();

        if (field.IsRequired && string.IsNullOrWhiteSpace(value))
            errors.Add($"{field.Label} is required.");

        if (!string.IsNullOrWhiteSpace(value))
        {
            if (value.Length < field.MinLength)
                errors.Add($"{field.Label} must be at least {field.MinLength} characters.");
            if (value.Length > field.MaxLength)
                errors.Add($"{field.Label} must not exceed {field.MaxLength} characters.");
            if (!string.IsNullOrEmpty(field.ValidationRegex) &&
                !System.Text.RegularExpressions.Regex.IsMatch(value, field.ValidationRegex))
                errors.Add(field.ValidationMessage ?? $"{field.Label} is invalid.");
        }

        return Ok(new { isValid = errors.Count == 0, errors });
    }

    // GET: Get saved state (for page refresh)
    [HttpGet("state/{sessionToken}")]
    public IActionResult GetState(string sessionToken)
    {
        var state = _processService.GetProcessState(sessionToken);
        var config = _processService.GetProcessConfig(state.ProcessId);

        return Ok(new
        {
            SessionToken = state.SessionToken,
            CurrentStepIndex = state.CurrentStepIndex,
            CurrentStep = state.IsCompleted ? null : config.Steps[state.CurrentStepIndex],
            FieldValues = state.FieldValues,
            StepProgress = state.StepProgress,
            IsCompleted = state.IsCompleted
        });
    }
}

// ─── Request DTOs ───

public class AdvanceRequest
{
    public string SessionToken { get; set; } = string.Empty;
    public Dictionary<string, object?> FieldValues { get; set; } = new();
}

public class SessionRequest
{
    public string SessionToken { get; set; } = string.Empty;
}

public class ValidateFieldRequest
{
    public string SessionToken { get; set; } = string.Empty;
    public string FieldId { get; set; } = string.Empty;
    public string? Value { get; set; }
}
