### `wwwroot/index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>User Registration — Guided Process</title>
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" />
    <link rel="stylesheet" href="css/guided-process.css" />
</head>
<body>
    <div class="app-container">
        <!-- Header -->
        <header class="app-header">
            <h1><i class="fa fa-user-plus"></i> Create Your Account</h1>
            <p class="subtitle">Complete the steps below to register</p>
        </header>

        <!-- Step Indicator / Progress Bar -->
        <nav class="step-indicator" id="stepIndicator">
            <!-- Dynamically populated -->
        </nav>

        <!-- Progress Bar -->
        <div class="progress-bar-container">
            <div class="progress-bar" id="progressBar"></div>
        </div>

        <!-- Main Content Area -->
        <main class="process-content">
            <!-- Step Header (title + description) -->
            <div class="step-header" id="stepHeader">
                <div class="step-icon" id="stepIcon"></div>
                <div>
                    <h2 id="stepTitle">Loading...</h2>
                    <p id="stepDescription"></p>
                </div>
            </div>

            <!-- Help / Info Panel -->
            <div class="help-panel" id="helpPanel">
                <div class="help-panel-content">
                    <i class="fa fa-info-circle"></i>
                    <div>
                        <p class="help-text" id="helpText"></p>
                        <p class="tip-text" id="tipText"></p>
                    </div>
                </div>
            </div>

            <!-- Form Fields Container -->
            <form id="processForm" class="process-form" autocomplete="off">
                <!-- Fields are dynamically rendered here -->
                <div id="fieldsContainer" class="fields-container"></div>
            </form>

            <!-- Validation Errors -->
            <div class="errors-container" id="errorsContainer" style="display:none;">
                <i class="fa fa-exclamation-triangle"></i>
                <ul id="errorsList"></ul>
            </div>

            <!-- Navigation Buttons -->
            <div class="nav-buttons">
                <button type="button" class="btn btn-back" id="btnBack">
                    <i class="fa fa-arrow-left"></i> Back
                </button>
                <button type="button" class="btn btn-next" id="btnNext">
                    Continue <i class="fa fa-arrow-right"></i>
                </button>
                <button type="button" class="btn btn-submit" id="btnSubmit" style="display:none;">
                    <i class="fa fa-check"></i> Create Account
                </button>
            </div>
        </main>

        <!-- Success Overlay -->
        <div class="success-overlay" id="successOverlay" style="display:none;">
            <div class="success-card">
                <i class="fa fa-check-circle success-icon"></i>
                <h2>Registration Complete!</h2>
                <p id="successMessage"></p>
                <button class="btn btn-primary" onclick="location.reload()">Start New Registration</button>
            </div>
        </div>
    </div>

    <script src="js/guided-process.js"></script>
</body>
