### `wwwroot/css/guided-process.css`

```css
/* ═══════════════════════════════════════════
   GUIDED PROCESS — SINGLE PAGE UI
   ═══════════════════════════════════════════ */

:root {
    --primary: #4f46e5;
    --primary-light: #818cf8;
    --primary-bg: #eef2ff;
    --success: #10b981;
    --danger: #ef4444;
    --warning: #f59e0b;
    --gray-50: #f9fafb;
    --gray-100: #f3f4f6;
    --gray-200: #e5e7eb;
    --gray-300: #d1d5db;
    --gray-400: #9ca3af;
    --gray-500: #6b7280;
    --gray-600: #4b5563;
    --gray-700: #374151;
    --gray-800: #1f2937;
    --radius: 12px;
    --shadow: 0 4px 24px rgba(0,0,0,0.08);
    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

.app-container {
    background: #fff;
    border-radius: 20px;
    box-shadow: 0 20px 60px rgba(0,0,0,0.15);
    width: 100%;
    max-width: 680px;
    padding: 40px;
    position: relative;
    overflow: hidden;
}

/* ─── Header ─── */
.app-header {
    text-align: center;
    margin-bottom: 30px;
}
.app-header h1 {
    font-size: 1.8rem;
    color: var(--gray-800);
    margin-bottom: 6px;
}
.app-header h1 i { color: var(--primary); margin-right: 10px; }
.app-header .subtitle {
    color: var(--gray-500);
    font-size: 0.95rem;
}

/* ─── Step Indicator ─── */
.step-indicator {
    display: flex;
    justify-content: center;
    align-items: center;
    margin-bottom: 20px;
    gap: 0;
}

.step-dot {
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    z-index: 2;
}

.step-dot .dot {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.8rem;
    font-weight: 700;
    border: 3px solid var(--gray-300);
    background: #fff;
    color: var(--gray-400);
    transition: var(--transition);
}

.step-dot .dot-label {
    margin-top: 8px;
    font-size: 0.7rem;
    color: var(--gray-400);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    white-space: nowrap;
}

.step-dot.active .dot {
    border-color: var(--primary);
    background: var(--primary);
    color: #fff;
    transform: scale(1.15);
    box-shadow: 0 0 0 6px rgba(79, 70, 229, 0.15);
}
.step-dot.active .dot-label { color: var(--primary); }

.step-dot.completed .dot {
    border-color: var(--success);
    background: var(--success);
    color: #fff;
}
.step-dot.completed .dot-label { color: var(--success); }

.step-connector {
    width: 50px;
    height: 3px;
    background: var(--gray-200);
    margin: 0 4px;
    margin-bottom: 24px;
    border-radius: 2px;
    transition: var(--transition);
}
.step-connector.completed { background: var(--success); }
.step-connector.active { background: var(--primary); }

/* ─── Progress Bar ─── */
.progress-bar-container {
    height: 6px;
    background: var(--gray-100);
    border-radius: 3px;
    margin-bottom: 30px;
    overflow: hidden;
}
.progress-bar {
    height: 100%;
    background: linear-gradient(90deg, var(--primary), var(--primary-light));
    border-radius: 3px;
    transition: width 0.5s ease;
    width: 0%;
}

/* ─── Step Header ─── */
.step-header {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    margin-bottom: 20px;
}
.step-icon {
    width: 50px;
    height: 50px;
    border-radius: var(--radius);
    background: var(--primary-bg);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.3rem;
    color: var(--primary);
    flex-shrink: 0;
}
.step-header h2 {
    font-size: 1.4rem;
    color: var(--gray-800);
    margin-bottom: 4px;
}
.step-header p {
    color: var(--gray-500);
    font-size: 0.9rem;
}

/* ─── Help Panel ─── */
.help-panel {
    background: #fffbeb;
    border: 1px solid #fde68a;
    border-radius: var(--radius);
    padding: 14px 18px;
    margin-bottom: 24px;
    animation: slideDown 0.3s ease;
}
.help-panel-content {
    display: flex;
    gap: 12px;
    align-items: flex-start;
}
.help-panel-content > i {
    color: var(--warning);
    font-size: 1.2rem;
    margin-top: 2px;
}
.help-text {
    font-size: 0.9rem;
    color: var(--gray-700);
    margin-bottom: 4px;
    font-weight: 500;
}
.tip-text {
    font-size: 0.82rem;
    color: var(--gray-500);
}

@keyframes slideDown {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* ─── Form Fields ─── */
.fields-container {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.field-group {
    position: relative;
    border-radius: var(--radius);
    padding: 16px;
    border: 2px solid transparent;
    transition: var(--transition);
    opacity: 0.4;
    pointer-events: none;
    filter: grayscale(0.5);
}

/* THE KEY CLASS: Active field is fully interactive */
.field-group.active {
    opacity: 1;
    pointer-events: auto;
    filter: none;
    border-color: var(--primary);
    background: var(--primary-bg);
    box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.1);
    animation: fieldGlow 2s ease-in-out infinite alternate;
}

@keyframes fieldGlow {
    from { box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.1); }
    to { box-shadow: 0 0 0 8px rgba(79, 70, 229, 0.05); }
}

.field-group.completed {
    opacity: 0.7;
    border-color: var(--success);
    background: #f0fdf4;
    pointer-events: none;
}

.field-group.error {
    border-color: var(--danger);
    background: #fef2f2;
    animation: shake 0.4s ease;
}

@keyframes shake {
    0%, 100% { transform: translateX(0); }
    25% { transform: translateX(-5px); }
    75% { transform: translateX(5px); }
}

.field-group label {
    display: block;
    font-weight: 600;
    font-size: 0.9rem;
    color: var(--gray-700);
    margin-bottom: 8px;
}

.field-group label .required-star {
    color: var(--danger);
    margin-left: 2px;
}

.field-group input,
.field-group select,
.field-group textarea {
    width: 100%;
    padding: 12px 16px;
    border: 2px solid var(--gray-200);
    border-radius: 8px;
    font-size: 1rem;
    font-family: inherit;
    transition: var(--transition);
    background: #fff;
}

.field-group input:focus,
.field-group select:focus,
.field-group textarea:focus {
    outline: none;
    border-color: var(--primary);
    box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

.field-group input:disabled,
.field-group select:disabled {
    background: var(--gray-100);
    cursor: not-allowed;
}

.field-group .field-error {
    color: var(--danger);
    font-size: 0.8rem;
    margin-top: 6px;
    display: none;
}
.field-group.error .field-error { display: block; }

/* Password strength indicator */
.password-strength {
    height: 4px;
    border-radius: 2px;
    margin-top: 8px;
    background: var(--gray-200);
    overflow: hidden;
}
.password-strength .bar {
    height: 100%;
    border-radius: 2px;
    transition: var(--transition);
    width: 0%;
}

/* ─── Errors Container ─── */
.errors-container {
    background: #fef2f2;
    border: 1px solid #fecaca;
    border-radius: var(--radius);
    padding: 14px 18px;
    margin-top: 16px;
    color: var(--danger);
}
.errors-container i { margin-right: 8px; }
.errors-container ul {
    list-style: none;
    margin-top: 8px;
    padding-left: 24px;
}
.errors-container li {
    font-size: 0.85rem;
    margin-bottom: 4px;
    list-style: "•";
}

/* ─── Navigation Buttons ─── */
.nav-buttons {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 30px;
    padding-top: 20px;
    border-top: 1px solid var(--gray-200);
}

.btn {
    padding: 12px 28px;
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    border: none;
    transition: var(--transition);
    display: flex;
    align-items: center;
    gap: 8px;
}
.btn:disabled { opacity: 0.5; cursor: not-allowed; }

.btn-back {
    background: var(--gray-100);
    color: var(--gray-600);
}
.btn-back:hover:not(:disabled) { background: var(--gray-200); }

.btn-next {
    background: var(--primary);
    color: #fff;
}
.btn-next:hover:not(:disabled) {
    background: #4338ca;
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3);
}

.btn-submit {
    background: var(--success);
    color: #fff;
}
.btn-submit:hover { background: #059669; transform: translateY(-1px); }

.btn-primary {
    background: var(--primary);
    color: #fff;
    margin-top: 20px;
}

/* ─── Success Overlay ─── */
.success-overlay {
    position: absolute;
    inset: 0;
    background: rgba(255,255,255,0.97);
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 20px;
    z-index: 100;
    animation: fadeIn 0.4s ease;
}
.success-card {
    text-align: center;
    padding: 40px;
}
.success-icon {
    font-size: 4rem;
    color: var(--success);
    margin-bottom: 16px;
    animation: bounceIn 0.6s ease;
}
.success-card h2 { color: var(--gray-800); margin-bottom: 8px; }
.success-card p { color: var(--gray-500); }

@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes bounceIn {
    0% { transform: scale(0); }
    60% { transform: scale(1.2); }
    100% { transform: scale(1); }
}

/* ─── Responsive ─── */
@media (max-width: 600px) {
    .app-container { padding: 24px; }
    .step-connector { width: 25px; }
    .step-dot .dot { width: 32px; height: 32px; font-size: 0.7rem; }
    .step-dot .dot-label { font-size: 0.6rem; }
    .nav-buttons { flex-direction: column; gap: 12px; }
    .nav-buttons .btn { width: 100%; justify-content: center; }
}
