### `wwwroot/js/guided-process.js`

```javascript
/**
 * GUIDED PROCESS ENGINE — Frontend Controller
 * 
 * Manages the single-page guided experience:
 * - Renders steps dynamically
 * - Enables/disables fields based on current step
 * - Highlights active field with glow animation
 * - Shows contextual help/tip for each field
 * - Handles validation (client + server)
 * - Manages navigation (next/back)
 */

class GuidedProcessEngine {
    constructor(processId) {
        this.processId = processId;
        this.sessionToken = null;
        this.currentStepIndex = 0;
        this.totalSteps = 0;
        this.currentStep = null;
        this.stepProgress = [];
        this.fieldValues = {};
        this.activeFieldIndex = 0; // which field within the step is active

        // DOM references
        this.dom = {
            stepIndicator: document.getElementById('stepIndicator'),
            progressBar: document.getElementById('progressBar'),
            stepTitle: document.getElementById('stepTitle'),
            stepDescription: document.getElementById('stepDescription'),
            stepIcon: document.getElementById('stepIcon'),
            helpPanel: document.getElementById('helpPanel'),
            helpText: document.getElementById('helpText'),
            tipText: document.getElementById('tipText'),
            fieldsContainer: document.getElementById('fieldsContainer'),
            errorsContainer: document.getElementById('errorsContainer'),
            errorsList: document.getElementById('errorsList'),
            btnBack: document.getElementById('btnBack'),
            btnNext: document.getElementById('btnNext'),
            btnSubmit: document.getElementById('btnSubmit'),
            successOverlay: document.getElementById('successOverlay'),
            successMessage: document.getElementById('successMessage'),
        };

        this.init();
    }

    // ─── Initialization ───
    async init() {
        try {
            // 1. Fetch process config
            const configRes = await fetch(`/api/GuidedProcess/config/${this.processId}`);
            if (!configRes.ok) throw new Error('Failed to load config');
            this.config = await configRes.json();
            this.totalSteps = this.config.Steps.length;

            // 2. Initialize session
            const initRes = await fetch(`/api/GuidedProcess/initialize/${this.processId}`, {
                method: 'POST'
            });
            const initData = await initRes.json();
            this.sessionToken = initData.SessionToken;
            this.currentStepIndex = initData.CurrentStepIndex;
            this.currentStep = initData.CurrentStep;
            this.stepProgress = initData.StepProgress;

            // 3. Bind events
            this.bindEvents();

            // 4. Render
            this.renderStepIndicator();
            this.renderCurrentStep();
            this.updateProgressBar();

        } catch (err) {
            console.error('Guided Process init failed:', err);
            alert('Failed to initialize. Please refresh.');
        }
    }

    bindEvents() {
        this.dom.btnNext.addEventListener('click', () => this.handleNext());
        this.dom.btnBack.addEventListener('click', () => this.handleBack());
        this.dom.btnSubmit.addEventListener('click', () => this.handleSubmit());

        // Keyboard navigation
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' && e.target.tagName !== 'TEXTAREA') {
                e.preventDefault();
                this.handleNext();
            }
        });
    }

    // ─── Step Indicator (dots at top) ───
    renderStepIndicator() {
        this.dom.stepIndicator.innerHTML = '';

        this.config.Steps.forEach((step, idx) => {
            const dot = document.createElement('div');
            dot.className = 'step-dot';
            dot.id = `step-dot-${idx}`;

            let statusClass = '';
            if (idx < this.currentStepIndex) statusClass = 'completed';
            else if (idx === this.currentStepIndex) statusClass = 'active';

            dot.classList.add(statusClass);

            const icon = idx < this.currentStepIndex
                ? '<i class="fa fa-check"></i>'
                : (idx + 1);

            dot.innerHTML = `
                <div class="dot">${icon}</div>
                <span class="dot-label">${step.Title.split(' ')[0]}</span>
            `;
            this.dom.stepIndicator.appendChild(dot);

            // Connector line
            if (idx < this.config.Steps.length - 1) {
                const conn = document.createElement('div');
                conn.className = 'step-connector';
                if (idx < this.currentStepIndex) conn.classList.add('completed');
                else if (idx === this.currentStepIndex) conn.classList.add('active');
                this.dom.stepIndicator.appendChild(conn);
            }
        });
    }

    updateProgressBar() {
        const pct = ((this.currentStepIndex) / this.totalSteps) * 100;
        this.dom.progressBar.style.width = `${pct}%`;
    }

    // ─── Render Current Step ───
    renderCurrentStep() {
        const step = this.currentStep;
        this.activeFieldIndex = 0;

        // Update header
        this.dom.stepTitle.textContent = step.Title;
        this.dom.stepDescription.textContent = step.Description;
        this.dom.stepIcon.innerHTML = `<i class="${step.IconClass}"></i>`;

        // Render fields
        this.dom.fieldsContainer.innerHTML = '';
        step.Fields.forEach((field, idx) => {
            const group = this.createFieldGroup(field, idx);
            this.dom.fieldsContainer.appendChild(group);
        });

        // Activate first field
        this.activateField(0);

        // Show/hide buttons
        this.dom.btnBack.style.display = this.currentStepIndex > 0 ? 'flex' : 'none';
        const isLastStep = this.currentStepIndex === this.totalSteps - 1;
        this.dom.btnNext.style.display = isLastStep ? 'none' : 'flex';
        this.dom.btnSubmit.style.display = isLastStep ? 'flex' : 'none';

        // Clear errors
        this.dom.errorsContainer.style.display = 'none';

        // Update indicator
        this.renderStepIndicator();
        this.updateProgressBar();
    }

    // ─── Create a Field Group DOM Element ───
    createFieldGroup(field, index) {
        const group = document.createElement('div');
        group.className = 'field-group';
        group.id = `field-${field.FieldId}`;
        group.dataset.fieldId = field.FieldId;
        group.dataset.index = index;

        const requiredStar = field.IsRequired ? '<span class="required-star">*</span>' : '';
        let inputHtml = '';

        switch (field.FieldType) {
            case 'password':
                inputHtml = `<input type="password" id="input-${field.FieldId}" name="${field.FieldId}"
                    placeholder="${field.Placeholder || ''}"
                    minlength="${field.MinLength}" maxlength="${field.MaxLength}"
                    ${field.IsRequired ? 'required' : ''} />
                    <div class="password-strength"><div class="bar" id="strength-${field.FieldId}"></div></div>`;
                break;

            case 'select':
                const options = (field.Options || [])
                    .map(o => `<option value="${o}">${o}</option>`)
                    .join('');
                inputHtml = `<select id="input-${field.FieldId}" name="${field.FieldId}"
                    ${field.IsRequired ? 'required' : ''}>
                    <option value="" disabled selected>— Select —</option>
                    ${options}
                </select>`;
                break;

            case 'checkbox':
                inputHtml = `<label style="display:flex;align-items:center;gap:10px;font-weight:400;">
                    <input type="checkbox" id="input-${field.FieldId}" name="${field.FieldId}"
                    style="width:20px;height:20px;" />
                    <span>${field.Label}</span>
                </label>`;
                break;

            case 'date':
                inputHtml = `<input type="date" id="input-${field.FieldId}" name="${field.FieldId}"
                    ${field.IsRequired ? 'required' : ''} />`;
                break;

            case 'tel':
                inputHtml = `<input type="tel" id="input-${field.FieldId}" name="${field.FieldId}"
                    placeholder="${field.Placeholder || ''}"
                    maxlength="${field.MaxLength}"
                    ${field.IsRequired ? 'required' : ''} />`;
                break;

            default:
                inputHtml = `<input type="${field.FieldType || 'text'}" id="input-${field.FieldId}" name="${field.FieldId}"
                    placeholder="${field.Placeholder || ''}"
                    minlength="${field.MinLength}" maxlength="${field.MaxLength}"
                    ${field.IsRequired ? 'required' : ''} />`;
        }

        group.innerHTML = `
            ${field.FieldType !== 'checkbox' ? `<label for="input-${field.FieldId}">${field.Label} ${requiredStar}</label>` : ''}
            ${inputHtml}
            <div class="field-error" id="error-${field.FieldId}"></div>
        `;

        // Password strength listener
        if (field.FieldType === 'password') {
            const input = group.querySelector('input');
            input.addEventListener('input', () => this.updatePasswordStrength(input.value, field.FieldId));
        }

        return group;
    }

    // ─── THE CORE: Activate a specific field ───
    activateField(index) {
        const fields = this.dom.fieldsContainer.querySelectorAll('.field-group');

        // Deactivate all
        fields.forEach(f => {
            f.classList.remove('active');
            f.querySelectorAll('input, select, textarea').forEach(el => {
                el.disabled = true;
            });
        });

        if (index >= fields.length) return;

        const activeGroup = fields[index];
        activeGroup.classList.add('active');

        // Enable the input inside
        const input = activeGroup.querySelector('input, select, textarea');
        if (input) {
            input.disabled = false;
            input.focus();
        }

        // Update help panel with field-specific info
        const fieldDef = this.currentStep.Fields[index];
        this.dom.helpPanel.style.display = 'block';
        this.dom.helpText.textContent = fieldDef.HelpText || '';
        this.dom.tipText.textContent = fieldDef.TipText || '';

        this.activeFieldIndex = index;
    }

    // ─── Handle Next (advance within step or to next step) ───
    async handleNext() {
        const fields = this.dom.fieldsContainer.querySelectorAll('.field-group');
        const fieldCount = this.currentStep.Fields.length;

        if (this.activeFieldIndex < fieldCount - 1) {
            // Move to next field within same step
            // Validate current field first
            const currentFieldId = this.currentStep.Fields[this.activeFieldIndex].FieldId;
            const isValid = await this.validateField(currentFieldId);
            if (isValid) {
                this.activateField(this.activeFieldIndex + 1);
            }
        } else {
            // All fields in step done → advance to next step
            await this.advanceStep();
        }
    }

    // ─── Handle Back ───
    async handleBack() {
        const fields = this.dom.fieldsContainer.querySelectorAll('.field-group');

        if (this.activeFieldIndex > 0) {
            // Go back to previous field within same step
            this.activateField(this.activeFieldIndex - 1);
        } else {
            // Go back to previous step
            const res = await fetch('/api/GuidedProcess/back', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ sessionToken: this.sessionToken })
            });
            const data = await res.json();
            if (data.CurrentStep) {
                this.currentStepIndex = data.CurrentStepIndex;
                this.currentStep = data.CurrentStep;
                this.stepProgress = data.StepProgress;
                if (data.FieldValues) this.fieldValues = data.FieldValues;
                this.renderCurrentStep();
                // Restore saved values
                this.populateFields();
            }
        }
    }

    // ─── Advance to Next Step (server validation) ───
    async advanceStep() {
        // Collect all field values for this step
        const values = {};
        this.currentStep.Fields.forEach(f => {
            const input = document.getElementById(`input-${f.FieldId}`);
            if (input) {
                values[f.FieldId] = input.type === 'checkbox' ? input.checked : input.value;
            }
        });

        // Mark current fields as completed visually
        this.dom.fieldsContainer.querySelectorAll('.field-group').forEach(g => {
            g.classList.remove('active');
            g.classList.add('completed');
        });

        // Call server
        const res = await fetch('/api/GuidedProcess/advance', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                sessionToken: this.sessionToken,
                fieldValues: values
            })
        });

        const data = await res.json();

        if (!res.ok) {
            // Show errors
            this.showErrors(data.errors || []);
            // Re-activate the field with error
            const firstErrorField = (data.errors || [])[0];
            if (firstErrorField) {
                const idx = this.currentStep.Fields.findIndex(f => f.FieldId === firstErrorField.FieldId);
                if (idx >= 0) this.activateField(idx);
            }
            return;
        }

        // Save values
        Object.assign(this.fieldValues, values);

        // Check completion
        if (data.IsCompleted) {
            this.showSuccess(data.SuccessMessage);
            return;
        }

        // Advance
        this.currentStepIndex = data.CurrentStepIndex;
        this.currentStep = data.CurrentStep;
        this.stepProgress = data.StepProgress;
        this.renderCurrentStep();
    }

    // ─── Submit (final step) ───
    async handleSubmit() {
        this.dom.btnSubmit.disabled = true;
        this.dom.btnSubmit.innerHTML = '<i class="fa fa-spinner fa-spin"></i> Creating...';

        const values = {};
        this.currentStep.Fields.forEach(f => {
            const input = document.getElementById(`input-${f.FieldId}`);
            if (input) values[f.FieldId] = input.type === 'checkbox' ? input.checked : input.value;
        });

        const res = await fetch('/api/GuidedProcess/advance', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ sessionToken: this.sessionToken, fieldValues: values })
        });

        const data = await res.json();

        if (res.ok && data.IsCompleted) {
            this.showSuccess(data.SuccessMessage);
        } else {
            this.dom.btnSubmit.disabled = false;
            this.dom.btnSubmit.innerHTML = '<i class="fa fa-check"></i> Create Account';
            this.showErrors(data.errors || []);
        }
    }

    // ─── Client-side field validation ───
    async validateField(fieldId) {
        const input = document.getElementById(`input-${fieldId}`);
        const value = input ? (input.type === 'checkbox' ? (input.checked ? 'true' : '') : input.value) : '';

        // Quick client check
        const fieldDef = this.currentStep.Fields.find(f => f.FieldId === fieldId);
        if (fieldDef && fieldDef.IsRequired && !value) {
            this.showFieldError(fieldId, `${fieldDef.Label} is required.`);
            return false;
        }

        // Server validation
        const res = await fetch('/api/GuidedProcess/validate-field', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                sessionToken: this.sessionToken,
                fieldId: fieldId,
                value: value
            })
        });
        const data = await res.json();

        if (!data.isValid) {
            this.showFieldError(fieldId, data.errors[0]);
            return false;
        }

        this.clearFieldError(fieldId);
        return true;
    }

    // ─── UI Helpers ───
    showFieldError(fieldId, message) {
        const group = document.getElementById(`field-${fieldId}`);
        const errorEl = document.getElementById(`error-${fieldId}`);
        if (group) group.classList.add('error');
        if (errorEl) errorEl.textContent = message;
    }

    clearFieldError(fieldId) {
        const group = document.getElementById(`field-${fieldId}`);
        const errorEl = document.getElementById(`error-${fieldId}`);
        if (group) group.classList.remove('error');
        if (errorEl) errorEl.textContent = '';
    }

    showErrors(errors) {
        this.dom.errorsContainer.style.display = 'block';
        this.dom.errorsList.innerHTML = errors
            .map(e => `<li>${e.message || e.Message || e}</li>`)
            .join('');
    }

    showSuccess(message) {
        this.dom.successMessage.textContent = message || 'Process completed successfully!';
        this.dom.successOverlay.style.display = 'flex';
        this.dom.progressBar.style.width = '100%';
    }

    updatePasswordStrength(password, fieldId) {
        const bar = document.getElementById(`strength-${fieldId}`);
        if (!bar) return;

        let score = 0;
        if (password.length >= 8) score++;
        if (/[A-Z]/.test(password)) score++;
        if (/[a-z]/.test(password)) score++;
        if (/\d/.test(password)) score++;
        if (/[^A-Za-z\d]/.test(password)) score++;

        const pct = (score / 5) * 100;
        bar.style.width = `${pct}%`;
        bar.style.background = score <= 2 ? '#ef4444' : score <= 3 ? '#f59e0b' : '#10b981';
    }

    populateFields() {
        Object.entries(this.fieldValues).forEach(([key, val]) => {
            const input = document.getElementById(`input-${key}`);
            if (input) {
                if (input.type === 'checkbox') input.checked = val === true || val === 'true';
                else input.value = val || '';
            }
        });
    }
}

// ─── Bootstrap ───
