function highlight(code, lang, marks){
  const pats = LANGS[lang] || [];
  if(!pats.length) return escapeHtml(code);
  const combined = new RegExp(pats.map(p=>'('+p[1]+')').join('|'), 'gm');
  const markSet = new Set(marks || []);
  let out = '', last = 0, m;
  while((m = combined.exec(code))){
    out += escapeHtml(code.slice(last, m.index));
    let cls = 'kw';
    for(const p of pats){
      if(new RegExp('^'+p[1]).test(code.slice(m.index))){ cls = p[0]; break; }
    }
    let tok;
    if(markSet.size){
      tok = '';
      for(let i=0;i<m[0].length;i++){
        const gi = m.index + i;
        tok += markSet.has(gi) ? '<span class="bm">'+escapeHtml(m[0][i])+'</span>' : escapeHtml(m[0][i]);
      }
    } else tok = escapeHtml(m[0]);
    out += '<span class="tk-'+cls+'">'+tok+'</span>';
    last = m.index + m[0].length;
    if(!m[0].length) combined.lastIndex++;
  }
  return out + escapeHtml(code.slice(last));
}

