let previewOn = false, bracketMarks = null, saveTimer = null;

function save(silent){
  if(state.active && state.files[state.active]) state.files[state.active].content = ta.value;
  try{ localStorage.setItem('novapad', JSON.stringify(state)); }catch(e){}
  const el = $('#save-state');
  el.textContent = '✓ Saved ' + new Date().toLocaleTimeString();
  el.className = 'item ok';
  if(!silent) toast('Saved to browser storage');
}
function markDirty(){
  const el = $('#save-state');
  el.textContent = '● Unsaved changes'; el.className = 'item dirty';
}
function scheduleAutosave(){
  markDirty();
  clearTimeout(saveTimer);
  saveTimer = setTimeout(()=>save(true), 1200);
}
function load(){
  try{
    const s = JSON.parse(localStorage.getItem('novapad'));
    if(s && s.files && Object.keys(s.files).length){ Object.assign(state, s); return true; }
  }catch(e){}
  return false;
}

/* ================= TABS ================= */
function newTab(name, content, lang){
  const id = nid();
  state.files[id] = { name: name || 'untitled-'+(state.order.length+1),
                       content: content ?? '', lang: lang || 'javascript' };
  state.order.push(id);
  switchTab(id); renderTabs(); save(true);
  return id;
}
function closeTab(id){
  state.order = state.order.filter(x => x !== id);
  delete state.files[id];
  if(state.active === id){
    state.active = state.order[state.order.length-1] || null;
    if(state.active) switchTab(state.active);
    else { ta.value = ''; renderAll(); }
  }
  renderTabs(); save(true);
}
function switchTab(id){
  if(state.active && state.files[state.active]) state.files[state.active].content = ta.value;
  state.active = id;
  const f = state.files[id];
  ta.value = f.content;
  $('#lang').value = f.lang;
  previewOn = false; $('#preview').classList.remove('on');
  renderAll();
}
function renderTabs(){
  const bar = $('#tabs'); bar.innerHTML = '';
  state.order.forEach(id => {
    const f = state.files[id];
    const t = document.createElement('div');
    t.className = 'tab' + (id === state.active ? ' active' : '');
    t.innerHTML = '<span class="tab-name">'+escapeHtml(f.name)+'</span><button class="tab-close" title="Close tab">×</button>';
    t.onclick = e => e.target.classList.contains('tab-close') ? closeTab(id) : switchTab(id);
    t.ondblclick = e => {
      if(e.target.classList.contains('tab-close')) return;
      const n = prompt('Rename file:', f.name);
      if(n && n.trim()){ f.name = n.trim(); renderTabs(); save(true); }
    };
    bar.appendChild(t);
  });
}

/* ================= RENDER ================= */
function currentLang(){ return state.files[state.active] ? state.files[state.active].lang : 'plain'; }
function lineHeight(){ return parseFloat(getComputedStyle(ta).lineHeight) || 22; }

function renderAll(){
  const code = ta.value, lang = currentLang();
  hl.innerHTML = highlight(code, lang, bracketMarks) + '\n';
  // line numbers
  const n = code.split('\n').length;
  let s = '';
  for(let i=1;i<=n;i++) s += i + '\n';
  lnEl.textContent = s;
  lnEl.parentElement.style.width = (String(n).length * 0.65 + 2) + 'ch';
  // status
  const pos = ta.selectionStart, upto = code.slice(0, pos);
  $('#st-ln').textContent = upto.split('\n').length;
  $('#st-col').textContent = pos - upto.lastIndexOf('\n');
  $('#st-lines').textContent = n;
  $('#st-words').textContent = (code.match(/\S+/g) || []).length;
  $('#st-chars').textContent = code.length;
  $('#st-lang').textContent = $('#lang').selectedOptions[0].text;
  if(previewOn && lang === 'markdown') renderPreview();
  syncScroll();
}
function syncScroll(){
  const hlEl = $('#highlight');
  hlEl.scrollTop = ta.scrollTop; hlEl.scrollLeft = ta.scrollLeft;
  lnEl.parentElement.scrollTop = ta.scrollTop;
}
ta.addEventListener('scroll', syncScroll);

/* ================= BRACKET MATCHING ================= */
function findMatch(v, i, isClose){
  const ch = v[i];
  const oi = '([{'.indexOf(ch), ci = ')]}'.indexOf(ch);
  if(oi === -1 && ci === -1) return -1;
  const o = oi !== -1 ? oi : ci, oCh = '([{'[o], cCh = ')]}'[o];
  let depth = 0;
  for(let j = i; j >= 0 && j < v.length; j += isClose ? -1 : 1){
    if(v[j] === cCh) depth++;
    else if(v[j] === oCh && --depth === 0) return j;
  }
  return -1;
}
function updateBracketMarks(){
  bracketMarks = null;
  const s = ta.selectionStart, v = ta.value;
  let a = -1, b = -1;
  if('([{'.includes(v[s-1])){ a = s-1; b = findMatch(v, a, false); }
  else if(')]}'.includes(v[s])){ b = s; a = findMatch(v, b, true); }
  if(a >= 0 && b >= 0) bracketMarks = [a, b];
  renderAll();
}

/* ================= EDITING ================= */
const PAIRS = {'(':')','[':']','{':'}','"':'"',"'":"'",'`':'`'};

ta.addEventListener('input', () => {
  if(state.active && state.files[state.active]) state.files[state.active].content = ta.value;
  renderAll(); scheduleAutosave();
});
ta.addEventListener('keyup',  updateBracketMarks);
ta.addEventListener('click',  updateBracketMarks);

ta.addEventListener('keydown', e => {
  const mod = e.ctrlKey || e.metaKey;
  if(mod && !e.altKey && e.key.toLowerCase() === 's'){ e.preventDefault(); e.shiftKey ? exportFile() : save(); return; }
  if(mod && e.key.toLowerCase() === 'f'){ e.preventDefault(); openFind(false); return; }
  if(mod && e.key.toLowerCase() === 'h'){ e.preventDefault(); openFind(true); return; }
  if(mod && e.key.toLowerCase() === 'o'){ e.preventDefault(); $('#file-input').click(); return; }
  if(mod && e.key.toLowerCase() === 'p'){ e.preventDefault(); doPrint(); return; }
  if(mod && e.key.toLowerCase() === 'g'){ e.preventDefault(); goToLine(); return; }
  if(mod && e.key.toLowerCase() === 'd'){ e.preventDefault(); duplicateLine(); return; }
  if(mod && e.key === '/'){ e.preventDefault(); toggleComment(); return; }
  if(mod && e.altKey && e.key.toLowerCase() === 'n'){ e.preventDefault(); newTab(); return; }

  if(e.key === 'Tab'){
    e.preventDefault(); e.shiftKey ? outdent() : indent(); return;
  }
  if(e.key === 'Enter'){
    e.preventDefault();
    const s = ta.selectionStart;
    const ls = ta.value.lastIndexOf('\n', s-1) + 1;
    const indent = (ta.value.slice(ls, s).match(/^\s*/) || [''])[0];
    const extra = ['{','[','(',':'].includes(ta.value[s-1]) ? '  ' : '';
    ta.setRangeText('\n' + indent + extra, s, ta.selectionEnd, 'end');
    ta.dispatchEvent(new Event('input')); return;
  }
  if(e.key === 'Backspace' && ta.selectionStart === ta.selectionEnd && ta.selectionStart > 0){
    const p = ta.value[ta.selectionStart-1], n = ta.value[ta.selectionStart];
    if(PAIRS[p] === n){
      e.preventDefault();
      ta.setRangeText('', ta.selectionStart-1, ta.selectionStart+1, 'end');
      ta.dispatchEvent(new Event('input')); return;
    }
  }
  if(PAIRS[e.key] && !e.shiftKey && !e.altKey && !mod){
    e.preventDefault();
    const s = ta.selectionStart, en = ta.selectionEnd;
    if(ta.value[s] === PAIRS[e.key]){ ta.setSelectionRange(s+1, s+1); return; }
    const sel = ta.value.slice(s, en);
    ta.setRangeText(e.key + PAIRS[e.key], s, en, 'end');
    ta.setSelectionRange(s+1, s+1+sel.length);
    ta.dispatchEvent(new Event('input'));
  }
});

function indent(){
  const s = ta.selectionStart, e = ta.selectionEnd;
  const ls = ta.value.lastIndexOf('\n', s-1) + 1;
  let le = ta.value.indexOf('\n', e); if(le === -1) le = ta.value.length;
  ta.setRangeText(ta.value.slice(ls, le).split('\n').map(l => '  ' + l).join('\n'), ls, le, 'select');
  ta.dispatchEvent(new Event('input'));
}
function outdent(){
  const s = ta.selectionStart, e = ta.selectionEnd;
  const ls = ta.value.lastIndexOf('\n', s-1) + 1;
  let le = ta.value.indexOf('\n', e); if(le === -1) le = ta.value.length;
  ta.setRangeText(ta.value.slice(ls, le).split('\n').map(l => l.replace(/^ {1,2}/,'')).join('\n'), ls, le, 'select');
  ta.dispatchEvent(new Event('input'));
}
function toggleComment(){
  const lang = currentLang();
  let prefix = '//', block = null;
  if(lang === 'python') prefix = '#';
  if(lang === 'css') block = ['/*','*/'];
  if(lang === 'html' || lang === 'markdown') block = ['<!--','-->'];
  const s = ta.selectionStart, e = ta.selectionEnd;
  const ls = ta.value.lastIndexOf('\n', s-1) + 1;
  let le = ta.value.indexOf('\n', e); if(le === -1) le = ta.value.length;
  const lines = ta.value.slice(ls, le).split('\n');
  let out;
  if(block){
    const [o,c] = block;
    if(lines[0].startsWith(o) && lines[lines.length-1].endsWith(c))
      out = [lines[0].slice(o.length), ...lines.slice(1,-1), lines[lines.length-1].slice(0,-c.length)];
    else out = [o + ' ' + lines[0], ...lines.slice(1), c];
  } else {
    const all = lines.every(l => l.trim().startsWith(prefix));
    out = lines.map(l => all ? l.replace(new RegExp('^\\s*'+prefix+'\\s?'),'') : prefix + l);
  }
  ta.setRangeText(out.join('\n'), ls, le, 'select');
  ta.dispatchEvent(new Event('input'));
}
function duplicateLine(){
  const s = ta.selectionStart;
  const ls = ta.value.lastIndexOf('\n', s-1) + 1;
  let le = ta.value.indexOf('\n', s); if(le === -1) le = ta.value.length;
  ta.setRangeText(ta.value.slice(ls, le), le, le, 'end');
  ta.dispatchEvent(new Event('input'));
}
function goToLine(){
  const n = parseInt(prompt('Go to line:'), 10);
  if(!n || n < 1) return;
  const lines = ta.value.split('\n');
  const idx = Math.min(n, lines.length);
  let pos = 0;
  for(let i=0;i<idx-1;i++) pos += lines[i].length + 1;
  ta.setSelectionRange(pos, pos + lines[idx-1].length);
  ta.focus();
  ta.scrollTop = Math.max(0, (idx-1) * lineHeight() - ta.clientHeight/2);
  renderAll();
}

/* ================= FIND & REPLACE ================= */
const findbar = $('#findbar');
function openFind(showReplace){
  findbar.classList.add('open');
  $('#replace-row').style.display = showReplace ? 'flex' : 'none';
  $('#find').focus(); $('#find').select();
}
function getRe(){
  const q = $('#find').value;
  if(!q) return null;
  let src = $('#re').checked ? q : escapeRe(q);
  if($('#whole').checked) src = '\\b' + src + '\\b';
  try{ return new RegExp(src, 'gm' + ($('#cs').checked ? '' : 'i')); }
  catch(err){ toast('⚠ Invalid regex'); return null; }
}
function findNext(fwd){
  const re = getRe(); if(!re) return;
  const v = ta.value, matches = []; let m;
  re.lastIndex = 0;
  while((m = re.exec(v))){ matches.push({i:m.index, l:m[0].length}); if(!m[0].length) re.lastIndex++; }
  $('#find-count').textContent = matches.length ? matches.length + ' match' + (matches.length>1?'es':'') : '0 matches';
  if(!matches.length) return;
  const pos = fwd ? ta.selectionStart : ta.selectionEnd;
  let hit;
  if(fwd){ hit = matches.find(x => x.i >= pos) || matches[0]; }
  else {
    const before = matches.filter(x => x.i < pos);
    hit = before.length ? before[before.length-1] : matches[matches.length-1];
  }
  ta.focus();
  ta.setSelectionRange(hit.i, hit.i + hit.l);
  const line = v.slice(0, hit.i).split('\n').length;
  ta.scrollTop = Math.max(0, (line-1) * lineHeight() - ta.clientHeight/3);
  renderAll();
}
function replaceOne(){
  const re = getRe(); if(!re) return;
  const v = ta.value, s = ta.selectionStart, e = ta.selectionEnd;
  const q = $('#find').value;
  if(e - s === q.length && v.slice(s, e) === q){
    ta.setRangeText($('#replace').value, s, e, 'end');
    ta.dispatchEvent(new Event('input'));
  }
  findNext(true);
}
function replaceAll(){
  const re = getRe(); if(!re) return;
  const rep = $('#replace').value.replace(/\$&/g, '\\$&');
  let count = 0;
  ta.value = ta.value.replace(re, () => { count++; return rep; });
  ta.dispatchEvent(new Event('input'));
  toast(count + ' replacement' + (count!==1?'s':'') + ' made');
}
$('#f-next').onclick = () => findNext(true);
$('#f-prev').onclick = () => findNext(false);
$('#f-rep').onclick = replaceOne;
$('#f-repall').onclick = replaceAll;
$('#f-close').onclick = () => findbar.classList.remove('open');
$('#find').addEventListener('keydown', e => {
  if(e.key === 'Enter'){ e.preventDefault(); findNext(!e.shiftKey); }
  if(e.key === 'Escape') findbar.classList.remove('open');
});
$('#replace').addEventListener('keydown', e => {
  if(e.key === 'Enter') replaceOne();
  if(e.key === 'Escape') findbar.classList.remove('open');
});

/* ================= FILES ================= */
function exportFile(){
  const f = state.files[state.active]; if(!f) return;
  const exts = {javascript:'.js', python:'.py', css:'.css', html:'.html', json:'.json', markdown:'.md', plain:'.txt'};
  const name = f.name.replace(/\.[^.]+$/,'') + (exts[f.lang] || '.txt');
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([ta.value], {type:'text/plain'}));
  a.download = name; a.click(); URL.revokeObjectURL(a.href);
  toast('Exported ' + name);
}
function openFile(file){
  const r = new FileReader();
  r.onload = () => {
    const ext = (file.name.split('.').pop() || '').toLowerCase();
    const map = {js:'javascript', mjs:'javascript', ts:'javascript', jsx:'javascript', py:'python',
                 css:'css', html:'html', htm:'html', json:'json', md:'markdown', markdown:'markdown', txt:'plain'};
    newTab(file.name, r.result, map[ext] || 'plain');
    toast('Opened ' + file.name);
  };
  r.readAsText(file);
}
$('#file-input').onchange = e => { if(e.target.files[0]) openFile(e.target.files[0]); e.target.value = ''; };
window.addEventListener('dragover', e => { e.preventDefault(); document.body.classList.add('dragging'); });
window.addEventListener('dragleave', e => { if(!e.relatedTarget) document.body.classList.remove('dragging'); });
window.addEventListener('drop', e => {
  e.preventDefault(); document.body.classList.remove('dragging');
  if(e.dataTransfer.files[0]) openFile(e.dataTransfer.files[0]);
});
function doPrint(){
  $('#print-area').textContent = ta.value;
  window.print();
}

/* ================= MARKDOWN PREVIEW ================= */
function inlineMd(s){
  s = escapeHtml(s);
  s = s.replace(/`([^`]+)`/g, '<code>$1</code>');
  s = s.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img alt="$1" src="$2">');
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  s = s.replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>');
  s = s.replace(/~~([^~]+)~~/g, '<del>$1</del>');
  return s;
}
function mdToHtml(md){
  const blocks = [];
  md = md.replace(/```[^\n]*\n([\s\S]*?)```/g, (m, c) => {
    blocks.push('<pre class="mdcode"><code>' + escapeHtml(c) + '</code></pre>');
    return '\u0000' + (blocks.length-1) + '\u0000';
  });
  let html = '', list = null, quote = false;
  const closeAll = () => { if(list){ html += '</' + list + '>'; list = null; } if(quote){ html += '</blockquote>'; quote = false; } };
  for(const line of md.split('\n')){
    if(/^\s*$/.test(line)){ closeAll(); continue; }
    let m;
    if(m = line.match(/^(#{1,6})\s+(.*)/)){ closeAll(); html += '<h'+m[1].length+'>'+inlineMd(m[2])+'</h'+m[1].length+'>'; continue; }
    if(/^(-{3,}|\*{3,})\s*$/.test(line)){ closeAll(); html += '<hr>'; continue; }
    if(m = line.match(/^>\s?(.*)/)){ if(!quote){ closeAll(); html += '<blockquote>'; quote = true; } html += '<p>'+inlineMd(m[1])+'</p>'; continue; }
    if(quote){ html += '</blockquote>'; quote = false; }
    if(m = line.match(/^\s*[-*+]\s+(.*)/)){ if(list !== 'ul'){ closeAll(); html += '<ul>'; list = 'ul'; } html += '<li>'+inlineMd(m[1])+'</li>'; continue; }
    if(m = line.match(/^\s*\d+\.\s+(.*)/)){ if(list !== 'ol'){ closeAll(); html += '<ol>'; list = 'ol'; } html += '<li>'+inlineMd(m[1])+'</li>'; continue; }
    closeAll(); html += '<p>'+inlineMd(line)+'</p>';
  }
  closeAll();
  return html.replace(/\u0000(\d+)\u0000/g, (m, i) => blocks[i]);
}
function renderPreview(){ $('#preview').innerHTML = mdToHtml(ta.value); }

/* ================= TOOLBAR ================= */
$('#btn-new').onclick = () => newTab();
$('#btn-open').onclick = () => $('#file-input').click();
$('#btn-save').onclick = () => save();
$('#btn-export').onclick = exportFile;
$('#btn-print').onclick = doPrint;
$('#btn-copy').onclick = () => { navigator.clipboard.writeText(ta.value).then(() => toast('Copied to clipboard')); };
$('#btn-find').onclick = () => openFind(findbar.classList.contains('open'));
$('#btn-comment').onclick = toggleComment;
$('#btn-wrap').onclick = () => {
  state.wrap = !state.wrap;
  document.body.classList.toggle('wrap', state.wrap);
  $('#btn-wrap').classList.toggle('active', state.wrap);
  save(true);
};
function setFont(px){
  state.fontSize = Math.min(32, Math.max(10, px));
  document.documentElement.style.setProperty('--ed-font', state.fontSize + 'px');
  save(true); renderAll();
}
$('#btn-font-up').onclick = () => setFont(state.fontSize + 1);
$('#btn-font-down').onclick = () => setFont(state.fontSize - 1);
$('#btn-theme').onclick = () => {
  state.theme = state.theme === 'dark' ? 'light' : 'dark';
  document.documentElement.dataset.theme = state.theme;
  $('#btn-theme').textContent = state.theme === 'dark' ? '🌙' : '☀️';
  save(true);
};
$('#btn-preview').onclick = () => {
  if(currentLang() !== 'markdown'){ toast('Switch language to Markdown to preview'); return; }
  previewOn = !previewOn;
  $('#preview').classList.toggle('on', previewOn);
  $('#btn-preview').classList.toggle('active', previewOn);
  if(previewOn) renderPreview();
};
$('#btn-zen').onclick = () => document.body.classList.add('zen');
$('#zen-exit').onclick = () => document.body.classList.remove('zen');
$('#btn-help').onclick = () => $('#modal').classList.add('open');
$('#modal').onclick = e => { if(e.target.id === 'modal') e.target.classList.remove('open'); };
$('#lang').onchange = e => {
  if(!state.active) return;
  state.files[state.active].lang = e.target.value;
  renderAll(); save(true);
};
window.addEventListener('keydown', e => {
  if(e.key === 'Escape'){
    document.body.classList.remove('zen');
    $('#modal').classList.remove('open');
    findbar.classList.remove('open');
  }
});
window.addEventListener('beforeunload', () => save(true));

/* ================= INIT ================= */
const WELCOME = `// ✨ NovaPad — Advanced Notepad
